DO $suno_scope$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM users WHERE id='1e56fd95-56af-4aca-b50f-89a48c083249'::uuid)
 OR (SELECT count(*) FROM pages WHERE fb_page_id IN ('540901085777059','697291860141214','606945225824770','505255682680407','600867369770679','533584419840779','492160583990696','663521640185928','552094384656613','558841917314834','551256468065614','1108946172305214','573992485795257'))<>13 THEN
  RAISE EXCEPTION 'This review upgrade is bound to the retained Suno owner and thirteen Suno Pages';
 END IF;
END $suno_scope$;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
