-- FILE: 202610180001_chatbot_reply_inbound_timestamp.sql SHA256: a0ebaa1090d78761dc5134d5f21d04b4602fe5c955a3644675e148960af8568e

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='20s';
