-- FILE: 202611020004_contact_profiles.sql SHA256: 62d65df17c9ffd0c1b2a065024dc1627390eb235687b364668ad20a72bab60b0

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';

CREATE TABLE IF NOT EXISTS public.contact_profile_jobs (
    contact_id UUID PRIMARY KEY REFERENCES public.contacts(id) ON DELETE CASCADE,
    page_id UUID NOT NULL REFERENCES public.pages(id) ON DELETE CASCADE,
    status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','processing','ready','failed')),
    reason TEXT NOT NULL DEFAULT 'profile_open',
    requested_version INTEGER NOT NULL DEFAULT 1,
    working_version INTEGER,
    claim_token UUID,
    lease_until TIMESTAMPTZ,
    next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    attempt_count INTEGER NOT NULL DEFAULT 0,
    source_cutoff_at TIMESTAMPTZ,
    scan_cursor TEXT,
    scan_started BOOLEAN NOT NULL DEFAULT FALSE,
    history_complete BOOLEAN NOT NULL DEFAULT FALSE,
    message_count INTEGER NOT NULL DEFAULT 0,
    analyzed_count INTEGER NOT NULL DEFAULT 0,
    partial_analysis JSONB NOT NULL DEFAULT '[]'::jsonb,
    error_message TEXT,
    requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_contact_profile_jobs_due ON public.contact_profile_jobs(next_attempt_at,requested_at)
    WHERE status IN ('queued','processing');

CREATE TABLE IF NOT EXISTS public.contact_profile_messages (
    contact_id UUID NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    page_id UUID NOT NULL REFERENCES public.pages(id) ON DELETE CASCADE,
    generation INTEGER NOT NULL,
    message_id TEXT NOT NULL,
    sent_at TIMESTAMPTZ NOT NULL,
    sender TEXT NOT NULL CHECK(sender IN ('customer','page','unknown')),
    text TEXT NOT NULL DEFAULT '',
    attachment_count INTEGER NOT NULL DEFAULT 0,
    image_count INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY(contact_id,generation,message_id)
);
CREATE INDEX IF NOT EXISTS idx_contact_profile_messages_time ON public.contact_profile_messages(contact_id,generation,sent_at,message_id);

CREATE TABLE IF NOT EXISTS public.contact_profile_snapshots (
    contact_id UUID NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    page_id UUID NOT NULL REFERENCES public.pages(id) ON DELETE CASCADE,
    generation INTEGER NOT NULL,
    source_cutoff_at TIMESTAMPTZ NOT NULL,
    message_count INTEGER NOT NULL,
    model TEXT NOT NULL,
    payload JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY(contact_id,generation)
);

CREATE TABLE IF NOT EXISTS public.contact_purchases (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    request_id UUID NOT NULL UNIQUE,
    page_id UUID NOT NULL REFERENCES public.pages(id) ON DELETE CASCADE,
    contact_id UUID NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    description TEXT NOT NULL CHECK(length(btrim(description)) BETWEEN 1 AND 500),
    total_minor BIGINT NOT NULL CHECK(total_minor>0 AND total_minor<=1000000000000),
    currency TEXT NOT NULL DEFAULT 'PHP' CHECK(currency ~ '^[A-Z]{3}$'),
    purchased_at TIMESTAMPTZ NOT NULL,
    reference TEXT,
    recorded_by UUID NOT NULL REFERENCES public.users(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_contact_purchases_scope ON public.contact_purchases(page_id,contact_id,purchased_at);

CREATE TABLE IF NOT EXISTS public.contact_verified_payments (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    request_id UUID NOT NULL UNIQUE,
    page_id UUID NOT NULL REFERENCES public.pages(id) ON DELETE CASCADE,
    contact_id UUID NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    purchase_id UUID REFERENCES public.contact_purchases(id),
    kind TEXT NOT NULL CHECK(kind IN ('deposit','balance','full','refund')),
    amount_minor BIGINT NOT NULL CHECK(amount_minor>0 AND amount_minor<=1000000000000),
    currency TEXT NOT NULL DEFAULT 'PHP' CHECK(currency ~ '^[A-Z]{3}$'),
    occurred_at TIMESTAMPTZ NOT NULL,
    reference TEXT NOT NULL CHECK(length(btrim(reference)) BETWEEN 3 AND 160),
    evidence_message_id TEXT,
    evidence_quote TEXT,
    note TEXT NOT NULL DEFAULT '',
    verified_by UUID NOT NULL REFERENCES public.users(id),
    verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    voided_at TIMESTAMPTZ,
    voided_by UUID REFERENCES public.users(id),
    void_reason TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_contact_payment_reference ON public.contact_verified_payments(page_id,lower(btrim(reference))) WHERE voided_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_contact_payments_scope ON public.contact_verified_payments(page_id,contact_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_outbound_events_contact_profile ON public.outbound_message_events(page_id,contact_id,sent_at);
CREATE INDEX IF NOT EXISTS idx_ad_stage_contact_profile ON public.ad_lead_stage_events(page_id,contact_id,recorded_at);

CREATE OR REPLACE FUNCTION public.enqueue_contact_profile(p_page_id UUID,p_contact_id UUID,p_reason TEXT DEFAULT 'profile_open')
RETURNS public.contact_profile_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE result public.contact_profile_jobs;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.contacts WHERE id=p_contact_id AND page_id=p_page_id) THEN RAISE EXCEPTION 'Contact does not belong to Page'; END IF;
    IF p_reason NOT IN ('profile_open','stage_change','manual_refresh') THEN RAISE EXCEPTION 'Invalid refresh reason'; END IF;
    INSERT INTO public.contact_profile_jobs(contact_id,page_id,reason) VALUES(p_contact_id,p_page_id,p_reason)
    ON CONFLICT(contact_id) DO UPDATE SET
        requested_version=CASE WHEN p_reason='profile_open' AND contact_profile_jobs.status IN ('queued','processing','ready')
            THEN contact_profile_jobs.requested_version ELSE contact_profile_jobs.requested_version+1 END,
        status=CASE WHEN contact_profile_jobs.status='processing' AND contact_profile_jobs.lease_until>NOW() THEN 'processing'
            WHEN p_reason='profile_open' AND contact_profile_jobs.status='ready' THEN 'ready' ELSE 'queued' END,
        reason=EXCLUDED.reason,requested_at=NOW(),next_attempt_at=NOW(),attempt_count=0,error_message=NULL,updated_at=NOW()
    WHERE NOT(p_reason='profile_open' AND contact_profile_jobs.status IN ('queued','processing','ready'))
    RETURNING * INTO result;
    IF NOT FOUND THEN SELECT * INTO result FROM public.contact_profile_jobs WHERE contact_id=p_contact_id; END IF;
    RETURN result;
END; $$;

CREATE OR REPLACE FUNCTION public.queue_profile_after_meta_stage()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
    IF NEW.applied AND (TG_OP='INSERT' OR NOT OLD.applied) THEN
        PERFORM public.enqueue_contact_profile(NEW.page_id,NEW.contact_id,'stage_change');
    END IF;
    RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS queue_profile_after_meta_stage ON public.messenger_lead_stage_events;
CREATE TRIGGER queue_profile_after_meta_stage AFTER INSERT OR UPDATE OF applied ON public.messenger_lead_stage_events
    FOR EACH ROW EXECUTE FUNCTION public.queue_profile_after_meta_stage();

CREATE OR REPLACE FUNCTION public.claim_contact_profile_jobs(p_limit INTEGER DEFAULT 2,p_contact_id UUID DEFAULT NULL)
RETURNS SETOF public.contact_profile_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 5 THEN RAISE EXCEPTION 'Invalid profile batch size'; END IF;
    RETURN QUERY WITH due AS (
        SELECT j.contact_id FROM public.contact_profile_jobs j
        WHERE (p_contact_id IS NULL OR j.contact_id=p_contact_id) AND j.next_attempt_at<=NOW()
          AND (j.status='queued' OR (j.status='processing' AND j.lease_until<NOW()))
        ORDER BY j.requested_at LIMIT p_limit FOR UPDATE SKIP LOCKED
    ) UPDATE public.contact_profile_jobs j SET status='processing',claim_token=gen_random_uuid(),lease_until=NOW()+interval '4 minutes',
        working_version=j.requested_version,
        source_cutoff_at=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN NOW() ELSE coalesce(j.source_cutoff_at,NOW()) END,
        scan_cursor=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN NULL ELSE j.scan_cursor END,
        scan_started=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN FALSE ELSE j.scan_started END,
        history_complete=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN FALSE ELSE j.history_complete END,
        message_count=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN 0 ELSE j.message_count END,
        analyzed_count=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN 0 ELSE j.analyzed_count END,
        partial_analysis=CASE WHEN j.working_version IS DISTINCT FROM j.requested_version THEN '[]'::jsonb ELSE j.partial_analysis END,
        updated_at=NOW()
    FROM due WHERE j.contact_id=due.contact_id RETURNING j.*;
END; $$;

CREATE OR REPLACE FUNCTION public.save_contact_profile_progress(p_contact_id UUID,p_claim_token UUID,p_messages JSONB,p_progress JSONB)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE job public.contact_profile_jobs; message JSONB;
BEGIN
    SELECT * INTO job FROM public.contact_profile_jobs WHERE contact_id=p_contact_id AND claim_token=p_claim_token AND status='processing' FOR UPDATE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF jsonb_typeof(p_messages)<>'array' OR jsonb_array_length(p_messages)>100 THEN RAISE EXCEPTION 'Invalid message batch'; END IF;
    FOR message IN SELECT * FROM jsonb_array_elements(p_messages) LOOP
        IF length(coalesce(message->>'id','')) NOT BETWEEN 1 AND 2000 OR length(coalesce(message->>'text',''))>50000
            OR message->>'sender' NOT IN ('customer','page','unknown') THEN RAISE EXCEPTION 'Invalid source message'; END IF;
        INSERT INTO public.contact_profile_messages(contact_id,page_id,generation,message_id,sent_at,sender,text,attachment_count,image_count)
        VALUES(job.contact_id,job.page_id,job.working_version,message->>'id',(message->>'at')::timestamptz,message->>'sender',coalesce(message->>'text',''),coalesce((message->>'attachments')::integer,0),coalesce((message->>'images')::integer,0))
        ON CONFLICT(contact_id,generation,message_id) DO UPDATE SET text=EXCLUDED.text,sender=EXCLUDED.sender,attachment_count=EXCLUDED.attachment_count,image_count=EXCLUDED.image_count;
    END LOOP;
    UPDATE public.contact_profile_jobs SET
        scan_cursor=CASE WHEN p_progress ? 'scan_cursor' THEN p_progress->>'scan_cursor' ELSE scan_cursor END,
        scan_started=CASE WHEN p_progress ? 'scan_started' THEN (p_progress->>'scan_started')::boolean ELSE scan_started END,
        history_complete=CASE WHEN p_progress ? 'history_complete' THEN (p_progress->>'history_complete')::boolean ELSE history_complete END,
        analyzed_count=CASE WHEN p_progress ? 'analyzed_count' THEN (p_progress->>'analyzed_count')::integer ELSE analyzed_count END,
        partial_analysis=coalesce(p_progress->'partial_analysis',partial_analysis),
        message_count=(SELECT count(*) FROM public.contact_profile_messages WHERE contact_id=job.contact_id AND generation=job.working_version),updated_at=NOW()
    WHERE contact_id=job.contact_id;
    RETURN TRUE;
END; $$;

CREATE OR REPLACE FUNCTION public.finish_contact_profile_job(p_contact_id UUID,p_claim_token UUID,p_model TEXT,p_payload JSONB DEFAULT NULL,p_error TEXT DEFAULT NULL)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE job public.contact_profile_jobs;
BEGIN
    SELECT * INTO job FROM public.contact_profile_jobs WHERE contact_id=p_contact_id AND claim_token=p_claim_token AND status='processing' FOR UPDATE;
    IF NOT FOUND THEN RETURN FALSE; END IF;
    IF p_payload IS NOT NULL THEN
        IF NOT job.history_complete OR job.analyzed_count<job.message_count THEN RAISE EXCEPTION 'Cannot publish an incomplete conversation'; END IF;
        INSERT INTO public.contact_profile_snapshots(contact_id,page_id,generation,source_cutoff_at,message_count,model,payload)
        VALUES(job.contact_id,job.page_id,job.working_version,job.source_cutoff_at,job.message_count,p_model,p_payload)
        ON CONFLICT(contact_id,generation) DO NOTHING;
        DELETE FROM public.contact_profile_messages WHERE contact_id=job.contact_id AND generation<job.working_version-1;
    END IF;
    UPDATE public.contact_profile_jobs SET
        status=CASE WHEN requested_version>working_version THEN 'queued' WHEN p_payload IS NOT NULL THEN 'ready'
            WHEN p_error IS NOT NULL AND attempt_count+1>=3 THEN 'failed' ELSE 'queued' END,
        attempt_count=CASE WHEN p_error IS NULL THEN 0 ELSE attempt_count+1 END,
        next_attempt_at=CASE WHEN p_error IS NULL THEN NOW() ELSE NOW()+interval '5 minutes' END,
        claim_token=NULL,lease_until=NULL,error_message=left(p_error,600),updated_at=NOW()
    WHERE contact_id=job.contact_id;
    RETURN TRUE;
END; $$;

CREATE OR REPLACE FUNCTION public.record_contact_purchase(p_page_id UUID,p_contact_id UUID,p_actor_id UUID,p_request_id UUID,p_description TEXT,p_total_minor BIGINT,p_currency TEXT,p_purchased_at TIMESTAMPTZ,p_reference TEXT DEFAULT NULL)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE result public.contact_purchases;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.contacts WHERE id=p_contact_id AND page_id=p_page_id) OR NOT EXISTS(SELECT 1 FROM public.user_pages WHERE page_id=p_page_id AND user_id=p_actor_id) THEN RAISE EXCEPTION 'Page membership required'; END IF;
    IF p_purchased_at IS NULL OR p_purchased_at>NOW()+interval '5 minutes' OR p_purchased_at<'2000-01-01' THEN RAISE EXCEPTION 'Invalid purchase date'; END IF;
    INSERT INTO public.contact_purchases(request_id,page_id,contact_id,description,total_minor,currency,purchased_at,reference,recorded_by)
    VALUES(p_request_id,p_page_id,p_contact_id,btrim(p_description),p_total_minor,upper(p_currency),p_purchased_at,nullif(btrim(p_reference),''),p_actor_id)
    ON CONFLICT(request_id) DO NOTHING RETURNING * INTO result;
    IF NOT FOUND THEN SELECT * INTO result FROM public.contact_purchases WHERE request_id=p_request_id AND page_id=p_page_id AND contact_id=p_contact_id AND recorded_by=p_actor_id; END IF;
    IF result.id IS NULL THEN RAISE EXCEPTION 'Request belongs to another contact'; END IF;
    RETURN to_jsonb(result);
END; $$;

CREATE OR REPLACE FUNCTION public.record_contact_verified_payment(p_page_id UUID,p_contact_id UUID,p_actor_id UUID,p_request_id UUID,p_purchase_id UUID,p_kind TEXT,p_amount_minor BIGINT,p_currency TEXT,p_occurred_at TIMESTAMPTZ,p_reference TEXT,p_message_id TEXT DEFAULT NULL,p_note TEXT DEFAULT '')
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE result public.contact_verified_payments; quote TEXT;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.contacts WHERE id=p_contact_id AND page_id=p_page_id) OR NOT EXISTS(SELECT 1 FROM public.user_pages WHERE page_id=p_page_id AND user_id=p_actor_id) THEN RAISE EXCEPTION 'Page membership required'; END IF;
    IF p_occurred_at IS NULL OR p_occurred_at>NOW()+interval '5 minutes' OR p_occurred_at<'2000-01-01' OR length(p_note)>3000 THEN RAISE EXCEPTION 'Invalid payment details'; END IF;
    IF p_purchase_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contact_purchases WHERE id=p_purchase_id AND page_id=p_page_id AND contact_id=p_contact_id AND currency=upper(p_currency)) THEN RAISE EXCEPTION 'Purchase or currency does not match contact'; END IF;
    IF p_message_id IS NOT NULL THEN
        SELECT left(text,2000) INTO quote FROM public.contact_profile_messages WHERE contact_id=p_contact_id AND page_id=p_page_id AND message_id=p_message_id ORDER BY generation DESC LIMIT 1;
        IF NOT FOUND THEN RAISE EXCEPTION 'Evidence message not found'; END IF;
    END IF;
    INSERT INTO public.contact_verified_payments(request_id,page_id,contact_id,purchase_id,kind,amount_minor,currency,occurred_at,reference,evidence_message_id,evidence_quote,note,verified_by)
    VALUES(p_request_id,p_page_id,p_contact_id,p_purchase_id,p_kind,p_amount_minor,upper(p_currency),p_occurred_at,btrim(p_reference),p_message_id,quote,p_note,p_actor_id)
    ON CONFLICT(request_id) DO NOTHING RETURNING * INTO result;
    IF NOT FOUND THEN SELECT * INTO result FROM public.contact_verified_payments WHERE request_id=p_request_id AND page_id=p_page_id AND contact_id=p_contact_id AND verified_by=p_actor_id; END IF;
    IF result.id IS NULL THEN RAISE EXCEPTION 'Request belongs to another contact'; END IF;
    RETURN to_jsonb(result);
END; $$;

CREATE OR REPLACE FUNCTION public.void_contact_verified_payment(p_page_id UUID,p_contact_id UUID,p_payment_id UUID,p_actor_id UUID,p_reason TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.user_pages WHERE page_id=p_page_id AND user_id=p_actor_id) OR length(btrim(p_reason)) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION 'Membership and correction reason required'; END IF;
    UPDATE public.contact_verified_payments SET voided_at=NOW(),voided_by=p_actor_id,void_reason=btrim(p_reason)
    WHERE id=p_payment_id AND page_id=p_page_id AND contact_id=p_contact_id AND voided_at IS NULL;
    RETURN FOUND;
END; $$;

CREATE OR REPLACE FUNCTION public.get_contact_finance_records(p_page_id UUID,p_contact_id UUID)
RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
    SELECT jsonb_build_object(
        'purchases',coalesce((SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object('recorded_by_name',u.name) ORDER BY p.purchased_at,p.id)
            FROM public.contact_purchases p JOIN public.users u ON u.id=p.recorded_by WHERE p.page_id=p_page_id AND p.contact_id=p_contact_id),'[]'::jsonb),
        'payments',coalesce((SELECT jsonb_agg(to_jsonb(p)||jsonb_build_object('verified_by_name',u.name) ORDER BY p.occurred_at,p.id)
            FROM public.contact_verified_payments p JOIN public.users u ON u.id=p.verified_by WHERE p.page_id=p_page_id AND p.contact_id=p_contact_id),'[]'::jsonb)
    );
$$;

ALTER TABLE public.contact_profile_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_profile_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_profile_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_verified_payments ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.contact_profile_jobs,public.contact_profile_messages,public.contact_profile_snapshots,public.contact_purchases,public.contact_verified_payments FROM anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contact_profile_jobs,public.contact_profile_messages,public.contact_profile_snapshots TO service_role;
GRANT SELECT ON public.contact_purchases,public.contact_verified_payments TO service_role;
REVOKE ALL ON FUNCTION public.enqueue_contact_profile(UUID,UUID,TEXT),public.queue_profile_after_meta_stage(),public.claim_contact_profile_jobs(INTEGER,UUID),
    public.save_contact_profile_progress(UUID,UUID,JSONB,JSONB),public.finish_contact_profile_job(UUID,UUID,TEXT,JSONB,TEXT),
    public.record_contact_purchase(UUID,UUID,UUID,UUID,TEXT,BIGINT,TEXT,TIMESTAMPTZ,TEXT),
    public.record_contact_verified_payment(UUID,UUID,UUID,UUID,UUID,TEXT,BIGINT,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT),
    public.void_contact_verified_payment(UUID,UUID,UUID,UUID,TEXT),public.get_contact_finance_records(UUID,UUID) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.enqueue_contact_profile(UUID,UUID,TEXT),public.claim_contact_profile_jobs(INTEGER,UUID),
    public.save_contact_profile_progress(UUID,UUID,JSONB,JSONB),public.finish_contact_profile_job(UUID,UUID,TEXT,JSONB,TEXT),
    public.record_contact_purchase(UUID,UUID,UUID,UUID,TEXT,BIGINT,TEXT,TIMESTAMPTZ,TEXT),
    public.record_contact_verified_payment(UUID,UUID,UUID,UUID,UUID,TEXT,BIGINT,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT),
    public.void_contact_verified_payment(UUID,UUID,UUID,UUID,TEXT),public.get_contact_finance_records(UUID,UUID) TO service_role;
-- Existing observed Meta decisions receive the same review as future changes.
INSERT INTO public.contact_profile_jobs(contact_id,page_id,reason)
SELECT DISTINCT contact_id,page_id,'stage_change' FROM public.messenger_lead_stage_events
WHERE applied AND observed_at>NOW()-interval '7 days'
ON CONFLICT(contact_id) DO NOTHING;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611020004_contact_profiles.sql','62d65df17c9ffd0c1b2a065024dc1627390eb235687b364668ad20a72bab60b0');

-- FILE: 202611020005_ad_calendar.sql SHA256: 878ec1bfdb3907a12c06c9325e30d49c0a405c408014c1a3c62f6d4479bc5fe8

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';

ALTER TABLE public.ad_daily_spend
 ADD COLUMN IF NOT EXISTS reach BIGINT,
 ADD COLUMN IF NOT EXISTS link_clicks BIGINT,
 ADD COLUMN IF NOT EXISTS messaging_started NUMERIC(20,6),
 ADD COLUMN IF NOT EXISTS video_plays NUMERIC(20,6),
 ADD COLUMN IF NOT EXISTS video_thruplays NUMERIC(20,6),
 ADD COLUMN IF NOT EXISTS video_complete NUMERIC(20,6),
 ADD COLUMN IF NOT EXISTS action_report_time TEXT,
 ADD COLUMN IF NOT EXISTS attribution_setting TEXT,
 ADD COLUMN IF NOT EXISTS report_complete BOOLEAN NOT NULL DEFAULT FALSE,
 ADD COLUMN IF NOT EXISTS reported_zero BOOLEAN NOT NULL DEFAULT FALSE;
CREATE INDEX IF NOT EXISTS idx_calendar_meta_converted ON public.messenger_lead_stage_events(page_id,contact_id,occurred_at) WHERE applied AND stage='converted';
CREATE INDEX IF NOT EXISTS idx_calendar_crm_converted ON public.ad_lead_stage_events(page_id,contact_id,stage_timestamp) WHERE stage='converted';

-- Inquiry dates select the cohort. Outcomes and receipts are deliberately NOT
-- restricted to the inquiry month, so later conversions update their original day.
CREATE OR REPLACE FUNCTION public.ad_calendar_cohort(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' AS $$
BEGIN
 IF p_page_ids IS NULL OR cardinality(p_page_ids)>50 OR p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '32 days'
 OR (p_ad_id IS NOT NULL AND p_ad_id<>'unknown' AND p_ad_id !~ '^[0-9]{1,100}$') THEN RAISE EXCEPTION 'Invalid calendar scope'; END IF;
 RETURN QUERY WITH keys AS MATERIALIZED (
  SELECT s.contact_id,s.page_id,CASE WHEN s.attribution_status='verified_inline' THEN s.origin_ad_id END AS ad_id,s.first_inquiry_at,s.inquiry_basis
  FROM public.ad_contact_sources s WHERE s.page_id=ANY(p_page_ids) AND s.first_inquiry_at>=p_from AND s.first_inquiry_at<least(p_to,statement_timestamp())
  UNION ALL
  SELECT c.id,c.page_id,NULL::text,c.first_interaction_at,'legacy_recorded'::text FROM public.contacts c
  WHERE c.page_id=ANY(p_page_ids) AND c.first_interaction_at>=p_from AND c.first_interaction_at<least(p_to,statement_timestamp())
  AND NOT EXISTS(SELECT 1 FROM public.ad_contact_sources s WHERE s.contact_id=c.id AND s.page_id=c.page_id)
 ), chosen AS MATERIALIZED (
  SELECT k.*,c.name,c.psid,c.pipeline_stage FROM keys k JOIN public.contacts c ON c.id=k.contact_id AND c.page_id=k.page_id
  WHERE p_ad_id IS NULL OR (p_ad_id='unknown' AND k.ad_id IS NULL) OR k.ad_id=p_ad_id
 ) SELECT c.contact_id,c.page_id,c.ad_id,c.first_inquiry_at,(c.first_inquiry_at AT TIME ZONE 'Asia/Manila')::date,c.inquiry_basis,
 c.name,c.psid,c.pipeline_stage,conversion.at,payment.at,coalesce(money.records,'[]'::jsonb),coalesce(earlier.n,0)
 FROM chosen c
 LEFT JOIN LATERAL (
  SELECT min(e.at) AS at FROM (
   SELECT m.occurred_at AS at FROM public.messenger_lead_stage_events m WHERE m.page_id=c.page_id AND m.contact_id=c.contact_id AND m.applied AND m.stage='converted'
   UNION ALL SELECT a.stage_timestamp FROM public.ad_lead_stage_events a WHERE a.page_id=c.page_id AND a.contact_id=c.contact_id AND a.stage='converted' AND a.previous_stage IS DISTINCT FROM 'converted'
  ) e WHERE c.pipeline_stage='converted' AND e.at>=c.first_inquiry_at AND e.at<=statement_timestamp()
 ) conversion ON TRUE
 LEFT JOIN LATERAL (
  SELECT min(p.occurred_at) AS at FROM public.contact_verified_payments p WHERE p.page_id=c.page_id AND p.contact_id=c.contact_id AND p.voided_at IS NULL
  AND p.kind<>'refund' AND p.occurred_at>=c.first_inquiry_at AND p.occurred_at<=statement_timestamp()
 ) payment ON TRUE
 LEFT JOIN LATERAL (
  SELECT jsonb_agg(to_jsonb(g) ORDER BY g.currency) AS records FROM (
   SELECT p.currency,sum(CASE WHEN p.kind<>'refund' THEN p.amount_minor ELSE 0 END) AS received_minor,
    sum(CASE WHEN p.kind='refund' THEN p.amount_minor ELSE 0 END) AS refunded_minor,count(*) AS records,
    count(DISTINCT p.purchase_id) FILTER(WHERE p.kind<>'refund') AS paid_orders
   FROM public.contact_verified_payments p WHERE p.page_id=c.page_id AND p.contact_id=c.contact_id AND p.voided_at IS NULL
    AND p.occurred_at>=c.first_inquiry_at AND p.occurred_at<=statement_timestamp() GROUP BY p.currency
  ) g
 ) money ON TRUE
 LEFT JOIN LATERAL (
  SELECT count(*) AS n FROM public.contact_verified_payments p WHERE p.page_id=c.page_id AND p.contact_id=c.contact_id AND p.voided_at IS NULL AND p.occurred_at<c.first_inquiry_at
 ) earlier ON TRUE;
END $$;

CREATE OR REPLACE FUNCTION public.get_ad_calendar_report(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' AS $$
 WITH cohort AS MATERIALIZED(SELECT *,
  (converted_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS stage_lag,
  (paid_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS paid_lag
  FROM public.ad_calendar_cohort(p_page_ids,p_from,p_to,p_ad_id)),
 grouped AS (
  SELECT page_id,ad_id,inquiry_day AS day,count(*) AS inquiries,count(*) FILTER(WHERE inquiry_basis='legacy_recorded') AS legacy_dates,
   count(*) FILTER(WHERE stage='converted') AS converted,count(*) FILTER(WHERE stage='converted' AND converted_at IS NULL) AS conversion_time_unknown,
   count(*) FILTER(WHERE stage_lag>0) AS converted_later,count(*) FILTER(WHERE paid_at IS NOT NULL) AS payers,count(*) FILTER(WHERE paid_lag>0) AS payers_later,
   sum(pre_inquiry_payments) AS pre_inquiry_payments,
   jsonb_build_array(count(*) FILTER(WHERE stage_lag=0),count(*) FILTER(WHERE stage_lag=1),count(*) FILTER(WHERE stage_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE stage_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE stage_lag>30)) AS stage_lags,
   jsonb_build_array(count(*) FILTER(WHERE paid_lag=0),count(*) FILTER(WHERE paid_lag=1),count(*) FILTER(WHERE paid_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE paid_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE paid_lag>30)) AS paid_lags
  FROM cohort GROUP BY page_id,ad_id,inquiry_day
 ), financial AS (
  SELECT c.page_id,c.ad_id,c.inquiry_day AS day,f->>'currency' AS currency,
   sum((f->>'received_minor')::numeric) AS received_minor,sum((f->>'refunded_minor')::numeric) AS refunded_minor,
   sum((f->>'records')::bigint) AS records,sum((f->>'paid_orders')::bigint) AS paid_orders
  FROM cohort c CROSS JOIN LATERAL jsonb_array_elements(c.finance) f GROUP BY c.page_id,c.ad_id,c.inquiry_day,f->>'currency'
 ) SELECT jsonb_build_object('as_of',statement_timestamp(),'groups',coalesce((SELECT jsonb_agg(to_jsonb(g)||jsonb_build_object('finance',coalesce((
  SELECT jsonb_agg(to_jsonb(f)-'page_id'-'ad_id'-'day' ORDER BY f.currency) FROM financial f WHERE f.page_id=g.page_id AND f.ad_id IS NOT DISTINCT FROM g.ad_id AND f.day=g.day
 ),'[]'::jsonb)) ORDER BY g.day,g.page_id,g.ad_id) FROM grouped g),'[]'::jsonb));
$$;

CREATE OR REPLACE FUNCTION public.get_ad_calendar_contacts(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL,p_status TEXT DEFAULT 'all',p_offset INTEGER DEFAULT 0)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' AS $$
BEGIN
 IF p_status NOT IN('all','converted','paid','unconverted') OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'Invalid contact filter'; END IF;
 RETURN (WITH filtered AS MATERIALIZED(
  SELECT * FROM public.ad_calendar_cohort(p_page_ids,p_from,p_to,p_ad_id)
  WHERE (p_ad_id IS NOT NULL OR ad_id IS NOT NULL) AND (p_status='all' OR p_status='converted' AND stage='converted' OR p_status='paid' AND paid_at IS NOT NULL OR p_status='unconverted' AND stage IS DISTINCT FROM 'converted')
 ), limited AS(SELECT * FROM filtered ORDER BY inquiry_at,id OFFSET p_offset LIMIT 25)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'contacts',coalesce((SELECT jsonb_agg(to_jsonb(l) ORDER BY inquiry_at,id) FROM limited l),'[]'::jsonb)));
END $$;

REVOKE ALL ON FUNCTION public.ad_calendar_cohort(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),public.get_ad_calendar_report(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),public.get_ad_calendar_contacts(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,TEXT,INTEGER) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ad_calendar_cohort(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),public.get_ad_calendar_report(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),public.get_ad_calendar_contacts(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,TEXT,INTEGER) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611020005_ad_calendar.sql','878ec1bfdb3907a12c06c9325e30d49c0a405c408014c1a3c62f6d4479bc5fe8');

-- FILE: 202611020006_calendar_outcome_sources.sql SHA256: 7f5e6b2b3a12a61fc86a17c240bcac2baea86acfee32f905ecca8f4415b62a5f

SET LOCAL lock_timeout='5s';

-- Preserve the original ledger and attribution functions. This read-only layer
-- exposes already-documented conversation confirmations without inventing cash.
CREATE OR REPLACE FUNCTION public.ad_calendar_outcomes(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT,
 converted BOOLEAN,order_created BOOLEAN,confirmed_at TIMESTAMPTZ,chat_confirmed BOOLEAN,
 conversation_reviewed BOOLEAN,confirmation_stale BOOLEAN,confirmation_evidence_id TEXT,confirmation_source_at TIMESTAMPTZ)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' AS $$
 WITH source AS (
  SELECT c.*,f.source_cutoff_at,
   CASE WHEN f.payment_evidence_id IS NOT NULL AND length(btrim(f.payment_evidence_id))>0
     AND f.payment_at>=greatest(c.inquiry_at,f.first_inquiry_at) AND f.payment_at<=least(f.source_cutoff_at,statement_timestamp())
    THEN f.payment_at END AS chat_at,
   f.payment_evidence_id,f.dirty_at,history.at AS previous_conversion
  FROM public.ad_calendar_cohort(p_page_ids,p_from,p_to,p_ad_id) c
  LEFT JOIN public.contact_conversion_cache f ON f.contact_id=c.id AND f.page_id=c.page_id
   AND f.complete_history AND f.source_cutoff_at<=statement_timestamp()
  LEFT JOIN LATERAL (
   SELECT min(e.at) AS at FROM (
    SELECT m.occurred_at AS at FROM public.messenger_lead_stage_events m WHERE m.page_id=c.page_id AND m.contact_id=c.id AND m.applied AND m.stage='converted'
    UNION ALL SELECT a.stage_timestamp FROM public.ad_lead_stage_events a WHERE a.page_id=c.page_id AND a.contact_id=c.id AND a.stage='converted' AND a.previous_stage IS DISTINCT FROM 'converted'
   ) e WHERE c.stage='order_created' AND e.at>=c.inquiry_at AND e.at<=statement_timestamp()
  ) history ON TRUE
 )
 SELECT s.id,s.page_id,s.ad_id,s.inquiry_at,s.inquiry_day,s.inquiry_basis,s.name,s.psid,s.stage,
  coalesce(s.converted_at,s.previous_conversion),s.paid_at,s.finance,s.pre_inquiry_payments,
  s.stage='converted' OR (s.stage='order_created' AND s.previous_conversion IS NOT NULL),
  s.stage='order_created',least(s.paid_at,s.chat_at),s.chat_at IS NOT NULL,
  s.source_cutoff_at IS NOT NULL,s.chat_at IS NOT NULL AND s.dirty_at>s.source_cutoff_at,
  CASE WHEN s.chat_at IS NOT NULL THEN s.payment_evidence_id END,s.source_cutoff_at
 FROM source s;
$$;

CREATE OR REPLACE FUNCTION public.get_ad_calendar_report(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' AS $$
 WITH cohort AS MATERIALIZED(SELECT *,
  (converted_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS stage_lag,
  (paid_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS paid_lag,
  (confirmed_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS confirmed_lag
  FROM public.ad_calendar_outcomes(p_page_ids,p_from,p_to,p_ad_id)),
 grouped AS (
  SELECT page_id,ad_id,inquiry_day AS day,count(*) AS inquiries,count(*) FILTER(WHERE inquiry_basis='legacy_recorded') AS legacy_dates,
   count(*) FILTER(WHERE converted) AS converted,count(*) FILTER(WHERE converted AND converted_at IS NULL) AS conversion_time_unknown,
   count(*) FILTER(WHERE order_created) AS orders,
   count(*) FILTER(WHERE stage_lag>0) AS converted_later,count(*) FILTER(WHERE paid_at IS NOT NULL) AS payers,count(*) FILTER(WHERE paid_lag>0) AS payers_later,
   count(*) FILTER(WHERE confirmed_at IS NOT NULL) AS confirmed_payers,count(*) FILTER(WHERE confirmed_lag>0) AS confirmed_payers_later,
   count(*) FILTER(WHERE chat_confirmed) AS chat_confirmed_payers,
   count(*) FILTER(WHERE conversation_reviewed) AS reviewed_conversations,
   count(*) FILTER(WHERE confirmation_stale) AS confirmation_stale,
   sum(pre_inquiry_payments) AS pre_inquiry_payments,
   jsonb_build_array(count(*) FILTER(WHERE stage_lag=0),count(*) FILTER(WHERE stage_lag=1),count(*) FILTER(WHERE stage_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE stage_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE stage_lag>30)) AS stage_lags,
   jsonb_build_array(count(*) FILTER(WHERE paid_lag=0),count(*) FILTER(WHERE paid_lag=1),count(*) FILTER(WHERE paid_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE paid_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE paid_lag>30)) AS paid_lags,
   jsonb_build_array(count(*) FILTER(WHERE confirmed_lag=0),count(*) FILTER(WHERE confirmed_lag=1),count(*) FILTER(WHERE confirmed_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE confirmed_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE confirmed_lag>30)) AS confirmed_paid_lags
  FROM cohort GROUP BY page_id,ad_id,inquiry_day
 ), financial AS (
  SELECT c.page_id,c.ad_id,c.inquiry_day AS day,f->>'currency' AS currency,
   sum((f->>'received_minor')::numeric) AS received_minor,sum((f->>'refunded_minor')::numeric) AS refunded_minor,
   sum((f->>'records')::bigint) AS records,sum((f->>'paid_orders')::bigint) AS paid_orders
  FROM cohort c CROSS JOIN LATERAL jsonb_array_elements(c.finance) f GROUP BY c.page_id,c.ad_id,c.inquiry_day,f->>'currency'
 ) SELECT jsonb_build_object('as_of',statement_timestamp(),'groups',coalesce((SELECT jsonb_agg(to_jsonb(g)||jsonb_build_object('finance',coalesce((
  SELECT jsonb_agg(to_jsonb(f)-'page_id'-'ad_id'-'day' ORDER BY f.currency) FROM financial f WHERE f.page_id=g.page_id AND f.ad_id IS NOT DISTINCT FROM g.ad_id AND f.day=g.day
 ),'[]'::jsonb)) ORDER BY g.day,g.page_id,g.ad_id) FROM grouped g),'[]'::jsonb));
$$;

CREATE OR REPLACE FUNCTION public.get_ad_calendar_contacts(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL,p_status TEXT DEFAULT 'all',p_offset INTEGER DEFAULT 0)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' AS $$
BEGIN
 IF p_status NOT IN('all','converted','paid','unconverted','confirmed','orders') OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'Invalid contact filter'; END IF;
 RETURN (WITH filtered AS MATERIALIZED(
  SELECT *,CASE WHEN paid_at IS NOT NULL AND chat_confirmed THEN 'ledger_and_conversation'
    WHEN paid_at IS NOT NULL THEN 'ledger_verified' WHEN chat_confirmed THEN 'conversation_documented' ELSE 'not_verified' END AS confirmation_basis
  FROM public.ad_calendar_outcomes(p_page_ids,p_from,p_to,p_ad_id)
  WHERE p_status='all' OR p_status='converted' AND converted OR p_status='paid' AND paid_at IS NOT NULL
   OR p_status='unconverted' AND NOT converted OR p_status='confirmed' AND confirmed_at IS NOT NULL OR p_status='orders' AND order_created
 ), limited AS(SELECT * FROM filtered ORDER BY inquiry_at,id OFFSET p_offset LIMIT 25)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'contacts',coalesce((SELECT jsonb_agg(to_jsonb(l) ORDER BY inquiry_at,id) FROM limited l),'[]'::jsonb)));
END $$;

REVOKE ALL ON FUNCTION public.ad_calendar_outcomes(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),
 public.get_ad_calendar_report(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),
 public.get_ad_calendar_contacts(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,TEXT,INTEGER) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ad_calendar_outcomes(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),
 public.get_ad_calendar_report(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT),
 public.get_ad_calendar_contacts(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,TEXT,INTEGER) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611020006_calendar_outcome_sources.sql','7f5e6b2b3a12a61fc86a17c240bcac2baea86acfee32f905ecca8f4415b62a5f');

-- FILE: 202611020007_calendar_report_performance.sql SHA256: 0a094b588e6310c308bf55a9218017403bc6e39c7c56a82e470fbdf05b50951a

SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';

CREATE INDEX IF NOT EXISTS idx_contacts_calendar_inquiry
 ON public.contacts(page_id,first_interaction_at,id) INCLUDE(pipeline_stage);
CREATE INDEX IF NOT EXISTS idx_sources_calendar_inquiry
 ON public.ad_contact_sources(page_id,first_inquiry_at,contact_id) INCLUDE(origin_ad_id,inquiry_basis,attribution_status);

-- Metrics do not need names or PSIDs for every contact. Read those only for
-- explicitly named callers or after the contact drilldown has been paginated.
CREATE OR REPLACE FUNCTION public.ad_calendar_cohort_rows(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT,p_include_names BOOLEAN)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$
BEGIN
 IF p_page_ids IS NULL OR cardinality(p_page_ids)>50 OR p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '32 days'
 OR (p_ad_id IS NOT NULL AND p_ad_id<>'unknown' AND p_ad_id !~ '^[0-9]{1,100}$') THEN RAISE EXCEPTION 'Invalid calendar scope'; END IF;
 RETURN QUERY WITH chosen AS MATERIALIZED (
  SELECT s.contact_id,s.page_id,CASE WHEN s.attribution_status='verified_inline' THEN s.origin_ad_id END AS ad_id,
   s.first_inquiry_at,s.inquiry_basis,c.pipeline_stage
  FROM public.ad_contact_sources s
  JOIN LATERAL(SELECT contact.pipeline_stage FROM public.contacts contact WHERE contact.page_id=s.page_id AND contact.id=s.contact_id LIMIT 1) c ON TRUE
  WHERE s.page_id=ANY(p_page_ids) AND s.first_inquiry_at>=p_from AND s.first_inquiry_at<least(p_to,statement_timestamp())
   AND (p_ad_id IS NULL OR p_ad_id='unknown' AND (s.attribution_status IS DISTINCT FROM 'verified_inline' OR s.origin_ad_id IS NULL)
    OR s.attribution_status='verified_inline' AND s.origin_ad_id=p_ad_id)
  UNION ALL
  SELECT c.id,c.page_id,NULL::text,c.first_interaction_at,'legacy_recorded'::text,c.pipeline_stage
  FROM public.contacts c
  WHERE (p_ad_id IS NULL OR p_ad_id='unknown') AND c.page_id=ANY(p_page_ids)
   AND c.first_interaction_at>=p_from AND c.first_interaction_at<least(p_to,statement_timestamp())
   AND NOT EXISTS(SELECT 1 FROM public.ad_contact_sources s WHERE s.contact_id=c.id AND s.page_id=c.page_id)
 ), converted AS MATERIALIZED (
  SELECT c.contact_id,c.page_id,c.first_inquiry_at FROM chosen c WHERE c.pipeline_stage='converted'
 ), events AS (
  SELECT c.contact_id,c.page_id,m.occurred_at AS at FROM converted c
   JOIN public.messenger_lead_stage_events m ON m.contact_id=c.contact_id AND m.page_id=c.page_id
   WHERE m.applied AND m.stage='converted' AND m.occurred_at>=c.first_inquiry_at AND m.occurred_at<=statement_timestamp()
  UNION ALL
  SELECT c.contact_id,c.page_id,a.stage_timestamp FROM converted c
   JOIN public.ad_lead_stage_events a ON a.contact_id=c.contact_id AND a.page_id=c.page_id
   WHERE a.stage='converted' AND a.previous_stage IS DISTINCT FROM 'converted' AND a.stage_timestamp>=c.first_inquiry_at AND a.stage_timestamp<=statement_timestamp()
 ), conversion AS (
  SELECT e.contact_id,e.page_id,min(e.at) AS at FROM events e GROUP BY e.contact_id,e.page_id
 ), receipts AS MATERIALIZED (
  SELECT p.*,c.first_inquiry_at FROM public.contact_verified_payments p
   JOIN chosen c ON c.contact_id=p.contact_id AND c.page_id=p.page_id
   WHERE p.voided_at IS NULL AND p.occurred_at<=statement_timestamp()
 ), amounts AS (
  SELECT p.contact_id,p.page_id,p.currency,
   sum(CASE WHEN p.kind<>'refund' THEN p.amount_minor ELSE 0 END) AS received_minor,
   sum(CASE WHEN p.kind='refund' THEN p.amount_minor ELSE 0 END) AS refunded_minor,
   count(*) AS records,count(DISTINCT p.purchase_id) FILTER(WHERE p.kind<>'refund') AS paid_orders,
   min(p.occurred_at) FILTER(WHERE p.kind<>'refund') AS paid_at
  FROM receipts p WHERE p.occurred_at>=p.first_inquiry_at GROUP BY p.contact_id,p.page_id,p.currency
 ), money AS (
  SELECT a.contact_id,a.page_id,min(a.paid_at) AS paid_at,
   jsonb_agg(jsonb_build_object('currency',a.currency,'received_minor',a.received_minor,'refunded_minor',a.refunded_minor,'records',a.records,'paid_orders',a.paid_orders) ORDER BY a.currency) AS records
  FROM amounts a GROUP BY a.contact_id,a.page_id
 ), earlier AS (
  SELECT p.contact_id,p.page_id,count(*) AS n FROM receipts p WHERE p.occurred_at<p.first_inquiry_at GROUP BY p.contact_id,p.page_id
 )
 SELECT c.contact_id,c.page_id,c.ad_id,c.first_inquiry_at,(c.first_inquiry_at AT TIME ZONE 'Asia/Manila')::date,c.inquiry_basis,
  names.name,names.psid,c.pipeline_stage,conversion.at,money.paid_at,coalesce(money.records,'[]'::jsonb),coalesce(earlier.n,0)
 FROM chosen c
 LEFT JOIN conversion ON conversion.contact_id=c.contact_id AND conversion.page_id=c.page_id
 LEFT JOIN money ON money.contact_id=c.contact_id AND money.page_id=c.page_id
 LEFT JOIN earlier ON earlier.contact_id=c.contact_id AND earlier.page_id=c.page_id
 LEFT JOIN LATERAL(SELECT contact.name,contact.psid FROM public.contacts contact WHERE p_include_names AND contact.id=c.contact_id AND contact.page_id=c.page_id LIMIT 1) names ON TRUE;
END $$;

CREATE OR REPLACE FUNCTION public.ad_calendar_outcomes_core(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT,p_include_names BOOLEAN)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT,
 converted BOOLEAN,order_created BOOLEAN,confirmed_at TIMESTAMPTZ,chat_confirmed BOOLEAN,
 conversation_reviewed BOOLEAN,confirmation_stale BOOLEAN,confirmation_evidence_id TEXT,confirmation_source_at TIMESTAMPTZ)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$
 WITH source AS (
  SELECT c.*,f.source_cutoff_at,
   CASE WHEN f.payment_evidence_id IS NOT NULL AND length(btrim(f.payment_evidence_id))>0
     AND f.payment_at>=greatest(c.inquiry_at,f.first_inquiry_at) AND f.payment_at<=least(f.source_cutoff_at,statement_timestamp())
    THEN f.payment_at END AS chat_at,
   f.payment_evidence_id,f.dirty_at,history.at AS previous_conversion
  FROM public.ad_calendar_cohort_rows(p_page_ids,p_from,p_to,p_ad_id,p_include_names) c
  LEFT JOIN public.contact_conversion_cache f ON f.contact_id=c.id AND f.page_id=c.page_id
   AND f.complete_history AND f.source_cutoff_at<=statement_timestamp()
  LEFT JOIN LATERAL (
   SELECT min(e.at) AS at FROM (
    SELECT m.occurred_at AS at FROM public.messenger_lead_stage_events m WHERE m.page_id=c.page_id AND m.contact_id=c.id AND m.applied AND m.stage='converted'
    UNION ALL SELECT a.stage_timestamp FROM public.ad_lead_stage_events a WHERE a.page_id=c.page_id AND a.contact_id=c.id AND a.stage='converted' AND a.previous_stage IS DISTINCT FROM 'converted'
   ) e WHERE c.stage='order_created' AND e.at>=c.inquiry_at AND e.at<=statement_timestamp()
  ) history ON TRUE
 )
 SELECT s.id,s.page_id,s.ad_id,s.inquiry_at,s.inquiry_day,s.inquiry_basis,s.name,s.psid,s.stage,
  coalesce(s.converted_at,s.previous_conversion),s.paid_at,s.finance,s.pre_inquiry_payments,
  s.stage='converted' OR (s.stage='order_created' AND s.previous_conversion IS NOT NULL),
  s.stage='order_created',least(s.paid_at,s.chat_at),s.chat_at IS NOT NULL,
  s.source_cutoff_at IS NOT NULL,s.chat_at IS NOT NULL AND s.dirty_at>s.source_cutoff_at,
  CASE WHEN s.chat_at IS NOT NULL THEN s.payment_evidence_id END,s.source_cutoff_at
 FROM source s;
$$;

CREATE OR REPLACE FUNCTION public.ad_calendar_cohort(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$ SELECT * FROM public.ad_calendar_cohort_rows(p_page_ids,p_from,p_to,p_ad_id,true); $$;

CREATE OR REPLACE FUNCTION public.ad_calendar_outcomes(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT,
 converted BOOLEAN,order_created BOOLEAN,confirmed_at TIMESTAMPTZ,chat_confirmed BOOLEAN,
 conversation_reviewed BOOLEAN,confirmation_stale BOOLEAN,confirmation_evidence_id TEXT,confirmation_source_at TIMESTAMPTZ)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$ SELECT * FROM public.ad_calendar_outcomes_core(p_page_ids,p_from,p_to,p_ad_id,true); $$;

CREATE OR REPLACE FUNCTION public.get_ad_calendar_report(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL)
RETURNS JSONB LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$
 WITH cohort AS MATERIALIZED(SELECT *,
  (converted_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS stage_lag,
  (paid_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS paid_lag,
  (confirmed_at AT TIME ZONE 'Asia/Manila')::date-inquiry_day AS confirmed_lag
  FROM public.ad_calendar_outcomes_core(p_page_ids,p_from,p_to,p_ad_id,false)),
 grouped AS (
  SELECT page_id,ad_id,inquiry_day AS day,count(*) AS inquiries,count(*) FILTER(WHERE inquiry_basis='legacy_recorded') AS legacy_dates,
   count(*) FILTER(WHERE converted) AS converted,count(*) FILTER(WHERE converted AND converted_at IS NULL) AS conversion_time_unknown,
   count(*) FILTER(WHERE order_created) AS orders,
   count(*) FILTER(WHERE stage_lag>0) AS converted_later,count(*) FILTER(WHERE paid_at IS NOT NULL) AS payers,count(*) FILTER(WHERE paid_lag>0) AS payers_later,
   count(*) FILTER(WHERE confirmed_at IS NOT NULL) AS confirmed_payers,count(*) FILTER(WHERE confirmed_lag>0) AS confirmed_payers_later,
   count(*) FILTER(WHERE chat_confirmed) AS chat_confirmed_payers,
   count(*) FILTER(WHERE conversation_reviewed) AS reviewed_conversations,
   count(*) FILTER(WHERE confirmation_stale) AS confirmation_stale,
   sum(pre_inquiry_payments) AS pre_inquiry_payments,
   jsonb_build_array(count(*) FILTER(WHERE stage_lag=0),count(*) FILTER(WHERE stage_lag=1),count(*) FILTER(WHERE stage_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE stage_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE stage_lag>30)) AS stage_lags,
   jsonb_build_array(count(*) FILTER(WHERE paid_lag=0),count(*) FILTER(WHERE paid_lag=1),count(*) FILTER(WHERE paid_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE paid_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE paid_lag>30)) AS paid_lags,
   jsonb_build_array(count(*) FILTER(WHERE confirmed_lag=0),count(*) FILTER(WHERE confirmed_lag=1),count(*) FILTER(WHERE confirmed_lag BETWEEN 2 AND 7),count(*) FILTER(WHERE confirmed_lag BETWEEN 8 AND 30),count(*) FILTER(WHERE confirmed_lag>30)) AS confirmed_paid_lags
  FROM cohort GROUP BY page_id,ad_id,inquiry_day
 ), financial AS MATERIALIZED (
  SELECT c.page_id,c.ad_id,c.inquiry_day AS day,f->>'currency' AS currency,
   sum((f->>'received_minor')::numeric) AS received_minor,sum((f->>'refunded_minor')::numeric) AS refunded_minor,
   sum((f->>'records')::bigint) AS records,sum((f->>'paid_orders')::bigint) AS paid_orders
  FROM cohort c CROSS JOIN LATERAL jsonb_array_elements(c.finance) f GROUP BY c.page_id,c.ad_id,c.inquiry_day,f->>'currency'
 ) SELECT jsonb_build_object('as_of',statement_timestamp(),'groups',coalesce((SELECT jsonb_agg(to_jsonb(g)||jsonb_build_object('finance',coalesce((
  SELECT jsonb_agg(to_jsonb(f)-'page_id'-'ad_id'-'day' ORDER BY f.currency) FROM financial f WHERE f.page_id=g.page_id AND f.ad_id IS NOT DISTINCT FROM g.ad_id AND f.day=g.day
 ),'[]'::jsonb)) ORDER BY g.day,g.page_id,g.ad_id) FROM grouped g),'[]'::jsonb));
$$;

CREATE OR REPLACE FUNCTION public.get_ad_calendar_contacts(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT DEFAULT NULL,p_status TEXT DEFAULT 'all',p_offset INTEGER DEFAULT 0)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$
BEGIN
 IF p_status NOT IN('all','converted','paid','unconverted','confirmed','orders') OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'Invalid contact filter'; END IF;
 RETURN (WITH filtered AS MATERIALIZED(
  SELECT *,CASE WHEN paid_at IS NOT NULL AND chat_confirmed THEN 'ledger_and_conversation'
    WHEN paid_at IS NOT NULL THEN 'ledger_verified' WHEN chat_confirmed THEN 'conversation_documented' ELSE 'not_verified' END AS confirmation_basis
  FROM public.ad_calendar_outcomes_core(p_page_ids,p_from,p_to,p_ad_id,false)
  WHERE p_status='all' OR p_status='converted' AND converted OR p_status='paid' AND paid_at IS NOT NULL
   OR p_status='unconverted' AND NOT converted OR p_status='confirmed' AND confirmed_at IS NOT NULL OR p_status='orders' AND order_created
 ), limited AS(SELECT * FROM filtered ORDER BY inquiry_at,id OFFSET p_offset LIMIT 25)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'contacts',coalesce((SELECT jsonb_agg(to_jsonb(l)||jsonb_build_object('name',names.name,'psid',names.psid) ORDER BY l.inquiry_at,l.id) FROM limited l LEFT JOIN public.contacts names ON names.id=l.id AND names.page_id=l.page_id),'[]'::jsonb)));
END $$;

REVOKE ALL ON FUNCTION public.ad_calendar_cohort_rows(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,BOOLEAN),public.ad_calendar_outcomes_core(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,BOOLEAN) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.ad_calendar_cohort_rows(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,BOOLEAN),public.ad_calendar_outcomes_core(UUID[],TIMESTAMPTZ,TIMESTAMPTZ,TEXT,BOOLEAN) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611020007_calendar_report_performance.sql','0a094b588e6310c308bf55a9218017403bc6e39c7c56a82e470fbdf05b50951a');

-- FILE: 202611020008_historical_repair_no_ai.sql SHA256: 6292505a5443a0388cfa1b1f4f791049d1716f7129b969e7ac50ec40c26d99c8

SET LOCAL lock_timeout='5s';
-- Only a trusted SQL repair session sets this transaction-local flag. It does
-- not change Page settings or suppress summaries for later live stage changes.
CREATE OR REPLACE FUNCTION public.queue_profile_after_meta_stage()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
    IF current_setting('app.historical_lead_repair',true)='deterministic_only' THEN RETURN NEW; END IF;
    IF NEW.applied AND (TG_OP='INSERT' OR NOT OLD.applied) THEN
        PERFORM public.enqueue_contact_profile(NEW.page_id,NEW.contact_id,'stage_change');
    END IF;
    RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION public.queue_profile_after_meta_stage() FROM PUBLIC,anon,authenticated;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611020008_historical_repair_no_ai.sql','6292505a5443a0388cfa1b1f4f791049d1716f7129b969e7ac50ec40c26d99c8');

-- FILE: 202611020009_calendar_historical_conversions.sql SHA256: aaa931e650ba4890d5224c7309f0659745d359a0a2b6e725d191ad9513194ca8

SET LOCAL lock_timeout='5s';
-- applied records whether a notice changed the CRM when observed. An older
-- authenticated Meta notice still establishes historical conversion timing.
-- Current-stage gates continue to handle reversals and keep orders separate.
CREATE OR REPLACE FUNCTION public.ad_calendar_cohort_rows(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT,p_include_names BOOLEAN)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$
BEGIN
 IF p_page_ids IS NULL OR cardinality(p_page_ids)>50 OR p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '32 days'
 OR (p_ad_id IS NOT NULL AND p_ad_id<>'unknown' AND p_ad_id !~ '^[0-9]{1,100}$') THEN RAISE EXCEPTION 'Invalid calendar scope'; END IF;
 RETURN QUERY WITH chosen AS MATERIALIZED (
  SELECT s.contact_id,s.page_id,CASE WHEN s.attribution_status='verified_inline' THEN s.origin_ad_id END AS ad_id,
   s.first_inquiry_at,s.inquiry_basis,c.pipeline_stage
  FROM public.ad_contact_sources s
  JOIN LATERAL(SELECT contact.pipeline_stage FROM public.contacts contact WHERE contact.page_id=s.page_id AND contact.id=s.contact_id LIMIT 1) c ON TRUE
  WHERE s.page_id=ANY(p_page_ids) AND s.first_inquiry_at>=p_from AND s.first_inquiry_at<least(p_to,statement_timestamp())
   AND (p_ad_id IS NULL OR p_ad_id='unknown' AND (s.attribution_status IS DISTINCT FROM 'verified_inline' OR s.origin_ad_id IS NULL)
    OR s.attribution_status='verified_inline' AND s.origin_ad_id=p_ad_id)
  UNION ALL
  SELECT c.id,c.page_id,NULL::text,c.first_interaction_at,'legacy_recorded'::text,c.pipeline_stage
  FROM public.contacts c
  WHERE (p_ad_id IS NULL OR p_ad_id='unknown') AND c.page_id=ANY(p_page_ids)
   AND c.first_interaction_at>=p_from AND c.first_interaction_at<least(p_to,statement_timestamp())
   AND NOT EXISTS(SELECT 1 FROM public.ad_contact_sources s WHERE s.contact_id=c.id AND s.page_id=c.page_id)
 ), converted AS MATERIALIZED (
  SELECT c.contact_id,c.page_id,c.first_inquiry_at FROM chosen c WHERE c.pipeline_stage='converted'
 ), events AS (
  SELECT c.contact_id,c.page_id,m.occurred_at AS at FROM converted c
   JOIN public.messenger_lead_stage_events m ON m.contact_id=c.contact_id AND m.page_id=c.page_id
   WHERE m.stage='converted' AND m.occurred_at>=c.first_inquiry_at AND m.occurred_at<=statement_timestamp()
  UNION ALL
  SELECT c.contact_id,c.page_id,a.stage_timestamp FROM converted c
   JOIN public.ad_lead_stage_events a ON a.contact_id=c.contact_id AND a.page_id=c.page_id
   WHERE a.stage='converted' AND a.previous_stage IS DISTINCT FROM 'converted' AND a.stage_timestamp>=c.first_inquiry_at AND a.stage_timestamp<=statement_timestamp()
 ), conversion AS (
  SELECT e.contact_id,e.page_id,min(e.at) AS at FROM events e GROUP BY e.contact_id,e.page_id
 ), receipts AS MATERIALIZED (
  SELECT p.*,c.first_inquiry_at FROM public.contact_verified_payments p
   JOIN chosen c ON c.contact_id=p.contact_id AND c.page_id=p.page_id
   WHERE p.voided_at IS NULL AND p.occurred_at<=statement_timestamp()
 ), amounts AS (
  SELECT p.contact_id,p.page_id,p.currency,
   sum(CASE WHEN p.kind<>'refund' THEN p.amount_minor ELSE 0 END) AS received_minor,
   sum(CASE WHEN p.kind='refund' THEN p.amount_minor ELSE 0 END) AS refunded_minor,
   count(*) AS records,count(DISTINCT p.purchase_id) FILTER(WHERE p.kind<>'refund') AS paid_orders,
   min(p.occurred_at) FILTER(WHERE p.kind<>'refund') AS paid_at
  FROM receipts p WHERE p.occurred_at>=p.first_inquiry_at GROUP BY p.contact_id,p.page_id,p.currency
 ), money AS (
  SELECT a.contact_id,a.page_id,min(a.paid_at) AS paid_at,
   jsonb_agg(jsonb_build_object('currency',a.currency,'received_minor',a.received_minor,'refunded_minor',a.refunded_minor,'records',a.records,'paid_orders',a.paid_orders) ORDER BY a.currency) AS records
  FROM amounts a GROUP BY a.contact_id,a.page_id
 ), earlier AS (
  SELECT p.contact_id,p.page_id,count(*) AS n FROM receipts p WHERE p.occurred_at<p.first_inquiry_at GROUP BY p.contact_id,p.page_id
 )
 SELECT c.contact_id,c.page_id,c.ad_id,c.first_inquiry_at,(c.first_inquiry_at AT TIME ZONE 'Asia/Manila')::date,c.inquiry_basis,
  names.name,names.psid,c.pipeline_stage,conversion.at,money.paid_at,coalesce(money.records,'[]'::jsonb),coalesce(earlier.n,0)
 FROM chosen c
 LEFT JOIN conversion ON conversion.contact_id=c.contact_id AND conversion.page_id=c.page_id
 LEFT JOIN money ON money.contact_id=c.contact_id AND money.page_id=c.page_id
 LEFT JOIN earlier ON earlier.contact_id=c.contact_id AND earlier.page_id=c.page_id
 LEFT JOIN LATERAL(SELECT contact.name,contact.psid FROM public.contacts contact WHERE p_include_names AND contact.id=c.contact_id AND contact.page_id=c.page_id LIMIT 1) names ON TRUE;
END $$;

CREATE OR REPLACE FUNCTION public.ad_calendar_outcomes_core(p_page_ids UUID[],p_from TIMESTAMPTZ,p_to TIMESTAMPTZ,p_ad_id TEXT,p_include_names BOOLEAN)
RETURNS TABLE(id UUID,page_id UUID,ad_id TEXT,inquiry_at TIMESTAMPTZ,inquiry_day DATE,inquiry_basis TEXT,
 name TEXT,psid TEXT,stage TEXT,converted_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,finance JSONB,pre_inquiry_payments BIGINT,
 converted BOOLEAN,order_created BOOLEAN,confirmed_at TIMESTAMPTZ,chat_confirmed BOOLEAN,
 conversation_reviewed BOOLEAN,confirmation_stale BOOLEAN,confirmation_evidence_id TEXT,confirmation_source_at TIMESTAMPTZ)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public SET plan_cache_mode='force_custom_plan' SET jit='off' AS $$
 WITH source AS (
  SELECT c.*,f.source_cutoff_at,
   CASE WHEN f.payment_evidence_id IS NOT NULL AND length(btrim(f.payment_evidence_id))>0
     AND f.payment_at>=greatest(c.inquiry_at,f.first_inquiry_at) AND f.payment_at<=least(f.source_cutoff_at,statement_timestamp())
    THEN f.payment_at END AS chat_at,
   f.payment_evidence_id,f.dirty_at,history.at AS previous_conversion
  FROM public.ad_calendar_cohort_rows(p_page_ids,p_from,p_to,p_ad_id,p_include_names) c
  LEFT JOIN public.contact_conversion_cache f ON f.contact_id=c.id AND f.page_id=c.page_id
   AND f.complete_history AND f.source_cutoff_at<=statement_timestamp()
  LEFT JOIN LATERAL (
   SELECT min(e.at) AS at FROM (
    SELECT m.occurred_at AS at FROM public.messenger_lead_stage_events m WHERE m.page_id=c.page_id AND m.contact_id=c.id AND m.stage='converted'
    UNION ALL SELECT a.stage_timestamp FROM public.ad_lead_stage_events a WHERE a.page_id=c.page_id AND a.contact_id=c.id AND a.stage='converted' AND a.previous_stage IS DISTINCT FROM 'converted'
   ) e WHERE c.stage='order_created' AND e.at>=c.inquiry_at AND e.at<=statement_timestamp()
  ) history ON TRUE
 )
 SELECT s.id,s.page_id,s.ad_id,s.inquiry_at,s.inquiry_day,s.inquiry_basis,s.name,s.psid,s.stage,
  coalesce(s.converted_at,s.previous_conversion),s.paid_at,s.finance,s.pre_inquiry_payments,
  s.stage='converted' OR (s.stage='order_created' AND s.previous_conversion IS NOT NULL),
  s.stage='order_created',least(s.paid_at,s.chat_at),s.chat_at IS NOT NULL,
  s.source_cutoff_at IS NOT NULL,s.chat_at IS NOT NULL AND s.dirty_at>s.source_cutoff_at,
  CASE WHEN s.chat_at IS NOT NULL THEN s.payment_evidence_id END,s.source_cutoff_at
 FROM source s;
$$;


NOTIFY pgrst,'reload schema';


