$$;
CREATE FUNCTION public.veo_legacy_finance_readonly() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 BEGIN
 IF EXISTS(SELECT 1 FROM veo_tenants WHERE launch_at IS NOT NULL) THEN RAISE EXCEPTION 'Retained financial history is read-only. Use the VEO verified ledger.'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END $$;
DO $$ DECLARE tbl text; BEGIN
 FOREACH tbl IN ARRAY ARRAY['contact_purchases','contact_verified_payments'] LOOP
 IF to_regclass('public.'||tbl) IS NOT NULL THEN EXECUTE format('CREATE TRIGGER veo_legacy_readonly BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION veo_legacy_finance_readonly()',tbl); END IF;
 END LOOP;
END $$;
CREATE FUNCTION public.veo_jaucian_report(p_tenant uuid,p_day date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 DECLARE result jsonb;
 BEGIN
 IF NOT EXISTS(SELECT 1 FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL AND (launch_at AT TIME ZONE 'Asia/Manila')::date<=p_day) OR p_day>veo_today() THEN RAISE EXCEPTION 'Date outside launched period'; END IF;
 SELECT jsonb_build_object('tenant_id',p_tenant,'work_date',p_day,'source','VEO verified sales ledger; Telegram receipts excluded',
 'teams',coalesce((SELECT jsonb_agg(jsonb_build_object('id',tm.id,'name',tm.name,'chat_id',tm.telegram_chat_id,'thread_id',tm.telegram_thread_id,
 'workers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.user_id,'name',u.name,'telegram_user_id',m.telegram_user_id,
 'salary',veo_salary(a.user_id,p_day),'active_tomorrow',att.active,'tomorrow_target',coalesce(dt.target,(veo_capacity(a.user_id,veo_today()+1)->>'target')::integer)))
 FROM veo_accounts a JOIN users u ON u.id=a.user_id LEFT JOIN veo_worker_mappings m ON m.user_id=a.user_id
 LEFT JOIN veo_attendance att ON att.user_id=a.user_id AND att.work_date=veo_today()+1
 LEFT JOIN veo_daily_targets dt ON dt.user_id=a.user_id AND dt.work_date=veo_today()+1
 WHERE a.active AND a.tenant_id=p_tenant AND (a.user_id=tm.manager_id OR a.parent_id=tm.manager_id)),'[]')))
 FROM veo_teams tm WHERE tm.tenant_id=p_tenant),'[]')) INTO result;
 RETURN result;
 END $$;
-- Reject chronological underpayments/overpayments even when a correction is backdated.
CREATE FUNCTION public.veo_payment_running_balance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 DECLARE total bigint;
 BEGIN
 SELECT total_minor INTO total FROM veo_orders WHERE id=NEW.order_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM(SELECT sum(CASE WHEN kind='refund' THEN -amount_minor ELSE amount_minor END) OVER(ORDER BY occurred_at,created_at,id) AS balance FROM veo_payments WHERE order_id=NEW.order_id) x WHERE balance<0 OR balance>total) THEN RAISE EXCEPTION 'Payment chronology exceeds balance or refundable amount'; END IF;
 RETURN NEW;
 END $$;
CREATE TRIGGER veo_payment_running_balance AFTER INSERT ON veo_payments FOR EACH ROW EXECUTE FUNCTION veo_payment_running_balance();
DO $$ DECLARE obj record; BEGIN
 FOR obj IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'veo_%' LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',obj.signature);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',obj.signature);
 END LOOP;
END $$;


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611050012_veo_workspace_hardening.sql','c953562d6530c1053619636c4ed61138e0428ec3e3a805fa3ad0268b86a1c87e');

-- FILE: 202611050013_veo_refund_and_submission_recovery.sql SHA256: def517fe1cd6001484cfa859c82b937852dee983a5fd8be071de48148c7ee1c9

-- A refunded deposit that is subsequently repaid must not reduce commission twice.
-- Each order contributes its current verified net funds to its first completion date.
CREATE OR REPLACE FUNCTION public.veo_salary(p_user uuid,p_day date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 DECLARE cd integer; dd integer; target integer; rate integer; totals jsonb;
 BEGIN
 target:=veo_target(p_user,p_day);
 SELECT count(*) FILTER(WHERE closed_date=p_day),count(*) FILTER(WHERE done_date=p_day) INTO cd,dd
 FROM veo_order_facts WHERE seller_id=p_user;
 rate:=CASE WHEN cd>=target AND dd>=target THEN 40 ELSE 35 END;
 SELECT coalesce(jsonb_agg(jsonb_build_object('currency',currency,'gross_minor',gross,'commission_minor',floor(gross*rate::numeric/100))), '[]') INTO totals
 FROM(SELECT currency,sum(paid_minor)::bigint AS gross FROM veo_order_facts WHERE seller_id=p_user AND done_date=p_day GROUP BY currency) y;
 RETURN jsonb_build_object('user_id',p_user,'work_date',p_day,'target',target,'closed',cd,'done',dd,'rate',rate,'totals',totals,'provisional',p_day>=veo_today());
 END $$;

CREATE OR REPLACE FUNCTION public.veo_handoff(p_submission uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 DECLARE s veo_submissions; o veo_order_facts; tm veo_teams; tg bigint;
 BEGIN
 SELECT * INTO s FROM veo_submissions WHERE id=p_submission;
 IF s.id IS NULL OR s.status NOT IN('queued','processing','delivered') THEN RETURN NULL; END IF;
 SELECT * INTO o FROM veo_order_facts WHERE id=s.order_id;
 IF s.expires_at<=now() OR NOT veo_can_page(s.submitted_by,o.page_id) OR NOT veo_can_page(o.seller_id,o.page_id) OR o.seller_id NOT IN(SELECT veo_descendants(s.submitted_by))
 OR NOT o.converted OR o.paid_minor<>o.total_minor OR o.done_at IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO tm FROM veo_teams WHERE id=o.team_id;
 SELECT telegram_user_id INTO tg FROM veo_worker_mappings WHERE user_id=o.seller_id;
 IF tm.telegram_chat_id IS NULL OR tg IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('submission_id',s.id,'tenant_id',o.tenant_id,'team_id',o.team_id,'seller_id',o.seller_id,
 'telegram_chat_id',tm.telegram_chat_id,'telegram_thread_id',tm.telegram_thread_id,'telegram_user_id',tg,
 'page_id',o.page_id,'contact_id',o.contact_id,'order_id',o.id,'currency',o.currency,'total_minor',o.total_minor,
 'paid_minor',o.paid_minor,'closed_at',o.closed_at,'done_at',o.done_at,'expires_at',s.expires_at,
 'seller_name',(SELECT name FROM users WHERE id=o.seller_id),'contact_name',(SELECT name FROM contacts WHERE id=o.contact_id),
 'description',o.description,'payments',(SELECT jsonb_agg(jsonb_build_object('id',id,'kind',kind,'amount_minor',amount_minor,'occurred_at',occurred_at)) FROM veo_payments WHERE order_id=o.id));
 END $$;
REVOKE ALL ON FUNCTION public.veo_salary(uuid,date),public.veo_handoff(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.veo_salary(uuid,date),public.veo_handoff(uuid) TO service_role;


