 definition:=replace(definition,'WHERE a.user_id IN(SELECT veo_branch(p_actor)) AND a.role IN(''member'',''manager'')','WHERE a.active AND a.user_id IN(SELECT veo_branch(p_actor)) AND a.role IN(''member'',''manager'')');
