-- FILE: 202611050028_veo_distinct_client_release.sql SHA256: b4fc09c4e5edb9fa55964dc994945e9f83a330d3f70873230200de72361d4684

-- DISTINCT must not include a volatile timestamp: multiple orders belonging to
-- one client can otherwise become multiple conflicting release rows.
DO $migration$ DECLARE definition text; previous text; BEGIN
 definition:=pg_get_functiondef('veo_offboard(uuid,uuid,text,text)'::regprocedure);
 previous:='SELECT DISTINCT o.contact_id,o.tenant_id,o.page_id,NULL::uuid,p_user,clock_timestamp(),p_reason';
 IF strpos(definition,previous)=0 THEN RAISE EXCEPTION 'Expected client release source before patching'; END IF;
 EXECUTE replace(definition,previous,'SELECT DISTINCT o.contact_id,o.tenant_id,o.page_id,NULL::uuid,p_user,statement_timestamp(),p_reason');
END $migration$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611050028_veo_distinct_client_release.sql','b4fc09c4e5edb9fa55964dc994945e9f83a330d3f70873230200de72361d4684');

-- FILE: 202611070001_veo_ad_spend_coverage.sql SHA256: 6b393f4ade62ccb722e0577d5ad6a0d9b5e5273d59b25a0e84ef94c2b11ba5f9

CREATE TABLE veo_ad_spend_coverage(
 page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE,spend_date date NOT NULL,currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),
 amount_minor bigint NOT NULL CHECK(amount_minor>=0),ad_count integer NOT NULL CHECK(ad_count>=0),accounts_checked integer NOT NULL CHECK(accounts_checked>0),
 checked_at timestamptz NOT NULL,report_complete boolean NOT NULL,pht_aligned boolean NOT NULL,PRIMARY KEY(page_id,spend_date,currency)
);
ALTER TABLE veo_ad_spend_coverage ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON veo_ad_spend_coverage FROM PUBLIC,anon,authenticated;
GRANT ALL ON veo_ad_spend_coverage TO service_role;
CREATE FUNCTION veo_calendar_spend(p_ids uuid[],p_from date,p_to date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH recorded AS(SELECT page_id,spend_date,currency,sum(amount)*100 AS amount_minor,bool_and(pht_aligned) AS aligned,
 count(*) AS records,count(DISTINCT ad_id) AS ads,max(checked_at) AS checked_at FROM ad_daily_spend
 WHERE page_id=ANY(p_ids) AND spend_date BETWEEN p_from AND p_to GROUP BY page_id,spend_date,currency),
 keys AS(SELECT page_id,spend_date,currency FROM recorded UNION SELECT page_id,spend_date,currency FROM veo_ad_spend_coverage WHERE page_id=ANY(p_ids) AND spend_date BETWEEN p_from AND p_to),
 reports AS(SELECT k.*,CASE WHEN c.pht_aligned AND c.checked_at>=coalesce(r.checked_at,'-infinity') THEN c.amount_minor
 WHEN r.aligned AND r.records=r.ads THEN r.amount_minor END AS amount_minor,
 coalesce(c.pht_aligned AND c.report_complete AND c.checked_at>=coalesce(r.checked_at,'-infinity')
 AND coalesce(r.records,0)=coalesce(r.ads,0) AND coalesce(r.ads,0)=c.ad_count AND coalesce(r.amount_minor,0)=c.amount_minor,false) AS complete,
 coalesce(r.records,0) AS records,greatest(c.checked_at,r.checked_at) AS checked_at,c.accounts_checked,c.ad_count
 FROM keys k LEFT JOIN recorded r USING(page_id,spend_date,currency) LEFT JOIN veo_ad_spend_coverage c USING(page_id,spend_date,currency))
 SELECT coalesce(jsonb_agg(to_jsonb(reports)),'[]') FROM reports
$$;
REVOKE ALL ON FUNCTION veo_calendar_spend(uuid[],date,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_calendar_spend(uuid[],date,date) TO service_role;
DO $$
DECLARE definition text;old_part text;
BEGIN
 definition:=replace(pg_get_functiondef('veo_calendar_inputs(uuid,date,date,date,uuid)'::regprocedure),E'\r\n',E'\n');
 old_part:=$old$'spend',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM(SELECT page_id,spend_date,currency,
 CASE WHEN bool_and(pht_aligned) AND count(*)=count(DISTINCT ad_id) THEN sum(amount)*100 END AS amount_minor,
 bool_and(pht_aligned AND report_complete) AND count(*)=count(DISTINCT ad_id) AS complete,count(*) AS records,max(checked_at) AS checked_at
 FROM ad_daily_spend WHERE page_id=ANY(ids) AND spend_date BETWEEN p_from AND p_to GROUP BY page_id,spend_date,currency) s),'[]'),$old$;
 IF strpos(definition,old_part)=0 THEN RAISE EXCEPTION 'Expected calendar spend source is missing';END IF;
 EXECUTE replace(definition,old_part,'''spend'',veo_calendar_spend(ids,p_from,p_to),');
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611070001_veo_ad_spend_coverage.sql','6b393f4ade62ccb722e0577d5ad6a0d9b5e5273d59b25a0e84ef94c2b11ba5f9');

-- FILE: 202611070002_veo_demographics.sql SHA256: e2ae56698159a690a93cc4a55b486d8b29cc67ceeca6c6b2b443644dee594d97

CREATE TABLE veo_contact_demographics(
 contact_id uuid PRIMARY KEY REFERENCES contacts(id) ON DELETE CASCADE,page_id uuid NOT NULL REFERENCES pages(id),
 fields jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','processing','ready','error')),
 requested_version integer NOT NULL DEFAULT 1,working_version integer,analyzed_version integer NOT NULL DEFAULT 0,
 attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,claim_token uuid,
 analyzed_at timestamptz,source_hash text,last_error text,coverage text NOT NULL DEFAULT 'Saved customer excerpts and new launch-period events; full historical coverage is not implied'
);
CREATE INDEX ON veo_contact_demographics(next_attempt_at) WHERE status IN('queued','error');
ALTER TABLE veo_contact_demographics ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON veo_contact_demographics FROM PUBLIC,anon,authenticated;
GRANT ALL ON veo_contact_demographics TO service_role;
CREATE FUNCTION veo_demographic_values(p_contact uuid) RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT coalesce(jsonb_object_agg(f->>'field',f->>'value'),'{}') FROM veo_contact_demographics d CROSS JOIN LATERAL jsonb_array_elements(d.fields) f WHERE d.contact_id=p_contact
$$;
CREATE FUNCTION veo_demographic_enqueue(p_contact uuid,p_manual boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE pg uuid;
BEGIN
 SELECT c.page_id INTO pg FROM contacts c JOIN pages p ON p.id=c.page_id AND p.veo_enabled JOIN veo_tenants t ON t.id=p.veo_tenant_id
 WHERE c.id=p_contact AND t.launch_at IS NOT NULL AND veo_can_page(t.owner_id,p.id);
 IF pg IS NULL THEN RETURN false;END IF;
 INSERT INTO veo_contact_demographics(contact_id,page_id,next_attempt_at) VALUES(p_contact,pg,now()+CASE WHEN p_manual THEN interval '-1 hour' ELSE interval '45 seconds' END)
 ON CONFLICT(contact_id) DO UPDATE SET requested_version=veo_contact_demographics.requested_version+1,
 status=CASE WHEN veo_contact_demographics.status='processing' AND veo_contact_demographics.lease_until>now() THEN 'processing' ELSE 'queued' END,
 next_attempt_at=CASE WHEN p_manual THEN now()-interval '1 hour' ELSE greatest(now()+interval '45 seconds',coalesce(veo_contact_demographics.analyzed_at,'-infinity')+interval '15 minutes') END;
 RETURN true;
END $$;
CREATE FUNCTION veo_demographic_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE m jsonb;client uuid;
BEGIN
 m:=coalesce(NEW.payload#>'{entry,0,messaging,0}',NEW.payload#>'{entry,0,standby,0}');
 IF m#>>'{message,text}' IS NULL OR m#>>'{message,is_echo}'='true' OR m#>>'{message,is_deleted}'='true' THEN RETURN NEW;END IF;
 SELECT c.id INTO client FROM contacts c JOIN pages p ON p.id=c.page_id WHERE c.page_id=NEW.page_id AND c.psid=m#>>'{sender,id}' AND p.fb_page_id=m#>>'{recipient,id}';
 IF client IS NOT NULL THEN PERFORM veo_demographic_enqueue(client);END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER veo_demographic_new_message AFTER UPDATE OF status ON veo_event_inbox FOR EACH ROW WHEN(NEW.status='done' AND OLD.status IS DISTINCT FROM NEW.status) EXECUTE FUNCTION veo_demographic_event();
-- Start with the new launch period only. Older contacts can be analyzed on
-- request from their retained excerpts; this never starts a history backfill.
INSERT INTO veo_contact_demographics(contact_id,page_id)
 SELECT c.id,c.page_id FROM contacts c JOIN pages p ON p.id=c.page_id AND p.veo_enabled JOIN veo_tenants t ON t.id=p.veo_tenant_id
 WHERE c.created_at>=t.launch_at AND veo_can_page(t.owner_id,p.id) ON CONFLICT DO NOTHING;
CREATE FUNCTION veo_demographic_access(p_actor uuid,p_contact uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE pg uuid;
BEGIN
 SELECT page_id INTO pg FROM contacts WHERE id=p_contact;
 IF pg IS NULL OR NOT veo_can_page(p_actor,pg) THEN RAISE EXCEPTION 'Contact access denied' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('contact_id',p_contact,'page_id',pg,'analysis',(SELECT to_jsonb(d)-'claim_token'-'lease_until' FROM veo_contact_demographics d WHERE contact_id=p_contact),
 'manual_fields',coalesce((SELECT fields FROM veo_contact_details WHERE contact_id=p_contact),'{}'),
 'saved_fields',coalesce((SELECT collected_details FROM chatbot_contact_states WHERE contact_id=p_contact AND page_id=pg),'{}'),
 'ai_demographics',veo_demographic_values(p_contact),
 'extracted_answers',coalesce((SELECT payload->'extracted_answers' FROM contact_profile_snapshots WHERE contact_id=p_contact AND page_id=pg ORDER BY generation DESC LIMIT 1),'[]'));
END $$;
CREATE FUNCTION veo_demographic_action(p_actor uuid,p_contact uuid,p_action text,p_fields jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE before_fields jsonb;pg uuid;tenant uuid;
BEGIN
 PERFORM veo_demographic_access(p_actor,p_contact);
 SELECT c.page_id,p.veo_tenant_id INTO pg,tenant FROM contacts c JOIN pages p ON p.id=c.page_id WHERE c.id=p_contact;
 IF p_action='refresh' THEN PERFORM veo_demographic_enqueue(p_contact,true);
 ELSIF p_action='correct' THEN
 IF jsonb_typeof(p_fields)<>'object' OR length(p_fields::text)>12000 OR EXISTS(SELECT 1 FROM jsonb_each(p_fields) WHERE key NOT IN('age','gender','location','country','region','province','city','industry','business_type','occupation','job_role','preferred_language') OR jsonb_typeof(value)<>'string' OR length(value#>>'{}')>160) THEN RAISE EXCEPTION 'Invalid demographic corrections';END IF;
 INSERT INTO veo_contact_details(contact_id,fields,updated_by) VALUES(p_contact,'{}',p_actor) ON CONFLICT DO NOTHING;
 SELECT fields INTO before_fields FROM veo_contact_details WHERE contact_id=p_contact FOR UPDATE;
 UPDATE veo_contact_details SET fields=fields||p_fields,updated_by=p_actor,updated_at=now() WHERE contact_id=p_contact;
 INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,before_value,after_value) VALUES(tenant,p_actor,'demographics_corrected',p_contact,before_fields,before_fields||p_fields);
 ELSE RAISE EXCEPTION 'Unknown demographic action';END IF;
 RETURN veo_demographic_access(p_actor,p_contact);
END $$;
CREATE FUNCTION veo_demographic_claim(p_limit integer DEFAULT 2) RETURNS SETOF veo_contact_demographics LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 RETURN QUERY WITH due AS(SELECT d.contact_id FROM veo_contact_demographics d JOIN pages p ON p.id=d.page_id AND p.veo_enabled JOIN veo_tenants t ON t.id=p.veo_tenant_id
 WHERE t.launch_at IS NOT NULL AND veo_can_page(t.owner_id,p.id) AND d.next_attempt_at<=now()
 AND(d.status IN('queued','error') OR d.status='processing' AND d.lease_until<now()) ORDER BY d.next_attempt_at LIMIT least(greatest(p_limit,1),5) FOR UPDATE OF d SKIP LOCKED)
 UPDATE veo_contact_demographics d SET status='processing',working_version=requested_version,claim_token=gen_random_uuid(),lease_until=now()+interval '5 minutes',attempts=attempts+1 FROM due WHERE d.contact_id=due.contact_id RETURNING d.*;
END $$;
CREATE FUNCTION veo_demographic_sources(p_contact uuid,p_claim uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH job AS(SELECT d.*,c.psid FROM veo_contact_demographics d JOIN contacts c ON c.id=d.contact_id JOIN pages p ON p.id=d.page_id AND p.veo_enabled JOIN veo_tenants t ON t.id=p.veo_tenant_id
 WHERE d.contact_id=p_contact AND d.claim_token=p_claim AND d.lease_until>now() AND d.status='processing' AND veo_can_page(t.owner_id,p.id)),
 latest AS(SELECT s.* FROM contact_profile_snapshots s JOIN job j ON j.contact_id=s.contact_id AND j.page_id=s.page_id ORDER BY generation DESC LIMIT 1),
 sources AS(SELECT m.message_id AS id,m.sent_at AS at,left(m.text,2500) AS text,'customer' AS sender,'saved_customer_excerpt' AS basis,0 AS priority
 FROM contact_profile_messages m JOIN latest l ON l.contact_id=m.contact_id AND l.page_id=m.page_id AND l.generation=m.generation WHERE m.sender='customer' AND m.text<>''
 UNION ALL SELECT coalesce(e.payload#>>'{entry,0,messaging,0,message,mid}',e.payload#>>'{entry,0,standby,0,message,mid}',e.event_key),e.occurred_at,left(coalesce(e.payload#>>'{entry,0,messaging,0,message,text}',e.payload#>>'{entry,0,standby,0,message,text}'),2500),'customer','launch_period_message',0
 FROM veo_event_inbox e JOIN job j ON j.page_id=e.page_id AND j.psid=coalesce(e.payload#>>'{entry,0,messaging,0,sender,id}',e.payload#>>'{entry,0,standby,0,sender,id}')
 WHERE coalesce(e.payload#>>'{entry,0,messaging,0,message,text}',e.payload#>>'{entry,0,standby,0,message,text}') IS NOT NULL
 UNION ALL SELECT proof->>'message_id',l.source_cutoff_at,left(proof->>'quote',2500),'customer','previously_cited_customer_answer',1
 FROM latest l CROSS JOIN LATERAL jsonb_array_elements(coalesce(l.payload->'extracted_answers','[]')) answer CROSS JOIN LATERAL jsonb_array_elements(coalesce(answer->'evidence','[]')) proof),
 unique_sources AS(SELECT DISTINCT ON(id) id,at,text,sender,basis FROM sources WHERE id IS NOT NULL AND text<>'' ORDER BY id,priority,at DESC),
 bounded AS(SELECT * FROM unique_sources ORDER BY at DESC,id LIMIT 24)
 SELECT jsonb_build_object('messages',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY at,id) FROM bounded b),'[]'),'coverage','Up to 24 saved customer excerpts and launch-period messages; not complete historical conversation') FROM job
$$;
CREATE FUNCTION veo_demographic_finish(p_contact uuid,p_claim uuid,p_fields jsonb,p_hash text,p_error text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE job veo_contact_demographics;merged jsonb;
BEGIN
 SELECT * INTO job FROM veo_contact_demographics WHERE contact_id=p_contact AND claim_token=p_claim AND lease_until>now() AND status='processing' FOR UPDATE;
 IF job.contact_id IS NULL OR NOT EXISTS(SELECT 1 FROM pages p JOIN veo_tenants t ON t.id=p.veo_tenant_id WHERE p.id=job.page_id AND p.veo_enabled AND veo_can_page(t.owner_id,p.id)) THEN RETURN false;END IF;
 IF p_error IS NULL AND jsonb_typeof(p_fields)<>'array' THEN RAISE EXCEPTION 'Invalid extracted demographic fields';END IF;
 SELECT coalesce(jsonb_agg(value),'[]') INTO merged FROM(SELECT DISTINCT ON(value->>'field') value FROM(
 SELECT value,0 AS priority FROM jsonb_array_elements(job.fields) UNION ALL SELECT value,1 FROM jsonb_array_elements(coalesce(p_fields,'[]'))) f ORDER BY value->>'field',
 (SELECT max((e->>'at')::timestamptz) FROM jsonb_array_elements(value->'evidence') e) DESC NULLS LAST,priority DESC) selected;
 UPDATE veo_contact_demographics SET fields=CASE WHEN p_error IS NULL THEN merged ELSE fields END,
 status=CASE WHEN p_error IS NOT NULL THEN 'error' WHEN requested_version>working_version THEN 'queued' ELSE 'ready' END,
 analyzed_version=CASE WHEN p_error IS NULL THEN working_version ELSE analyzed_version END,analyzed_at=CASE WHEN p_error IS NULL THEN now() ELSE analyzed_at END,
 source_hash=CASE WHEN p_error IS NULL THEN p_hash ELSE source_hash END,last_error=left(p_error,300),claim_token=NULL,lease_until=NULL,
 next_attempt_at=CASE WHEN p_error IS NOT NULL THEN now()+least(interval '6 hours',interval '1 minute'*power(2,least(attempts,8))) ELSE greatest(next_attempt_at,now()+interval '15 minutes') END WHERE contact_id=p_contact;
 RETURN true;
END $$;
-- Only demographic values, without citations or message text, enter cohort reports.
CREATE OR REPLACE FUNCTION veo_calendar_demographic_fields(p_fields jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
 SELECT coalesce(jsonb_object_agg(key,value),'{}') FROM jsonb_each(CASE WHEN jsonb_typeof(p_fields)='object' THEN p_fields ELSE '{}' END)
 WHERE regexp_replace(lower(key),'[ _-]','','g') IN('age','edad','gender','sex','kasarian','city','municipality','location','businesslocation','province','state','country','region','industry','businessindustry','businesstype','businesscategory','businesssubcategory','industrysubcategory','occupation','profession','trabaho','jobrole','jobtitle','role','preferredlanguage','languagepreference')
$$;
DO $$ DECLARE definition text;BEGIN
 definition:=pg_get_functiondef('veo_calendar_inputs(uuid,date,date,date,uuid)'::regprocedure);
 IF strpos(definition,'SELECT l.*,veo_calendar_demographic_fields(d.fields)')=0 THEN RAISE EXCEPTION 'Expected calendar demographic source is missing';END IF;
 EXECUTE replace(definition,'SELECT l.*,veo_calendar_demographic_fields(d.fields)','SELECT l.*,veo_demographic_values(l.id) AS ai_demographics,veo_calendar_demographic_fields(d.fields)');
END $$;
DO $$ DECLARE fn regprocedure;BEGIN
 FOR fn IN SELECT oid::regprocedure FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'veo_demographic_%' LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',fn);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',fn);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611070002_veo_demographics.sql','e2ae56698159a690a93cc4a55b486d8b29cc67ceeca6c6b2b443644dee594d97');

-- FILE: 202611070003_veo_calendar_read_only_inputs.sql SHA256: 1fd598bcbc39cd55d6a1b938cb271a33e6b53bcf9a2d3622b2b1ed3d912fe34d

-- Concurrent Page reads must not hold the same daily target/capacity row locks
-- while their historical cohort queries run. Prepare today's plan once instead.
CREATE FUNCTION veo_calendar_prepare(p_actor uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM veo_accounts WHERE user_id=p_actor AND active AND role IN('owner','team_leader')) THEN RAISE EXCEPTION 'Calendar access denied' USING ERRCODE='42501';END IF;
 PERFORM veo_target(user_id,veo_today()) FROM veo_accounts WHERE active AND role IN('member','manager') AND user_id IN(SELECT veo_descendants(p_actor));
 PERFORM veo_team_capacity(p_actor,veo_today()); PERFORM veo_page_capacity(p_actor,veo_today());
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION veo_calendar_prepare(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_calendar_prepare(uuid) TO service_role;
DO $$ DECLARE definition text;old_part text;BEGIN
 definition:=replace(pg_get_functiondef('veo_calendar_inputs(uuid,date,date,date,uuid)'::regprocedure),E'\r\n',E'\n');
 old_part:=$old$ PERFORM veo_target(user_id,veo_today()) FROM veo_accounts WHERE active AND role IN('member','manager') AND user_id IN(SELECT veo_descendants(p_actor));
 PERFORM veo_team_capacity(p_actor,veo_today()); PERFORM veo_page_capacity(p_actor,veo_today());$old$;
 IF strpos(definition,old_part)=0 THEN RAISE EXCEPTION 'Expected calendar planning writes are missing';END IF;
 EXECUTE replace(definition,old_part,'');
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611070003_veo_calendar_read_only_inputs.sql','1fd598bcbc39cd55d6a1b938cb271a33e6b53bcf9a2d3622b2b1ed3d912fe34d');

-- FILE: 202611070004_veo_employee_profiles.sql SHA256: 0033e1c124329f234465bfc580eb63831affa007d2b49e35052f151494ca0186

CREATE INDEX IF NOT EXISTS veo_employee_assignment_history ON veo_audit(entity_id,created_at,id)
 WHERE action IN('client_assignment','claim_client');
CREATE INDEX IF NOT EXISTS veo_employee_manual_replies ON outbound_message_events(actor_user_id,contact_id,sent_at)
 WHERE source_type='manual';
-- A supervisor's replacement of a Telegram declaration is a workspace entry.
DO $migration$ DECLARE definition text; BEGIN
 definition:=pg_get_functiondef('veo_work_action(uuid,text,jsonb)'::regprocedure);
 definition:=replace(definition,'updated_by=p_actor,updated_at=EXCLUDED.updated_at;', 'updated_by=p_actor,updated_at=EXCLUDED.updated_at,source=''workspace'';');
 EXECUTE definition;
END $migration$;

-- One employee dossier. Salary uses the existing authoritative daily calculation;
-- ranking always includes all permitted peers before selecting the employee.
CREATE FUNCTION veo_employee_profile(p_actor uuid,p_worker uuid,p_from date,p_to date,p_page uuid DEFAULT NULL) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 DECLARE actor veo_accounts; worker veo_accounts; tenant veo_tenants; finance jsonb; result jsonb; capacity jsonb;
 BEGIN
 SELECT * INTO actor FROM veo_accounts WHERE user_id=p_actor AND active;
 SELECT * INTO tenant FROM veo_tenants WHERE id=actor.tenant_id AND launch_at IS NOT NULL;
 SELECT * INTO worker FROM veo_accounts WHERE user_id=p_worker AND tenant_id=actor.tenant_id AND role IN('manager','member');
 IF actor.user_id IS NULL OR tenant.id IS NULL OR worker.user_id IS NULL OR p_worker NOT IN(SELECT veo_branch(p_actor))
 OR(p_page IS NOT NULL AND NOT veo_can_page(p_actor,p_page)) THEN RAISE EXCEPTION 'Employee access denied' USING ERRCODE='42501'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_from>p_to OR p_to-p_from>92 OR p_from<(tenant.launch_at AT TIME ZONE 'Asia/Manila')::date OR p_to>veo_today()
 THEN RAISE EXCEPTION 'Choose up to 93 Philippine dates within the launched period'; END IF;
 finance:=veo_finance_days(p_actor,p_from,p_to,p_page,p_worker);
 capacity:=coalesce((SELECT basis||jsonb_build_object('target',target,'snapshot',true,'snapshot_at',created_at) FROM veo_daily_targets WHERE user_id=p_worker AND work_date=veo_today()),
 veo_capacity(p_worker,veo_today())||jsonb_build_object('snapshot',false));
 WITH visible_pages AS MATERIALIZED(SELECT id,name FROM pages WHERE veo_can_page(p_actor,id) AND(p_page IS NULL OR id=p_page)),
 facts AS MATERIALIZED(SELECT f.* FROM veo_work_facts f JOIN visible_pages p ON p.id=f.page_id WHERE f.tenant_id=actor.tenant_id
 AND f.created_at>=tenant.launch_at AND f.seller_id IN(SELECT veo_branch(p_actor))),
 personal AS MATERIALIZED(SELECT * FROM facts WHERE seller_id=p_worker),
 peers AS MATERIALIZED(SELECT a.user_id,a.enrolled_at,a.departed_at FROM veo_accounts a WHERE a.tenant_id=actor.tenant_id AND a.role IN('member','manager')
 AND a.user_id IN(SELECT veo_branch(p_actor)) AND(a.user_id=p_worker OR EXISTS(SELECT 1 FROM user_pages up JOIN visible_pages p ON p.id=up.page_id WHERE up.user_id=a.user_id) OR EXISTS(SELECT 1 FROM facts f WHERE f.seller_id=a.user_id))),
 milestones AS(SELECT seller_id AS user_id,closed_date AS day,1 AS cd,0 AS dd FROM facts WHERE closed_date BETWEEN p_from AND p_to
 UNION ALL SELECT seller_id,done_date,0,1 FROM facts WHERE done_date BETWEEN p_from AND p_to),
 counts AS(SELECT user_id,day,sum(cd)::int AS closed,sum(dd)::int AS done FROM milestones GROUP BY user_id,day),
 frames AS(SELECT p.user_id,d::date AS day,coalesce(c.closed,0) AS closed,coalesce(c.done,0) AS done FROM peers p
 CROSS JOIN generate_series(p_from::timestamp,p_to::timestamp,interval '1 day') d LEFT JOIN counts c ON c.user_id=p.user_id AND c.day=d::date
 WHERE ((p.enrolled_at AT TIME ZONE 'Asia/Manila')::date<=d::date AND(p.departed_at IS NULL OR(p.departed_at AT TIME ZONE 'Asia/Manila')::date>=d::date)) OR c.user_id IS NOT NULL),
 ranked AS(SELECT *,dense_rank() OVER(PARTITION BY day ORDER BY done DESC,closed DESC) AS rank,count(*) OVER(PARTITION BY day)::int AS peers FROM frames),
 range_counts AS(SELECT p.user_id,coalesce(sum(c.closed),0)::int AS closed,coalesce(sum(c.done),0)::int AS done FROM peers p LEFT JOIN counts c ON c.user_id=p.user_id
 WHERE EXISTS(SELECT 1 FROM frames f WHERE f.user_id=p.user_id) GROUP BY p.user_id),
 range_rank AS(SELECT *,dense_rank() OVER(ORDER BY done DESC,closed DESC) AS rank,count(*) OVER()::int AS peers FROM range_counts),
 peak_days AS(SELECT d.day,sum(d.cd)::int AS closed,sum(d.dd)::int AS done FROM(
 SELECT closed_date AS day,1 AS cd,0 AS dd FROM personal WHERE closed_date IS NOT NULL
 UNION ALL SELECT done_date,0,1 FROM personal WHERE done_date IS NOT NULL) d GROUP BY d.day),
 -- Reconstruct recorded ownership intervals, including reassignment and departure.
 -- Never give every worker on a shared Page credit for the Page's inquiries/replies.
 ownership_events AS MATERIALIZED(SELECT v.entity_id AS contact_id,(v.after_value->>'user_id')::uuid AS user_id,
 coalesce((v.after_value->>'claimed_at')::timestamptz,v.created_at) AS start_at,v.id AS seq
 FROM veo_audit v JOIN contacts c ON c.id=v.entity_id JOIN visible_pages p ON p.id=c.page_id
 WHERE v.tenant_id=actor.tenant_id AND v.action IN('client_assignment','claim_client') AND v.after_value->>'user_id' IS NOT NULL
 UNION ALL SELECT c.contact_id,c.user_id,c.claimed_at,0 FROM veo_client_claims c JOIN visible_pages p ON p.id=c.page_id
 WHERE c.tenant_id=actor.tenant_id AND c.user_id IS NOT NULL AND c.claimed_at IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM veo_audit v WHERE v.entity_id=c.contact_id AND v.action IN('client_assignment','claim_client') AND v.after_value->>'user_id'=c.user_id::text
 AND coalesce((v.after_value->>'claimed_at')::timestamptz,v.created_at)=c.claimed_at)),
 ordered_events AS(SELECT *,lag(user_id) OVER(PARTITION BY contact_id ORDER BY start_at,seq) AS previous_user FROM ownership_events),
 sequenced AS(SELECT *,lead(start_at) OVER(PARTITION BY contact_id ORDER BY start_at,seq) AS next_at FROM ordered_events WHERE previous_user IS DISTINCT FROM user_id),
 ownership AS MATERIALIZED(SELECT s.contact_id,c.page_id,c.psid,greatest(s.start_at,tenant.launch_at) AS start_at,
 least(coalesce(s.next_at,'infinity'::timestamptz),coalesce(worker.departed_at,'infinity'::timestamptz),
 CASE WHEN cc.user_id IS NULL AND cc.released_at>=s.start_at THEN cc.released_at ELSE 'infinity'::timestamptz END) AS end_at
 FROM sequenced s JOIN contacts c ON c.id=s.contact_id LEFT JOIN veo_client_claims cc ON cc.contact_id=s.contact_id
 WHERE s.user_id=p_worker AND s.start_at>=tenant.launch_at),
 assigned_cohort AS MATERIALIZED(SELECT o.contact_id,bool_or(EXISTS(SELECT 1 FROM personal f WHERE f.contact_id=o.contact_id AND f.closed_date IS NOT NULL AND f.closed_at>=o.start_at AND f.closed_at<o.end_at)) AS converted
 FROM ownership o WHERE(o.start_at AT TIME ZONE 'Asia/Manila')::date BETWEEN p_from AND p_to GROUP BY o.contact_id),
 incoming AS MATERIALIZED(SELECT DISTINCT m.page_id,m.message_id,m.client_psid,m.occurred_at,(m.occurred_at AT TIME ZONE 'Asia/Manila')::date AS day,o.contact_id,o.end_at
 FROM ownership o JOIN veo_calendar_messages m ON m.page_id=o.page_id AND m.client_psid=o.psid AND m.direction='in' AND m.occurred_at>=o.start_at AND m.occurred_at<o.end_at
 WHERE m.occurred_at>=p_from::timestamp AT TIME ZONE 'Asia/Manila' AND m.occurred_at<(p_to+1)::timestamp AT TIME ZONE 'Asia/Manila'),
 responses AS MATERIALIZED(SELECT i.*,EXISTS(SELECT 1 FROM outbound_message_events e WHERE e.actor_user_id=p_worker AND e.source_type='manual' AND e.contact_id=i.contact_id AND e.page_id=i.page_id
 AND e.sent_at>=i.occurred_at AND e.sent_at<=i.occurred_at+interval '24 hours' AND e.sent_at<i.end_at) AS answered,
 EXISTS(SELECT 1 FROM veo_calendar_messages m WHERE m.page_id=i.page_id AND m.client_psid=i.client_psid AND m.direction='out' AND m.occurred_at>=i.occurred_at
 AND m.occurred_at<=i.occurred_at+interval '24 hours' AND m.occurred_at<i.end_at AND NOT EXISTS(SELECT 1 FROM outbound_message_events e WHERE e.page_id=m.page_id AND e.message_id=m.message_id AND(e.actor_user_id IS NOT NULL OR e.source_type<>'manual'))) AS unattributed
 FROM incoming i),
 reply_days AS(SELECT day,count(DISTINCT contact_id)::int AS incoming_clients,count(DISTINCT contact_id) FILTER(WHERE answered)::int AS answered_clients,
 count(DISTINCT contact_id) FILTER(WHERE unattributed AND NOT answered)::int AS unattributed_clients FROM responses GROUP BY day),
 daily AS(SELECT d.value||jsonb_build_object('totals',coalesce((SELECT jsonb_agg(t.value||jsonb_build_object('order_gross_minor',
 (SELECT coalesce(sum(f.total_minor),0) FROM personal f WHERE f.done_date=(d.value->>'work_date')::date AND f.currency=t.value->>'currency')))
 FROM jsonb_array_elements(d.value->'totals') t),'[]'),
 'target_snapshot',EXISTS(SELECT 1 FROM veo_daily_targets dt WHERE dt.user_id=p_worker AND dt.work_date=(d.value->>'work_date')::date),
 'attendance',CASE WHEN att.user_id IS NULL THEN NULL ELSE jsonb_build_object('active',att.active,'source',att.source,'updated_at',att.updated_at) END,
 'rank',CASE WHEN actor.role<>'member' AND r.closed+r.done>0 THEN r.rank END,'peers',CASE WHEN actor.role<>'member' THEN r.peers END,
 'replies',jsonb_build_object('incoming_clients',coalesce(rd.incoming_clients,0),'answered_clients',coalesce(rd.answered_clients,0),'unattributed_clients',coalesce(rd.unattributed_clients,0))) AS value
 FROM jsonb_array_elements(finance->'days') d LEFT JOIN ranked r ON r.user_id=p_worker AND r.day=(d.value->>'work_date')::date
 LEFT JOIN veo_attendance att ON att.user_id=p_worker AND att.work_date=(d.value->>'work_date')::date LEFT JOIN reply_days rd ON rd.day=(d.value->>'work_date')::date),
 cd_cohort AS MATERIALIZED(SELECT * FROM personal WHERE closed_date BETWEEN p_from AND p_to),
 client_list AS(SELECT c.id AS contact_id,c.name,c.page_id,p.name AS page_name,cc.claimed_at,cc.user_id=p_worker AS currently_assigned,
 (SELECT count(*)::int FROM personal f WHERE f.contact_id=c.id AND f.closed_date IS NOT NULL) AS closed,
 (SELECT count(*)::int FROM personal f WHERE f.contact_id=c.id AND f.done_date IS NOT NULL) AS done,
 greatest(cc.claimed_at,(SELECT max(created_at) FROM personal f WHERE f.contact_id=c.id)) AS last_recorded_at
 FROM contacts c JOIN visible_pages p ON p.id=c.page_id LEFT JOIN veo_client_claims cc ON cc.contact_id=c.id
 WHERE cc.user_id=p_worker OR EXISTS(SELECT 1 FROM personal f WHERE f.contact_id=c.id))
 SELECT jsonb_build_object('employee',jsonb_build_object('id',p_worker,'name',(SELECT name FROM users WHERE id=p_worker),'role',worker.role,'active',worker.active,
 'enrolled_at',worker.enrolled_at,'departed_at',worker.departed_at,'telegram_username',worker.telegram_username,'supervisor',(SELECT name FROM users WHERE id=worker.parent_id),
 'pages',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.name) FROM visible_pages p JOIN user_pages up ON up.page_id=p.id WHERE up.user_id=p_worker),'[]'),
 'active_today',(SELECT active FROM veo_attendance WHERE user_id=p_worker AND work_date=veo_today()),'active_tomorrow',(SELECT active FROM veo_attendance WHERE user_id=p_worker AND work_date=veo_today()+1)),
 'from',p_from,'to',p_to,'as_of',now(),'launch_at',tenant.launch_at,'page_id',p_page,
 'ranking_scope',CASE actor.role WHEN 'owner' THEN 'Overall VEO' WHEN 'team_leader' THEN 'Your branch' WHEN 'manager' THEN 'Your team' ELSE 'Personal view; peer ranking unavailable' END,
 'ranking',(SELECT jsonb_build_object('rank',CASE WHEN actor.role<>'member' AND closed+done>0 THEN rank END,'peers',CASE WHEN actor.role<>'member' THEN peers END) FROM range_rank WHERE user_id=p_worker),
 'capacity',capacity||jsonb_build_object('work_date',veo_today(),'observed_max_done',coalesce((SELECT max(done) FROM peak_days),0),'observed_max_closed',coalesce((SELECT max(closed) FROM peak_days),0),
 'peak_done_dates',coalesce((SELECT jsonb_agg(day ORDER BY day DESC) FROM peak_days WHERE done>0 AND done=(SELECT max(done) FROM peak_days)),'[]')),
 'summary',jsonb_build_object('closed',(SELECT count(*) FROM personal WHERE closed_date BETWEEN p_from AND p_to),'done',(SELECT count(*) FROM personal WHERE done_date BETWEEN p_from AND p_to),
 'cd_cohort',(SELECT count(*) FROM cd_cohort),'cd_cohort_done',(SELECT count(*) FROM cd_cohort WHERE done_date IS NOT NULL),
 'cd_to_dd_hours_mean',(SELECT avg(extract(epoch FROM done_at-closed_at)/3600) FROM cd_cohort WHERE done_date IS NOT NULL),
 'cd_to_dd_hours_median',(SELECT percentile_cont(0.5) WITHIN GROUP(ORDER BY extract(epoch FROM done_at-closed_at)/3600) FROM cd_cohort WHERE done_date IS NOT NULL),
 'waiting_payment',(SELECT count(*) FROM personal WHERE converted AND waiting_payment),'overdue',(SELECT count(*) FROM personal WHERE converted AND overdue),
 'assigned_cohort',(SELECT count(*) FROM assigned_cohort),'assigned_cohort_converted',(SELECT count(*) FROM assigned_cohort WHERE converted),
 'reply_client_days',(SELECT coalesce(sum(incoming_clients),0) FROM reply_days),'answered_client_days',(SELECT coalesce(sum(answered_clients),0) FROM reply_days),
 'unattributed_reply_client_days',(SELECT coalesce(sum(unattributed_clients),0) FROM reply_days)),
 'reply_coverage',jsonb_build_object('pages',coalesce((SELECT jsonb_agg(jsonb_build_object('page_id',p.id,'name',p.name,'capture_from',c.capture_from)) FROM visible_pages p
 LEFT JOIN veo_calendar_message_coverage c ON c.page_id=p.id WHERE EXISTS(SELECT 1 FROM user_pages up WHERE up.user_id=p_worker AND up.page_id=p.id) OR EXISTS(SELECT 1 FROM ownership o WHERE o.page_id=p.id)),'[]')),
 'days',coalesce((SELECT jsonb_agg(value ORDER BY value->>'work_date' DESC) FROM daily),'[]'),
 'clients',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.currently_assigned DESC NULLS LAST,c.last_recorded_at DESC NULLS LAST,c.contact_id) FROM(SELECT * FROM client_list ORDER BY currently_assigned DESC NULLS LAST,last_recorded_at DESC NULLS LAST,contact_id LIMIT 50) c),'[]'),
 'client_count',(SELECT count(*) FROM client_list),'coverage','Verified workspace sales since launch. Current seller attribution and audited corrections apply. Retained legacy sales are excluded. Attendance is declared participation, not time-clock attendance. Reply counts require recorded ownership and a manual reply attributed to this worker within 24 hours; bot and unattributed Page replies do not count as personal replies.') INTO result;
 RETURN result;
 END $$;
REVOKE ALL ON FUNCTION veo_employee_profile(uuid,uuid,date,date,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_employee_profile(uuid,uuid,date,date,uuid) TO service_role;
NOTIFY pgrst,'reload schema';


