-- FILE: 202611080003_veo_telegram_groups.sql SHA256: a6b62e091573500573d7188a9a2409b62459d145864feb2cddfd05bdb8b7a71d

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;
ALTER TABLE veo_teams ADD COLUMN telegram_groups_managed boolean NOT NULL DEFAULT false;
CREATE TABLE veo_telegram_groups(
 tenant_id uuid NOT NULL REFERENCES veo_tenants(id),chat_id bigint NOT NULL CHECK(chat_id<0),name text NOT NULL,
 topics jsonb NOT NULL DEFAULT '{}',discovered_pages jsonb NOT NULL DEFAULT '[]',identities jsonb NOT NULL DEFAULT '[]',
 active boolean NOT NULL DEFAULT true,checked_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,chat_id)
);
CREATE TABLE veo_team_telegram_groups(
 team_id uuid NOT NULL REFERENCES veo_teams(id),tenant_id uuid NOT NULL REFERENCES veo_tenants(id),chat_id bigint NOT NULL,
 thread_id bigint CHECK(thread_id>0),updated_by uuid NOT NULL REFERENCES veo_accounts(user_id),updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(team_id,chat_id),FOREIGN KEY(tenant_id,chat_id) REFERENCES veo_telegram_groups(tenant_id,chat_id)
);
CREATE TABLE veo_team_telegram_pages(
 team_id uuid NOT NULL,page_id uuid NOT NULL REFERENCES pages(id),chat_id bigint NOT NULL,
 PRIMARY KEY(team_id,page_id),FOREIGN KEY(team_id,chat_id) REFERENCES veo_team_telegram_groups(team_id,chat_id) ON DELETE CASCADE
);
CREATE TABLE veo_telegram_memberships(
 user_id uuid NOT NULL REFERENCES veo_accounts(user_id),tenant_id uuid NOT NULL REFERENCES veo_tenants(id),chat_id bigint NOT NULL,
 telegram_user_id bigint NOT NULL CHECK(telegram_user_id>0),verified_at timestamptz NOT NULL DEFAULT now(),verified_by uuid NOT NULL REFERENCES veo_accounts(user_id),
 PRIMARY KEY(user_id,chat_id),FOREIGN KEY(tenant_id,chat_id) REFERENCES veo_telegram_groups(tenant_id,chat_id)
);
CREATE TABLE veo_telegram_group_states(
 user_id uuid NOT NULL,chat_id bigint NOT NULL,telegram_user_id bigint NOT NULL,payload jsonb NOT NULL,observed_at timestamptz NOT NULL,
 PRIMARY KEY(user_id,chat_id),FOREIGN KEY(user_id,chat_id) REFERENCES veo_telegram_memberships(user_id,chat_id) ON DELETE CASCADE
);
CREATE INDEX veo_telegram_membership_identity ON veo_telegram_memberships(tenant_id,telegram_user_id,chat_id);

CREATE FUNCTION veo_staff_can_telegram_group(p_user uuid,p_chat bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM veo_accounts a JOIN users u ON u.id=a.user_id AND u.is_active JOIN veo_telegram_groups g ON g.tenant_id=a.tenant_id AND g.chat_id=p_chat AND g.active
 WHERE a.user_id=p_user AND a.active AND EXISTS(
 SELECT 1 FROM veo_team_telegram_groups l JOIN veo_teams t ON t.id=l.team_id JOIN veo_team_telegram_pages r ON r.team_id=l.team_id AND r.chat_id=l.chat_id
 WHERE l.tenant_id=a.tenant_id AND l.chat_id=p_chat AND veo_can_page(p_user,r.page_id) AND veo_can_page(t.manager_id,r.page_id)
 AND(a.role='owner' OR(a.role='team_leader' AND t.manager_id IN(SELECT veo_descendants(p_user))) OR t.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END)))
$$;

CREATE FUNCTION veo_sync_telegram_groups(p_actor uuid,p_groups jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a veo_accounts;g jsonb;BEGIN
 SELECT * INTO a FROM veo_accounts WHERE user_id=p_actor AND active AND role='owner';
 IF a.user_id IS NULL THEN RAISE EXCEPTION 'Head access required to fetch the bot directory' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_groups) IS DISTINCT FROM 'array' OR jsonb_array_length(p_groups)>200 THEN RAISE EXCEPTION 'Invalid bot directory';END IF;
 UPDATE veo_telegram_groups SET active=false WHERE tenant_id=a.tenant_id;
 FOR g IN SELECT value FROM jsonb_array_elements(p_groups) LOOP
  IF (g->>'chat_id')::bigint>=0 OR length(g->>'name')>200 OR jsonb_typeof(g->'pages') IS DISTINCT FROM 'array' OR jsonb_typeof(g->'identities') IS DISTINCT FROM 'array' OR length(g::text)>1000000 THEN RAISE EXCEPTION 'Invalid group metadata';END IF;
  INSERT INTO veo_telegram_groups(tenant_id,chat_id,name,topics,discovered_pages,identities,active,checked_at)
  VALUES(a.tenant_id,(g->>'chat_id')::bigint,g->>'name',coalesce(g->'topics','{}'),g->'pages',g->'identities',true,clock_timestamp())
  ON CONFLICT(tenant_id,chat_id) DO UPDATE SET name=EXCLUDED.name,topics=EXCLUDED.topics,discovered_pages=EXCLUDED.discovered_pages,identities=EXCLUDED.identities,active=true,checked_at=EXCLUDED.checked_at;
 END LOOP;
 INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value) VALUES(a.tenant_id,p_actor,'telegram_directory_refresh',a.tenant_id,jsonb_build_object('groups',jsonb_array_length(p_groups)));
 RETURN jsonb_build_object('saved',true,'groups',jsonb_array_length(p_groups));
END $$;

CREATE FUNCTION veo_telegram_groups_page(p_actor uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off SET plan_cache_mode=force_custom_plan AS $$
DECLARE a veo_accounts;branch uuid[];ids uuid[];BEGIN
 SELECT * INTO a FROM veo_accounts WHERE user_id=p_actor AND active;
 IF a.user_id IS NULL THEN RAISE EXCEPTION 'Workspace access denied' USING ERRCODE='42501';END IF;
 SELECT coalesce(array_agg(id),'{}') INTO branch FROM veo_descendants(p_actor) id;
 SELECT coalesce(array_agg(id),'{}') INTO ids FROM pages WHERE veo_can_page(p_actor,id);
 RETURN jsonb_build_object('scope',veo_scope(p_actor),'can_manage',a.role IN('owner','team_leader','manager'),
 'pages',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name) FROM pages WHERE id=ANY(ids)),'[]'),
 'teams',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.name) FROM veo_teams t WHERE t.tenant_id=a.tenant_id AND t.manager_id=ANY(branch)),'[]'),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',w.user_id,'name',u.name,'role',w.role,'parent_id',w.parent_id,'telegram_username',w.telegram_username,'telegram_user_id',m.telegram_user_id,
 'page_ids',ARRAY(SELECT p.id FROM pages p WHERE p.id=ANY(ids) AND veo_can_page(w.user_id,p.id))) ORDER BY u.name) FROM veo_accounts w JOIN users u ON u.id=w.user_id LEFT JOIN veo_worker_mappings m ON m.user_id=w.user_id WHERE w.active AND w.user_id=ANY(branch)),'[]'),
 'groups',coalesce((SELECT jsonb_agg(jsonb_build_object('chat_id',g.chat_id,'name',g.name,'topics',g.topics,'active',g.active,'checked_at',g.checked_at,
 'pages',CASE WHEN a.role='owner' THEN g.discovered_pages ELSE coalesce((SELECT jsonb_agg(p.value) FROM jsonb_array_elements(g.discovered_pages) p WHERE p.value->>'id'=ANY(ARRAY(SELECT id::text FROM unnest(ids) id))),'[]') END,
 'identities',CASE WHEN a.role='owner' OR EXISTS(SELECT 1 FROM veo_team_telegram_groups l JOIN veo_teams t ON t.id=l.team_id WHERE l.chat_id=g.chat_id AND t.manager_id=ANY(branch)) THEN g.identities ELSE '[]'::jsonb END)
 ORDER BY g.name) FROM veo_telegram_groups g WHERE g.tenant_id=a.tenant_id AND(a.role='owner' OR EXISTS(SELECT 1 FROM veo_team_telegram_groups l JOIN veo_teams t ON t.id=l.team_id WHERE l.chat_id=g.chat_id AND t.manager_id=ANY(branch))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(g.discovered_pages) p WHERE p.value->>'id'=ANY(ARRAY(SELECT id::text FROM unnest(ids) id))) OR EXISTS(SELECT 1 FROM veo_telegram_memberships m WHERE m.user_id=p_actor AND m.chat_id=g.chat_id))),'[]'),
 'links',coalesce((SELECT jsonb_agg(to_jsonb(l)) FROM veo_team_telegram_groups l JOIN veo_teams t ON t.id=l.team_id WHERE l.tenant_id=a.tenant_id AND t.manager_id=ANY(branch)),'[]'),
 'routes',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM veo_team_telegram_pages r JOIN veo_teams t ON t.id=r.team_id WHERE t.tenant_id=a.tenant_id AND t.manager_id=ANY(branch) AND r.page_id=ANY(ids)),'[]'),
 'memberships',coalesce((SELECT jsonb_agg(to_jsonb(m)||jsonb_build_object('state',s.payload->>'membership','checked_at',s.observed_at)) FROM veo_telegram_memberships m LEFT JOIN veo_telegram_group_states s USING(user_id,chat_id) WHERE m.tenant_id=a.tenant_id AND m.user_id=ANY(branch)),'[]'),
 'coverage','Approved VEO groups registered with Jaucian. Page metadata is not a permission grant. Observed identities are not a complete membership list.');
END $$;

CREATE FUNCTION veo_telegram_group_action(p_actor uuid,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a veo_accounts;t veo_teams;w veo_accounts;chat bigint;uid bigint;pg uuid;ids uuid[];old jsonb;BEGIN
 SELECT * INTO a FROM veo_accounts WHERE user_id=p_actor AND active AND role IN('owner','team_leader','manager');
 IF a.user_id IS NULL THEN RAISE EXCEPTION 'Supervisor access required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-telegram-groups:'||a.tenant_id::text,0));
 chat:=(p_data->>'chat_id')::bigint;
 IF NOT EXISTS(SELECT 1 FROM veo_telegram_groups WHERE tenant_id=a.tenant_id AND chat_id=chat AND active) AND p_action NOT IN('remove_group','remove_membership') THEN RAISE EXCEPTION 'Fetch the approved active bot groups first';END IF;
 IF p_action IN('group','remove_group') THEN
  SELECT * INTO t FROM veo_teams WHERE id=(p_data->>'team_id')::uuid AND tenant_id=a.tenant_id FOR UPDATE;
  IF t.id IS NULL OR t.manager_id NOT IN(SELECT veo_descendants(p_actor)) THEN RAISE EXCEPTION 'Team is outside your branch' USING ERRCODE='42501';END IF;
  old:=to_jsonb(t);
  IF NOT t.telegram_groups_managed AND t.telegram_chat_id IS NOT NULL AND EXISTS(SELECT 1 FROM veo_telegram_groups WHERE tenant_id=a.tenant_id AND chat_id=t.telegram_chat_id AND active) THEN
   INSERT INTO veo_team_telegram_groups VALUES(t.id,a.tenant_id,t.telegram_chat_id,t.telegram_thread_id,p_actor,now()) ON CONFLICT DO NOTHING;
   INSERT INTO veo_team_telegram_pages SELECT t.id,p.id,t.telegram_chat_id FROM pages p WHERE veo_can_page(t.manager_id,p.id) ON CONFLICT DO NOTHING;
   INSERT INTO veo_telegram_memberships(user_id,tenant_id,chat_id,telegram_user_id,verified_at,verified_by)
   SELECT s.user_id,a.tenant_id,s.telegram_chat_id,m.telegram_user_id,s.verified_at,p_actor FROM veo_staff_telegram_groups s JOIN veo_worker_mappings m USING(user_id)
   WHERE s.telegram_chat_id=t.telegram_chat_id AND veo_staff_can_telegram_group(s.user_id,t.telegram_chat_id) ON CONFLICT DO NOTHING;
  END IF;
  IF p_action='group' THEN
   IF jsonb_typeof(p_data->'page_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'page_ids') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Choose at least one Page';END IF;
   SELECT array_agg(DISTINCT value::uuid) INTO ids FROM jsonb_array_elements_text(p_data->'page_ids');
   FOREACH pg IN ARRAY ids LOOP
    IF NOT veo_can_page(p_actor,pg) OR NOT veo_can_page(t.manager_id,pg) THEN RAISE EXCEPTION 'Grant only Pages permitted for both you and the team manager' USING ERRCODE='42501';END IF;
    IF a.role<>'owner' AND NOT EXISTS(SELECT 1 FROM veo_team_telegram_groups l JOIN veo_teams x ON x.id=l.team_id WHERE l.chat_id=chat AND x.manager_id IN(SELECT veo_descendants(p_actor)))
     AND NOT EXISTS(SELECT 1 FROM veo_telegram_groups g CROSS JOIN LATERAL jsonb_array_elements(g.discovered_pages) p WHERE g.tenant_id=a.tenant_id AND g.chat_id=chat AND p.value->>'id'=pg::text)
    THEN RAISE EXCEPTION 'Head must link this group before adding Pages beyond its registered scope' USING ERRCODE='42501';END IF;
    IF EXISTS(SELECT 1 FROM veo_team_telegram_pages WHERE team_id=t.id AND page_id=pg AND chat_id<>chat) AND coalesce((p_data->>'move_pages')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'A selected Page is linked to another group. Explicitly choose Move Pages to change its destination' USING ERRCODE='23505';END IF;
   END LOOP;
   INSERT INTO veo_team_telegram_groups VALUES(t.id,a.tenant_id,chat,nullif(p_data->>'thread_id','')::bigint,p_actor,clock_timestamp())
   ON CONFLICT(team_id,chat_id) DO UPDATE SET thread_id=EXCLUDED.thread_id,updated_by=p_actor,updated_at=clock_timestamp();
   DELETE FROM veo_team_telegram_pages r WHERE r.team_id=t.id AND r.chat_id=chat AND NOT(r.page_id=ANY(ids)) AND veo_can_page(p_actor,r.page_id);
   INSERT INTO veo_team_telegram_pages SELECT t.id,p,chat FROM unnest(ids) p ON CONFLICT(team_id,page_id) DO UPDATE SET chat_id=EXCLUDED.chat_id;
   UPDATE veo_teams SET telegram_groups_managed=true,telegram_chat_id=CASE WHEN telegram_chat_id IS NULL OR coalesce((p_data->>'primary')::boolean,false) THEN chat ELSE telegram_chat_id END,
    telegram_thread_id=CASE WHEN telegram_chat_id IS NULL OR coalesce((p_data->>'primary')::boolean,false) OR telegram_chat_id=chat THEN nullif(p_data->>'thread_id','')::bigint ELSE telegram_thread_id END WHERE id=t.id;
  ELSE
   IF EXISTS(SELECT 1 FROM veo_team_telegram_pages WHERE team_id=t.id AND chat_id=chat AND NOT veo_can_page(p_actor,page_id)) THEN RAISE EXCEPTION 'Head must remove group links containing Pages outside your scope' USING ERRCODE='42501';END IF;
   DELETE FROM veo_team_telegram_groups WHERE team_id=t.id AND chat_id=chat;
   UPDATE veo_teams SET telegram_groups_managed=true,telegram_chat_id=(SELECT chat_id FROM veo_team_telegram_groups WHERE team_id=t.id ORDER BY updated_at LIMIT 1),
    telegram_thread_id=(SELECT thread_id FROM veo_team_telegram_groups WHERE team_id=t.id ORDER BY updated_at LIMIT 1) WHERE id=t.id AND(telegram_chat_id=chat OR telegram_chat_id IS NULL);
  END IF;
  INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,before_value,after_value) VALUES(a.tenant_id,p_actor,'telegram_'||p_action,t.id,old,p_data);
 ELSIF p_action IN('membership','remove_membership') THEN
  SELECT * INTO w FROM veo_accounts WHERE user_id=(p_data->>'user_id')::uuid AND tenant_id=a.tenant_id AND active FOR UPDATE;
  IF w.user_id IS NULL OR w.user_id NOT IN(SELECT veo_descendants(p_actor)) THEN RAISE EXCEPTION 'Staff account is outside your branch' USING ERRCODE='42501';END IF;
  IF p_action='membership' THEN
   uid:=(p_data->>'telegram_user_id')::bigint;
   IF uid IS NULL OR uid<=0 OR NOT veo_staff_can_telegram_group(w.user_id,chat) THEN RAISE EXCEPTION 'Choose a linked group with permitted Pages for this person';END IF;
   IF EXISTS(SELECT 1 FROM veo_telegram_memberships WHERE user_id=w.user_id AND telegram_user_id<>uid) THEN RAISE EXCEPTION 'Use the same verified Telegram identity across groups; remove old memberships before changing identity';END IF;
   IF EXISTS(SELECT 1 FROM veo_worker_mappings m JOIN veo_accounts x USING(user_id) WHERE x.tenant_id=a.tenant_id AND x.active AND m.telegram_user_id=uid AND m.user_id<>w.user_id) THEN RAISE EXCEPTION 'That Telegram identity already belongs to another active account' USING ERRCODE='23505';END IF;
   INSERT INTO veo_worker_mappings VALUES(w.user_id,uid) ON CONFLICT(user_id) DO UPDATE SET telegram_user_id=EXCLUDED.telegram_user_id;
   INSERT INTO veo_telegram_memberships VALUES(w.user_id,a.tenant_id,chat,uid,clock_timestamp(),p_actor) ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=uid,verified_at=clock_timestamp(),verified_by=p_actor;
   DELETE FROM veo_telegram_group_states WHERE user_id=w.user_id AND chat_id=chat;
   IF coalesce((p_data->>'primary')::boolean,false) OR NOT EXISTS(SELECT 1 FROM veo_staff_telegram_groups WHERE user_id=w.user_id) THEN
    INSERT INTO veo_staff_telegram_groups VALUES(w.user_id,chat,clock_timestamp()) ON CONFLICT(user_id) DO UPDATE SET telegram_chat_id=chat,verified_at=clock_timestamp();
   END IF;
  ELSE
   DELETE FROM veo_telegram_memberships WHERE user_id=w.user_id AND chat_id=chat;
   DELETE FROM veo_staff_telegram_groups WHERE user_id=w.user_id AND telegram_chat_id=chat;
   INSERT INTO veo_staff_telegram_groups SELECT w.user_id,m.chat_id,m.verified_at FROM veo_telegram_memberships m WHERE m.user_id=w.user_id AND veo_staff_can_telegram_group(w.user_id,m.chat_id) ORDER BY m.verified_at LIMIT 1 ON CONFLICT DO NOTHING;
  END IF;
  INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value) VALUES(a.tenant_id,p_actor,'telegram_'||p_action,w.user_id,p_data);
 ELSE RAISE EXCEPTION 'Unknown group action';END IF;
 RETURN jsonb_build_object('saved',true);
END $$;

CREATE FUNCTION veo_telegram_destination(p_team uuid,p_page uuid,p_user uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE t veo_teams;r record;BEGIN
 SELECT * INTO t FROM veo_teams WHERE id=p_team;
 IF NOT t.telegram_groups_managed THEN RETURN jsonb_build_object('chat_id',t.telegram_chat_id,'thread_id',t.telegram_thread_id);END IF;
 SELECT l.chat_id,l.thread_id INTO r FROM veo_team_telegram_pages p JOIN veo_team_telegram_groups l USING(team_id,chat_id) JOIN veo_telegram_groups g ON g.tenant_id=l.tenant_id AND g.chat_id=l.chat_id AND g.active
 WHERE p.team_id=p_team AND p.page_id=p_page AND veo_can_page(t.manager_id,p_page) AND veo_can_page(p_user,p_page)
 AND EXISTS(SELECT 1 FROM veo_telegram_memberships m JOIN veo_worker_mappings w USING(user_id) WHERE m.user_id=p_user AND m.chat_id=l.chat_id AND m.telegram_user_id=w.telegram_user_id);
 RETURN CASE WHEN FOUND THEN jsonb_build_object('chat_id',r.chat_id,'thread_id',r.thread_id) ELSE NULL END;
END $$;
ALTER FUNCTION veo_handoff(uuid) RENAME TO veo_handoff_before_groups;
CREATE FUNCTION veo_handoff(p_submission uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;dest jsonb;BEGIN
 result:=veo_handoff_before_groups(p_submission);IF result IS NULL THEN RETURN NULL;END IF;
 dest:=veo_telegram_destination((result->>'team_id')::uuid,(result->>'page_id')::uuid,(result->>'seller_id')::uuid);
 IF dest->>'chat_id' IS NULL THEN RETURN NULL;END IF;
 RETURN result||jsonb_build_object('telegram_chat_id',(dest->>'chat_id')::bigint,'telegram_thread_id',dest->'thread_id');
END $$;
DO $$ DECLARE tab text;fn record;BEGIN
 FOREACH tab IN ARRAY ARRAY['veo_telegram_groups','veo_team_telegram_groups','veo_team_telegram_pages','veo_telegram_memberships','veo_telegram_group_states'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,anon,authenticated',tab);EXECUTE format('GRANT ALL ON %I TO service_role',tab);
 END LOOP;
 FOR fn IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('veo_staff_can_telegram_group','veo_sync_telegram_groups','veo_telegram_groups_page','veo_telegram_group_action','veo_telegram_destination','veo_handoff') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',fn.signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',fn.signature);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611080003_veo_telegram_groups.sql','a6b62e091573500573d7188a9a2409b62459d145864feb2cddfd05bdb8b7a71d');

-- FILE: 202611080004_veo_telegram_group_observations.sql SHA256: 6c1a78085712d47e757ea8e140915da9447e8fc24281583eebfed5c6a1e9364b

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;
ALTER FUNCTION veo_map_staff_telegram(uuid,uuid,bigint,bigint) RENAME TO veo_map_staff_telegram_before_groups;
CREATE FUNCTION veo_map_staff_telegram(p_actor uuid,p_user uuid,p_telegram bigint,p_chat bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;tenant uuid;BEGIN
 SELECT tenant_id INTO tenant FROM veo_accounts WHERE user_id=p_actor AND active AND role='owner';
 IF tenant IS NULL THEN RAISE EXCEPTION 'Owner access required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-telegram-groups:'||tenant::text,0));
 IF EXISTS(SELECT 1 FROM veo_worker_mappings m JOIN veo_accounts a USING(user_id) WHERE a.tenant_id=tenant AND a.active AND m.telegram_user_id=p_telegram AND m.user_id<>p_user) THEN RAISE EXCEPTION 'Telegram identity already belongs to another active account' USING ERRCODE='23505';END IF;
 IF EXISTS(SELECT 1 FROM veo_telegram_memberships WHERE user_id=p_user AND telegram_user_id<>p_telegram) THEN RAISE EXCEPTION 'Remove existing group memberships before changing Telegram identity';END IF;
 result:=veo_map_staff_telegram_before_groups(p_actor,p_user,p_telegram,p_chat);
 IF veo_staff_can_telegram_group(p_user,p_chat) THEN
  INSERT INTO veo_telegram_memberships VALUES(p_user,tenant,p_chat,p_telegram,clock_timestamp(),p_actor) ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=p_telegram,verified_at=clock_timestamp(),verified_by=p_actor;
 END IF;
 RETURN result;
END $$;
ALTER FUNCTION veo_action(uuid,text,jsonb) RENAME TO veo_action_before_group_controls;
CREATE FUNCTION veo_action(p_actor uuid,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF p_action='mapping' AND EXISTS(SELECT 1 FROM veo_teams WHERE id=nullif(p_data->>'team_id','')::uuid AND telegram_groups_managed) THEN RAISE EXCEPTION 'Use Telegram Groups and Pages to edit a team with multiple destinations';END IF;
 RETURN veo_action_before_group_controls(p_actor,p_action,p_data);
END $$;
ALTER FUNCTION veo_current_telegram_group(uuid) RENAME TO veo_current_telegram_group_before_groups;
CREATE FUNCTION veo_current_telegram_group(p_user uuid) RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE chat bigint;BEGIN
 SELECT m.chat_id INTO chat FROM veo_telegram_memberships m LEFT JOIN veo_staff_telegram_groups s ON s.user_id=m.user_id
 WHERE m.user_id=p_user AND veo_staff_can_telegram_group(p_user,m.chat_id)
 ORDER BY (m.chat_id=s.telegram_chat_id) DESC NULLS LAST,m.verified_at,m.chat_id LIMIT 1;
 IF FOUND THEN RETURN chat;END IF;
 IF EXISTS(SELECT 1 FROM veo_accounts a JOIN veo_teams t ON t.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END WHERE a.user_id=p_user AND t.telegram_groups_managed) THEN RETURN NULL;END IF;
 RETURN veo_current_telegram_group_before_groups(p_user);
END $$;
ALTER FUNCTION veo_apply_telegram_observations(uuid,jsonb) RENAME TO veo_apply_telegram_observations_before_groups;
CREATE FUNCTION veo_apply_telegram_observations(p_tenant uuid,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE person jsonb;a veo_accounts;owner uuid;chat bigint;seen timestamptz;prior jsonb;info jsonb;answer jsonb;poll jsonb;current_state jsonb;legacy jsonb;
 checked integer:=0;imported integer:=0;removed integer:=0;all_count integer;left_count integer;state_seen timestamptz;primary_chat bigint;BEGIN
 SELECT owner_id INTO owner FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL;
 IF owner IS NULL OR p_payload->>'tenant_id' IS DISTINCT FROM p_tenant::text OR jsonb_typeof(p_payload->'workers') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'workers')>5000 THEN RAISE EXCEPTION 'Invalid connected workforce';END IF;
 FOR person IN SELECT value FROM jsonb_array_elements(p_payload->'workers') LOOP
  SELECT * INTO a FROM veo_accounts WHERE user_id=(person->>'user_id')::uuid AND tenant_id=p_tenant AND active AND role<>'owner' FOR UPDATE;
  IF NOT FOUND THEN CONTINUE;END IF;
  IF NOT EXISTS(SELECT 1 FROM veo_telegram_memberships WHERE user_id=a.user_id) THEN
   legacy:=veo_apply_telegram_observations_before_groups(p_tenant,jsonb_build_object('tenant_id',p_tenant,'workers',jsonb_build_array(person)));
   checked:=checked+coalesce((legacy->>'checked')::int,0);imported:=imported+coalesce((legacy->>'attendance_imported')::int,0);removed:=removed+coalesce((legacy->>'departures')::int,0);CONTINUE;
  END IF;
  chat:=(person->>'chat_id')::bigint;seen:=(person->>'observed_at')::timestamptz;
  IF seen IS NULL OR seen<now()-interval '10 minutes' OR seen>now()+interval '1 minute' OR length(person::text)>12000 OR NOT veo_staff_can_telegram_group(a.user_id,chat)
   OR NOT EXISTS(SELECT 1 FROM veo_telegram_memberships m JOIN veo_worker_mappings w USING(user_id) WHERE m.user_id=a.user_id AND m.chat_id=chat AND m.telegram_user_id=(person->>'telegram_user_id')::bigint AND m.telegram_user_id=w.telegram_user_id AND m.verified_at<=seen) THEN CONTINUE;END IF;
  SELECT payload INTO prior FROM veo_telegram_group_states WHERE user_id=a.user_id AND chat_id=chat;
  IF EXISTS(SELECT 1 FROM veo_telegram_group_states WHERE user_id=a.user_id AND chat_id=chat AND observed_at>=seen) THEN CONTINUE;END IF;
  SELECT jsonb_object_agg(key,value) INTO info FROM jsonb_each(jsonb_build_object('membership',person->'membership','membership_confirmed',person->'membership_confirmed','is_bot',person->'is_bot','attendance',person->'attendance','availability',person->'availability','page_access',person->'page_access','error',person->'error')) WHERE value<>'null'::jsonb;
  -- Preserve a previously verified declaration on incomplete reads; only an
  -- explicit newer withdrawal or a known replacement poll can clear it.
  IF prior->'attendance' IS NOT NULL AND((info->'attendance' IS NULL AND(info->'availability' IS NULL OR info->'availability'->>'poll_id' IS NOT DISTINCT FROM prior->'availability'->>'poll_id'))
   OR(info->'attendance'->>'updated_at')::timestamptz<=(prior->'attendance'->>'updated_at')::timestamptz) THEN info:=info||jsonb_build_object('attendance',prior->'attendance');END IF;
  INSERT INTO veo_telegram_group_states VALUES(a.user_id,chat,(person->>'telegram_user_id')::bigint,info,seen)
  ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=EXCLUDED.telegram_user_id,payload=EXCLUDED.payload,observed_at=EXCLUDED.observed_at;
  checked:=checked+1;
  SELECT count(*),count(*) FILTER(WHERE s.observed_at>=now()-interval '10 minutes' AND s.observed_at>=m.verified_at AND s.payload->>'membership' IN('left','kicked') AND s.payload->'membership_confirmed'='true'::jsonb AND s.payload->'is_bot'='false'::jsonb)
   INTO all_count,left_count FROM veo_telegram_memberships m LEFT JOIN veo_telegram_group_states s USING(user_id,chat_id)
   WHERE m.user_id=a.user_id AND veo_staff_can_telegram_group(a.user_id,m.chat_id);
  IF all_count>0 AND all_count=left_count THEN PERFORM veo_offboard(owner,a.user_id,'Jaucian confirmed departure from every current linked Telegram group','telegram_confirmed_departure');removed:=removed+1;CONTINUE;END IF;
  primary_chat:=veo_current_telegram_group(a.user_id);
  SELECT s.payload,s.observed_at INTO current_state,state_seen FROM veo_telegram_group_states s WHERE s.user_id=a.user_id AND veo_staff_can_telegram_group(a.user_id,s.chat_id)
   ORDER BY (s.payload->>'membership' IN('member','administrator','creator','restricted_member') AND s.payload->'membership_confirmed'='true'::jsonb AND s.payload->'is_bot'='false'::jsonb) DESC NULLS LAST,s.observed_at DESC LIMIT 1;
  SELECT s.payload->'attendance' INTO answer FROM veo_telegram_group_states s WHERE s.user_id=a.user_id AND veo_staff_can_telegram_group(a.user_id,s.chat_id)
   AND s.payload->>'membership' NOT IN('left','kicked') AND s.payload->'attendance'->>'work_date'=(veo_today()+1)::text AND jsonb_typeof(s.payload->'attendance'->'active')='boolean'
   AND(s.payload->'attendance'->>'updated_at')::timestamptz BETWEEN(SELECT launch_at FROM veo_tenants WHERE id=p_tenant) AND now()+interval '1 minute'
   ORDER BY(s.payload->'attendance'->>'updated_at')::timestamptz DESC,s.chat_id LIMIT 1;
  SELECT s.payload->'availability' INTO poll FROM veo_telegram_group_states s WHERE s.user_id=a.user_id AND veo_staff_can_telegram_group(a.user_id,s.chat_id)
   AND s.payload->'availability'->>'work_date'=(veo_today()+1)::text ORDER BY s.observed_at DESC LIMIT 1;
  IF answer IS NOT NULL AND poll IS NOT NULL THEN poll:=poll||jsonb_build_object('has_vote',true);END IF;
  INSERT INTO veo_telegram_staff_state(user_id,tenant_id,telegram_chat_id,telegram_user_id,membership,observed_at,attendance,availability,last_error)
  VALUES(a.user_id,p_tenant,primary_chat,(person->>'telegram_user_id')::bigint,coalesce(current_state->>'membership','unknown'),state_seen,answer,poll,current_state->>'error')
  ON CONFLICT(user_id) DO UPDATE SET telegram_chat_id=EXCLUDED.telegram_chat_id,telegram_user_id=EXCLUDED.telegram_user_id,membership=EXCLUDED.membership,observed_at=EXCLUDED.observed_at,attendance=EXCLUDED.attendance,availability=EXCLUDED.availability,last_error=EXCLUDED.last_error;
  IF a.role IN('member','manager') THEN
   SELECT to_jsonb(x) INTO prior FROM veo_attendance x WHERE x.user_id=a.user_id AND work_date=veo_today()+1;
   IF answer IS NOT NULL AND(prior IS NULL OR prior->>'source'<>'telegram' OR prior->'active' IS DISTINCT FROM answer->'active') THEN
    INSERT INTO veo_attendance(user_id,work_date,active,updated_by,updated_at,source) VALUES(a.user_id,veo_today()+1,(answer->>'active')::boolean,owner,seen,'telegram')
    ON CONFLICT(user_id,work_date) DO UPDATE SET active=EXCLUDED.active,updated_by=owner,updated_at=seen,source='telegram';
    INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,before_value,after_value,reason) VALUES(p_tenant,owner,'telegram_attendance',a.user_id,prior,answer,'Latest current declaration across linked Telegram groups');imported:=imported+1;
   ELSIF answer IS NULL AND prior->>'source'='telegram' AND EXISTS(SELECT 1 FROM veo_telegram_group_states s WHERE s.user_id=a.user_id AND veo_staff_can_telegram_group(a.user_id,s.chat_id) AND s.payload->'attendance'->>'work_date'=(veo_today()+1)::text AND s.payload->'attendance'->'active'='null'::jsonb) THEN
    DELETE FROM veo_attendance WHERE user_id=a.user_id AND work_date=veo_today()+1;imported:=imported+1;
    INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,before_value,after_value,reason) VALUES(p_tenant,owner,'telegram_attendance',a.user_id,prior,'null','Current linked-group votes withdrawn');
   END IF;
  END IF;
 END LOOP;
 UPDATE veo_telegram_sync_state SET last_sync_at=clock_timestamp(),cursor=greatest(0,coalesce((p_payload->>'next_offset')::int,0)),next_sync_at=now()+CASE WHEN coalesce((p_payload->>'next_offset')::int,0)>0 THEN interval '1 minute' ELSE interval '5 minutes' END,
  lease_until=NULL,last_error=NULL,counts=jsonb_build_object('checked',checked,'attendance_imported',imported,'departures',removed,'unmapped',coalesce((p_payload->>'unmapped')::int,0)) WHERE tenant_id=p_tenant;
 RETURN jsonb_build_object('checked',checked,'attendance_imported',imported,'departures',removed);
END $$;

ALTER FUNCTION veo_receipt_requirements(uuid,uuid,uuid,text,uuid,boolean) RENAME TO veo_receipt_requirements_before_groups;
CREATE FUNCTION veo_receipt_requirements(p_actor uuid,p_contact uuid,p_seller uuid,p_kind text,p_order uuid DEFAULT NULL,p_fresh boolean DEFAULT true) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE result jsonb;team uuid;pg uuid;BEGIN
 result:=veo_receipt_requirements_before_groups(p_actor,p_contact,p_seller,p_kind,p_order,p_fresh);
 SELECT c.page_id INTO pg FROM contacts c WHERE c.id=p_contact;
 SELECT t.id INTO team FROM veo_teams t JOIN veo_accounts a ON t.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END WHERE a.user_id=p_seller AND t.tenant_id=a.tenant_id;
 IF EXISTS(SELECT 1 FROM veo_teams WHERE id=team AND telegram_groups_managed) AND veo_telegram_destination(team,pg,p_seller)->>'chat_id' IS NULL THEN
  RETURN result||jsonb_build_object('allowed',false,'blockers',coalesce(result->'blockers','[]')||'"telegram_page_or_membership_required"'::jsonb);
 END IF;
 RETURN result;
END $$;
ALTER FUNCTION veo_receipt_facts(uuid) RENAME TO veo_receipt_facts_before_groups;
CREATE FUNCTION veo_receipt_facts(p_receipt uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;r veo_receipts;team uuid;dest jsonb;BEGIN
 result:=veo_receipt_facts_before_groups(p_receipt);SELECT * INTO r FROM veo_receipts WHERE id=p_receipt;
 SELECT coalesce((SELECT team_id FROM veo_closed_deals WHERE id=r.closed_deal_id),(SELECT team_id FROM veo_orders WHERE id=r.order_id)) INTO team;
 IF EXISTS(SELECT 1 FROM veo_teams WHERE id=team AND telegram_groups_managed) THEN
  dest:=veo_telegram_destination(team,r.page_id,r.seller_id);
  IF dest->>'chat_id' IS NULL AND NOT (coalesce(result->'holds','[]') ? 'telegram_page_or_membership_required') THEN RETURN result||jsonb_build_object('holds',coalesce(result->'holds','[]')||'"telegram_page_or_membership_required"'::jsonb);END IF;
 END IF;
 RETURN result;
END $$;
DO $warnings$ DECLARE definition text;anchor text:='EXISTS(SELECT 1 FROM veo_worker_mappings WHERE user_id=a.user_id) AS mapped';BEGIN
 definition:=pg_get_functiondef('veo_workflow_warnings(uuid,uuid)'::regprocedure);
 IF strpos(definition,anchor)=0 THEN RAISE EXCEPTION 'Expected Telegram warning mapping guard';END IF;
 EXECUTE replace(definition,anchor,'(EXISTS(SELECT 1 FROM veo_worker_mappings WHERE user_id=a.user_id) AND veo_current_telegram_group(a.user_id) IS NOT NULL) AS mapped');
END $warnings$;
DO $$ DECLARE fn record;BEGIN
 FOR fn IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('veo_current_telegram_group','veo_apply_telegram_observations','veo_receipt_facts','veo_receipt_requirements','veo_action','veo_map_staff_telegram') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',fn.signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',fn.signature);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611080004_veo_telegram_group_observations.sql','6c1a78085712d47e757ea8e140915da9447e8fc24281583eebfed5c6a1e9364b');

-- FILE: 202611080005_veo_telegram_group_reports.sql SHA256: 3cf1d1ac98d96bba8df43fa8a2fce838a7f8a2ff2042b055bff5b41fcf640364

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;
ALTER FUNCTION veo_operations_report(uuid,date) RENAME TO veo_operations_report_before_groups;
CREATE FUNCTION veo_operations_report(p_tenant uuid,p_day date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp SET jit=off SET plan_cache_mode=force_custom_plan AS $$
DECLARE result jsonb;t jsonb;l record;ids uuid[];workers jsonb;quotas jsonb;cap jsonb;closed integer;done integer;target integer;output jsonb:='[]';BEGIN
 result:=veo_operations_report_before_groups(p_tenant,p_day);
 FOR t IN SELECT value FROM jsonb_array_elements(result->'teams') LOOP
  IF NOT EXISTS(SELECT 1 FROM veo_teams WHERE id=(t->>'id')::uuid AND telegram_groups_managed) THEN output:=output||jsonb_build_array(t);CONTINUE;END IF;
  FOR l IN SELECT x.* FROM veo_team_telegram_groups x JOIN veo_telegram_groups g ON g.tenant_id=x.tenant_id AND g.chat_id=x.chat_id AND g.active WHERE x.team_id=(t->>'id')::uuid LOOP
   SELECT coalesce(array_agg(r.page_id ORDER BY r.page_id),'{}') INTO ids FROM veo_team_telegram_pages r JOIN veo_teams tm ON tm.id=r.team_id
    WHERE r.team_id=l.team_id AND r.chat_id=l.chat_id AND veo_can_page(tm.manager_id,r.page_id);
   IF cardinality(ids)=0 THEN CONTINUE;END IF;
   SELECT coalesce(jsonb_agg(w.value||jsonb_build_object(
    'pages',coalesce((SELECT jsonb_agg(p.value) FROM jsonb_array_elements(w.value->'pages') p WHERE(p.value->>'id')::uuid=ANY(ids)),'[]'),
    'clients',coalesce((SELECT jsonb_agg(c.value) FROM jsonb_array_elements(w.value->'clients') c WHERE(c.value->>'page_id')::uuid=ANY(ids)),'[]'),
    'warnings',coalesce((SELECT jsonb_agg(e.value) FROM jsonb_array_elements(w.value->'warnings') e WHERE e.value->>'page_id' IS NULL OR(e.value->>'page_id')::uuid=ANY(ids)),'[]'),
    'receipt_holds',coalesce((SELECT jsonb_agg(h.value) FROM jsonb_array_elements(w.value->'receipt_holds') h JOIN veo_receipts r ON r.id=(h.value->>'id')::uuid WHERE r.page_id=ANY(ids)),'[]'),
    'group_results',(SELECT jsonb_build_object('closed',count(*) FILTER(WHERE f.closed_date=p_day),'done',count(*) FILTER(WHERE f.done_date=p_day)) FROM veo_sales_facts f WHERE f.tenant_id=p_tenant AND f.team_id=l.team_id AND f.seller_id=(w.value->>'id')::uuid AND f.page_id=ANY(ids) AND veo_can_page(f.seller_id,f.page_id))) ORDER BY w.value->>'name'),'[]') INTO workers
    FROM jsonb_array_elements(t->'workers') w WHERE EXISTS(SELECT 1 FROM unnest(ids) p WHERE veo_can_page((w.value->>'id')::uuid,p));
   SELECT coalesce(jsonb_agg(p.value),'[]'),coalesce(sum((p.value->>'quota')::integer),0) INTO quotas,target FROM jsonb_array_elements(t->'page_quotas') p WHERE(p.value->>'page_id')::uuid=ANY(ids);
   SELECT count(*) FILTER(WHERE closed_date=p_day),count(*) FILTER(WHERE done_date=p_day) INTO closed,done FROM veo_sales_facts WHERE tenant_id=p_tenant AND team_id=l.team_id AND page_id=ANY(ids);
   cap:=coalesce(t->'capacity','{}')||jsonb_build_object('closed',closed,'done',done,'quota',jsonb_build_object('closed',target,'done',target));
   output:=output||jsonb_build_array(t||jsonb_build_object('chat_id',l.chat_id,'thread_id',l.thread_id,'group_report',true,'group_page_ids',to_jsonb(ids),'delivery_key',l.team_id::text||':'||l.chat_id::text,
    'workers',workers,'page_quotas',quotas,'capacity',cap,'access_signature',md5(coalesce(t->>'access_signature','')||l.chat_id::text||coalesce(l.thread_id::text,'')||ids::text||coalesce((SELECT jsonb_agg(jsonb_build_array(user_id,telegram_user_id,verified_at) ORDER BY user_id)::text FROM veo_telegram_memberships WHERE chat_id=l.chat_id AND tenant_id=p_tenant),'[]'))));
  END LOOP;
 END LOOP;
 RETURN result||jsonb_build_object('teams',output,'telegram_groups_version',3,'group_report_policy','Group results and clients use routed Pages; personal commission qualification and attendance remain unique per worker across all Pages.');
END $$;
REVOKE ALL ON FUNCTION veo_operations_report(uuid,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_operations_report(uuid,date) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611080005_veo_telegram_group_reports.sql','3cf1d1ac98d96bba8df43fa8a2fce838a7f8a2ff2042b055bff5b41fcf640364');

-- FILE: 202611080006_veo_telegram_intake.sql SHA256: acac6ff0d5138560e884f01bf64e995656bb14eca1f3fd300c97db5e6a9f9b81

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;
CREATE TABLE veo_telegram_intake_requests(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES veo_tenants(id),actor_id uuid NOT NULL REFERENCES veo_accounts(user_id),chat_id bigint NOT NULL,
 kind text NOT NULL,context jsonb NOT NULL DEFAULT '{}',offer_id uuid,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',UNIQUE(offer_id,chat_id)
);
CREATE TABLE veo_telegram_intake_tokens(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES veo_telegram_intake_requests(id) ON DELETE CASCADE,
 action text NOT NULL,contact_id uuid,offer_id uuid,target_id uuid,expires_at timestamptz NOT NULL,
 result_request_id uuid REFERENCES veo_telegram_intake_requests(id) ON DELETE SET NULL,
 UNIQUE NULLS NOT DISTINCT(request_id,action,contact_id,offer_id,target_id)
);
CREATE INDEX veo_telegram_intake_request_expiry ON veo_telegram_intake_requests(expires_at);

CREATE FUNCTION veo_telegram_intake_context(p_tenant uuid,p_telegram bigint,p_chat bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE actor uuid;n integer;a veo_accounts;ids uuid[];thread bigint;BEGIN
 SELECT count(*),(array_agg(w.user_id))[1] INTO n,actor FROM veo_accounts w JOIN veo_worker_mappings m USING(user_id) JOIN users u ON u.id=w.user_id AND u.is_active
 WHERE w.tenant_id=p_tenant AND w.active AND m.telegram_user_id=p_telegram AND(
  EXISTS(SELECT 1 FROM veo_telegram_memberships g WHERE g.user_id=w.user_id AND g.chat_id=p_chat AND g.telegram_user_id=p_telegram AND veo_staff_can_telegram_group(w.user_id,p_chat))
  OR(NOT EXISTS(SELECT 1 FROM veo_telegram_memberships WHERE user_id=w.user_id) AND veo_current_telegram_group(w.user_id)=p_chat AND EXISTS(SELECT 1 FROM veo_staff_telegram_groups WHERE user_id=w.user_id AND telegram_chat_id=p_chat)));
 IF n<>1 THEN RAISE EXCEPTION 'Ask the Head to verify your Telegram account, linked team group and Page access in Tokko' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM veo_accounts WHERE user_id=actor;
 SELECT coalesce(array_agg(p.id ORDER BY p.id),'{}') INTO ids FROM pages p WHERE veo_can_page(actor,p.id) AND EXISTS(
  SELECT 1 FROM veo_teams t WHERE t.tenant_id=p_tenant AND veo_can_page(t.manager_id,p.id)
  AND(a.role='owner' OR(a.role='team_leader' AND t.manager_id IN(SELECT veo_descendants(actor))) OR t.manager_id=CASE WHEN a.role='manager' THEN actor ELSE a.parent_id END)
  AND((NOT t.telegram_groups_managed AND t.telegram_chat_id=p_chat) OR EXISTS(SELECT 1 FROM veo_team_telegram_pages r WHERE r.team_id=t.id AND r.chat_id=p_chat AND r.page_id=p.id)));
 IF cardinality(ids)=0 THEN RAISE EXCEPTION 'No currently permitted Pages are routed to this group' USING ERRCODE='42501';END IF;
 SELECT l.thread_id INTO thread FROM veo_team_telegram_groups l JOIN veo_teams t ON t.id=l.team_id WHERE l.tenant_id=p_tenant AND l.chat_id=p_chat
  AND(a.role IN('owner','team_leader') AND t.manager_id IN(SELECT veo_descendants(actor)) OR t.manager_id=CASE WHEN a.role='manager' THEN actor ELSE a.parent_id END) ORDER BY t.id LIMIT 1;
 RETURN jsonb_build_object('actor_id',actor,'role',a.role,'page_ids',to_jsonb(ids),'thread_id',thread);
END $$;

CREATE FUNCTION veo_telegram_intake_token(p_request uuid,p_action text,p_contact uuid DEFAULT NULL,p_offer uuid DEFAULT NULL,p_target uuid DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE token uuid;until_at timestamptz;BEGIN
 SELECT expires_at INTO until_at FROM veo_telegram_intake_requests WHERE id=p_request AND expires_at>now();IF NOT FOUND THEN RAISE EXCEPTION 'Assignment menu expired; use /clients again';END IF;
 INSERT INTO veo_telegram_intake_tokens(request_id,action,contact_id,offer_id,target_id,expires_at) VALUES(p_request,p_action,p_contact,p_offer,p_target,until_at)
 ON CONFLICT(request_id,action,contact_id,offer_id,target_id) DO UPDATE SET expires_at=EXCLUDED.expires_at RETURNING id INTO token;
 RETURN 'vi:'||token::text;
END $$;

CREATE FUNCTION veo_telegram_intake_pending(p_tenant uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(o)),'[]') FROM(
 SELECT x.id offer_id,a.user_id,wm.telegram_user_id,(dest->>'chat_id')::bigint chat_id FROM veo_client_offers x JOIN veo_accounts a ON a.user_id=x.offered_to AND a.active
 JOIN veo_teams t ON t.tenant_id=a.tenant_id AND t.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END
 JOIN veo_worker_mappings wm ON wm.user_id=a.user_id LEFT JOIN veo_client_claims cc ON cc.contact_id=x.contact_id
 CROSS JOIN LATERAL(SELECT veo_telegram_destination(t.id,x.page_id,a.user_id) dest) d
 WHERE x.tenant_id=p_tenant AND x.status='pending' AND x.expires_at>now() AND dest->>'chat_id' IS NOT NULL
 AND cc.user_id IS NOT DISTINCT FROM x.previous_owner AND veo_intake_can_offer(x.offered_by,x.contact_id,a.user_id)
 ORDER BY x.created_at,x.id LIMIT 50) o
$$;

CREATE FUNCTION veo_telegram_intake(p_tenant uuid,p_telegram bigint,p_chat bigint,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp SET jit=off SET plan_cache_mode=force_custom_plan AS $$
DECLARE scope jsonb;actor uuid;req uuid;kind text;context jsonb:='{}';token veo_telegram_intake_tokens;r veo_telegram_intake_requests;offer veo_client_offers;
 ids uuid[];pg uuid;part jsonb;items jsonb:='[]';c jsonb;w jsonb;lines text;buttons jsonb:='[]';row_buttons jsonb;ready boolean;dest jsonb;target_team uuid;result jsonb;BEGIN
 scope:=veo_telegram_intake_context(p_tenant,p_telegram,p_chat);actor:=(scope->>'actor_id')::uuid;
 SELECT array_agg(value::uuid) INTO ids FROM jsonb_array_elements_text(scope->'page_ids');
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-intake:'||p_tenant::text,0));
 IF p_action='render_offer' THEN
  SELECT * INTO offer FROM veo_client_offers WHERE id=(p_data->>'offer_id')::uuid AND tenant_id=p_tenant AND offered_to=actor;
  IF offer.id IS NULL OR offer.status<>'pending' OR offer.expires_at<=now() OR NOT(offer.page_id=ANY(ids)) OR NOT veo_intake_can_offer(offer.offered_by,offer.contact_id,actor)
   OR NOT EXISTS(SELECT 1 FROM veo_client_claims WHERE contact_id=offer.contact_id AND user_id IS NOT DISTINCT FROM offer.previous_owner) AND offer.previous_owner IS NOT NULL
  THEN RAISE EXCEPTION 'The offer expired, ended or its access changed' USING ERRCODE='42501';END IF;
  IF (SELECT user_id FROM veo_client_claims WHERE contact_id=offer.contact_id) IS DISTINCT FROM offer.previous_owner THEN RAISE EXCEPTION 'Client ownership changed' USING ERRCODE='42501';END IF;
  INSERT INTO veo_telegram_intake_requests(id,tenant_id,actor_id,chat_id,kind,context,offer_id,expires_at) VALUES(gen_random_uuid(),p_tenant,actor,p_chat,'offers',jsonb_build_object('contact_id',offer.contact_id),offer.id,offer.expires_at)
   ON CONFLICT(offer_id,chat_id) DO UPDATE SET expires_at=EXCLUDED.expires_at RETURNING id INTO req;
 ELSIF p_action='render' THEN req:=(p_data->>'request_id')::uuid;
 ELSE
  req:=(p_data->>'request_id')::uuid;IF req IS NULL THEN RAISE EXCEPTION 'A stable Telegram update ID is required';END IF;
  SELECT * INTO r FROM veo_telegram_intake_requests WHERE id=req;
  IF r.id IS NOT NULL THEN
   IF(r.tenant_id,r.actor_id,r.chat_id) IS DISTINCT FROM(p_tenant,actor,p_chat) THEN RAISE EXCEPTION 'Request belongs to another account' USING ERRCODE='42501';END IF;
   RETURN jsonb_build_object('request_id',req,'chat_id',p_chat,'telegram_user_id',p_telegram);
  END IF;
  kind:=p_action;
  IF p_action='callback' THEN
   SELECT t.* INTO token FROM veo_telegram_intake_tokens t JOIN veo_telegram_intake_requests x ON x.id=t.request_id WHERE t.id=(p_data->>'token_id')::uuid AND x.actor_id=actor AND x.chat_id=p_chat AND x.tenant_id=p_tenant AND t.expires_at>now() FOR UPDATE OF t;
   IF token.id IS NULL THEN RAISE EXCEPTION 'This button belongs to another person or has expired; use /clients for a fresh menu' USING ERRCODE='42501';END IF;
   IF token.result_request_id IS NOT NULL THEN RETURN jsonb_build_object('request_id',token.result_request_id,'chat_id',p_chat,'telegram_user_id',p_telegram);END IF;
   IF token.contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=token.contact_id AND page_id=ANY(ids)) THEN RAISE EXCEPTION 'Client Page access changed' USING ERRCODE='42501';END IF;
   kind:=token.action;context:=jsonb_strip_nulls(jsonb_build_object('contact_id',token.contact_id));
  END IF;
  IF kind IN('ready','busy') THEN
   PERFORM veo_intake_action(actor,'readiness',jsonb_build_object('request_id',req,'status',kind,'source','telegram'));kind:='status';
  ELSIF kind IN('accept','decline','cancel','offer') THEN
   IF token.id IS NULL THEN RAISE EXCEPTION 'Use the current assignment buttons';END IF;
   PERFORM veo_intake_action(actor,kind,jsonb_build_object('request_id',req,'contact_id',token.contact_id,'offer_id',token.offer_id,'user_id',token.target_id,'reason','Telegram handover requested by the current supervisor or client owner','source','telegram'));
   IF kind='accept' THEN kind:='assigned';ELSE context:=context||jsonb_build_object('notice',CASE WHEN kind='offer' THEN 'Client offer recorded. Assignments change only when the worker accepts; sales keep their original seller.' ELSE 'Offer updated.' END);kind:='notice';END IF;
  ELSIF kind NOT IN('pool','offers','assigned','reassign','choose_worker') THEN RAISE EXCEPTION 'Unknown Telegram assignment command';END IF;
  INSERT INTO veo_telegram_intake_requests(id,tenant_id,actor_id,chat_id,kind,context) VALUES(req,p_tenant,actor,p_chat,kind,context);
  INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value,reason) VALUES(p_tenant,actor,'telegram_intake',coalesce(token.contact_id,actor),jsonb_build_object('request_id',req,'chat_id',p_chat,'command',coalesce(token.action,p_action)),'Existing Jaucian bot; current account, group and Page authorization checked');
  IF token.id IS NOT NULL THEN UPDATE veo_telegram_intake_tokens SET result_request_id=req WHERE id=token.id;END IF;
  RETURN jsonb_build_object('request_id',req,'chat_id',p_chat,'telegram_user_id',p_telegram);
 END IF;
 SELECT * INTO r FROM veo_telegram_intake_requests WHERE id=req AND tenant_id=p_tenant AND actor_id=actor AND chat_id=p_chat AND expires_at>now();
 IF r.id IS NULL THEN RAISE EXCEPTION 'Assignment menu expired or its access changed' USING ERRCODE='42501';END IF;
 IF r.context->>'contact_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=(r.context->>'contact_id')::uuid AND page_id=ANY(ids)) THEN RAISE EXCEPTION 'Client Page access changed' USING ERRCODE='42501';END IF;
 ready:=EXISTS(SELECT 1 FROM veo_intake_readiness WHERE user_id=actor AND status='ready' AND expires_at>now());
 lines:='Tokko / VEO · '||(SELECT left(coalesce(name,'Worker'),80) FROM users WHERE id=actor)||E'\nStatus: '||CASE WHEN ready THEN 'Ready until '||(SELECT to_char(expires_at AT TIME ZONE 'Asia/Manila','HH24:MI') FROM veo_intake_readiness WHERE user_id=actor)||' PHT' ELSE 'Busy / Ready expired' END||E'\nReady/Busy is shared with Tokko. Tomorrow attendance still uses Jaucian’s poll.';
 IF r.kind='notice' THEN lines:=lines||E'\n'||(r.context->>'notice');
 ELSIF r.kind='choose_worker' THEN
  SELECT to_jsonb(x) INTO c FROM contacts x WHERE x.id=(r.context->>'contact_id')::uuid AND x.page_id=ANY(ids);
  part:=veo_intake_page(actor,'assigned',(c->>'page_id')::uuid,'',0);
  lines:=lines||E'\nOffer / reassign: '||coalesce(c->>'name','Unknown client')||E'\nChoose a Ready worker. The current owner keeps the client until acceptance.';
  FOR w IN SELECT value FROM jsonb_array_elements(part->'roster') WHERE value->'ready'='true'::jsonb LOOP
   IF NOT veo_intake_can_offer(actor,(c->>'id')::uuid,(w->>'id')::uuid) OR (w->>'id')::uuid=(SELECT user_id FROM veo_client_claims WHERE contact_id=(c->>'id')::uuid) THEN CONTINUE;END IF;
   SELECT id INTO target_team FROM veo_teams WHERE manager_id=(SELECT CASE WHEN role='manager' THEN user_id ELSE parent_id END FROM veo_accounts WHERE user_id=(w->>'id')::uuid);
   dest:=veo_telegram_destination(target_team,(c->>'page_id')::uuid,(w->>'id')::uuid);IF dest->>'chat_id' IS NULL THEN CONTINUE;END IF;
   buttons:=buttons||jsonb_build_array(jsonb_build_array(jsonb_build_object('text','Offer to '||left(coalesce(w->>'name','Worker'),45),'callback_data',veo_telegram_intake_token(req,'offer',(c->>'id')::uuid,NULL,(w->>'id')::uuid))));
   IF jsonb_array_length(buttons)>=10 THEN EXIT;END IF;
  END LOOP;
  IF jsonb_array_length(buttons)=0 THEN lines:=lines||E'\nNo Ready, verified workers are currently eligible. Ask a supervisor or use Tokko.';END IF;
 ELSIF r.kind<>'status' THEN
  FOREACH pg IN ARRAY ids LOOP
   part:=veo_intake_page(actor,CASE WHEN r.kind='reassign' THEN 'assigned' ELSE r.kind END,pg,coalesce(r.context->>'contact_id',''),0);items:=items||(part->'items');
  END LOOP;
  lines:=lines||E'\n'||CASE r.kind WHEN 'pool' THEN 'Available clients (up to 10)' WHEN 'offers' THEN 'Current offers' WHEN 'reassign' THEN 'Choose an assigned client to hand over' ELSE 'Accepted clients' END;
  FOR c IN SELECT value FROM jsonb_array_elements(items) ORDER BY value->>'last_interaction_at' DESC,value->>'id' LIMIT 10 LOOP
   lines:=lines||E'\n• '||left(coalesce(c->>'name','Unknown client'),70)||' / '||left(coalesce(c->>'page_name','Unknown Page'),60)||' · '||coalesce(c->>'pipeline_stage','Unknown stage');row_buttons:='[]';
   IF r.kind='pool' AND scope->>'role' IN('member','manager') OR c->>'offered_to'=actor::text AND c->'offer_authorized'='true'::jsonb THEN
    row_buttons:=row_buttons||jsonb_build_array(jsonb_build_object('text','Accept · '||left(coalesce(c->>'name','Client'),35),'callback_data',veo_telegram_intake_token(req,'accept',(c->>'id')::uuid,nullif(c->>'offer_id','')::uuid,NULL)));
   END IF;
   IF c->'can_offer'='true'::jsonb THEN row_buttons:=row_buttons||jsonb_build_array(jsonb_build_object('text','Offer / reassign','callback_data',veo_telegram_intake_token(req,'choose_worker',(c->>'id')::uuid,NULL,NULL)));END IF;
   IF c->>'offered_to'=actor::text THEN row_buttons:=row_buttons||jsonb_build_array(jsonb_build_object('text','Decline','callback_data',veo_telegram_intake_token(req,'decline',(c->>'id')::uuid,(c->>'offer_id')::uuid,NULL)));END IF;
   IF jsonb_array_length(row_buttons)>0 THEN buttons:=buttons||jsonb_build_array(row_buttons);END IF;
  END LOOP;
  IF jsonb_array_length(items)=0 THEN lines:=lines||E'\nNo matching clients. Use Tokko for full search and history.';END IF;
 END IF;
 IF scope->>'role' IN('member','manager') THEN buttons:=buttons||jsonb_build_array(jsonb_build_array(jsonb_build_object('text','Ready','callback_data',veo_telegram_intake_token(req,'ready')),jsonb_build_object('text','Busy','callback_data',veo_telegram_intake_token(req,'busy'))));END IF;
 buttons:=buttons||jsonb_build_array(jsonb_build_array(jsonb_build_object('text','New clients','callback_data',veo_telegram_intake_token(req,'pool')),jsonb_build_object('text','Offers','callback_data',veo_telegram_intake_token(req,'offers')),jsonb_build_object('text','My clients','callback_data',veo_telegram_intake_token(req,'assigned'))),jsonb_build_array(jsonb_build_object('text','Reassign','callback_data',veo_telegram_intake_token(req,'reassign')),jsonb_build_object('text','Open Tokko','url','https://veochatbot.vercel.app/dashboard/workspace?view=new_clients')));
 RETURN jsonb_build_object('request_id',req,'chat_id',p_chat,'telegram_user_id',p_telegram,'thread_id',scope->'thread_id','text',left(lines,3400),'reply_markup',jsonb_build_object('inline_keyboard',buttons));
END $$;
CREATE FUNCTION veo_telegram_intake_maintenance() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE removed integer;BEGIN
 WITH old AS(SELECT id FROM veo_telegram_intake_requests WHERE expires_at<now()-interval '1 day' ORDER BY expires_at LIMIT 500)
 DELETE FROM veo_telegram_intake_requests r USING old WHERE r.id=old.id;
 GET DIAGNOSTICS removed=ROW_COUNT;RETURN removed;
END $$;
DO $$ DECLARE tab text;fn record;BEGIN
 FOREACH tab IN ARRAY ARRAY['veo_telegram_intake_requests','veo_telegram_intake_tokens'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,anon,authenticated',tab);EXECUTE format('GRANT ALL ON %I TO service_role',tab);END LOOP;
 FOR fn IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('veo_telegram_intake_context','veo_telegram_intake_token','veo_telegram_intake_pending','veo_telegram_intake','veo_telegram_intake_maintenance') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',fn.signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',fn.signature);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611080006_veo_telegram_intake.sql','acac6ff0d5138560e884f01bf64e995656bb14eca1f3fd300c97db5e6a9f9b81');

-- FILE: 202611080007_veo_automatic_telegram_teams.sql SHA256: b69e986262bdfddb773883f51e379ec4c7aebdabfa4e47fe8d33de88889c62a3

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;

-- A team's existing manager_id is its supervising account. It may now be a
-- team leader, allowing direct members without inventing a manager account.
DO $$ DECLARE definition text; BEGIN
 definition:=pg_get_functiondef('veo_action_core(uuid,text,jsonb)'::regprocedure);
 IF position('(parent.role=''team_leader'' AND desired=''manager'')' IN definition)=0 THEN RAISE EXCEPTION 'Account hierarchy implementation changed';END IF;
 definition:=replace(definition,'(parent.role=''team_leader'' AND desired=''manager'')','(parent.role=''team_leader'' AND desired IN (''manager'',''member''))');
 definition:=replace(definition,'IF desired=''manager'' THEN INSERT INTO veo_teams','IF desired IN (''manager'',''team_leader'') THEN INSERT INTO veo_teams');
 definition:=replace(definition,'IF coalesce(cardinality(ids),0)=0 OR EXISTS','IF (coalesce(cardinality(ids),0)=0 AND desired<>''member'') OR EXISTS');
 EXECUTE definition;
END $$;
INSERT INTO veo_teams(tenant_id,manager_id,name)
 SELECT a.tenant_id,a.user_id,u.name||' (direct members)' FROM veo_accounts a JOIN users u ON u.id=a.user_id
 WHERE a.active AND a.role='team_leader' ON CONFLICT(manager_id) DO NOTHING;
-- Direct-member teams exclude their leader's child managers, who already have
-- their own teams. Keep capacity, reports and salary rosters disjoint.
DO $$ DECLARE fn record;definition text;BEGIN
 FOR fn IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'veo_%'
  AND prosrc LIKE '%a.parent_id=tm.manager_id%' LOOP
  definition:=pg_get_functiondef(fn.oid);
  definition:=replace(definition,'OR a.parent_id=tm.manager_id','OR (a.role=''member'' AND a.parent_id=tm.manager_id)');
  EXECUTE definition;
 END LOOP;
END $$;

ALTER TABLE veo_telegram_sync_state ADD COLUMN auto_cursor integer NOT NULL DEFAULT 0,
 ADD COLUMN auto_checked_at timestamptz,ADD COLUMN auto_last_error text;
CREATE TABLE veo_telegram_link_codes(
 user_id uuid PRIMARY KEY REFERENCES veo_accounts(user_id),code_hash text NOT NULL UNIQUE CHECK(length(code_hash)=64),
 expires_at timestamptz NOT NULL,consumed_by bigint,consumed_at timestamptz
);
CREATE TABLE veo_telegram_auto_grants(
 user_id uuid NOT NULL REFERENCES veo_accounts(user_id),page_id uuid NOT NULL REFERENCES pages(id),
 created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,page_id)
);
CREATE TABLE veo_telegram_auto_states(
 user_id uuid NOT NULL REFERENCES veo_accounts(user_id),chat_id bigint NOT NULL,telegram_user_id bigint NOT NULL,
 membership text NOT NULL,observed_at timestamptz NOT NULL,PRIMARY KEY(user_id,chat_id)
);

CREATE FUNCTION veo_create_telegram_link(p_actor uuid,p_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a veo_accounts;BEGIN
 SELECT * INTO a FROM veo_accounts WHERE user_id=p_actor AND active;
 IF a.user_id IS NULL THEN RAISE EXCEPTION 'Sign in required' USING ERRCODE='42501';END IF;
 IF p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid link code';END IF;
 INSERT INTO veo_telegram_link_codes(user_id,code_hash,expires_at) VALUES(p_actor,p_hash,now()+interval '15 minutes')
 ON CONFLICT(user_id) DO UPDATE SET code_hash=EXCLUDED.code_hash,expires_at=EXCLUDED.expires_at,consumed_by=NULL,consumed_at=NULL;
 RETURN jsonb_build_object('expires_at',now()+interval '15 minutes');
END $$;

CREATE FUNCTION veo_confirm_telegram_link(p_tenant uuid,p_hash text,p_telegram bigint,p_chat bigint,p_username text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c veo_telegram_link_codes;a veo_accounts;owner uuid;BEGIN
 SELECT owner_id INTO owner FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL;
 IF owner IS NULL OR p_telegram<=0 OR NOT EXISTS(SELECT 1 FROM veo_telegram_groups WHERE tenant_id=p_tenant AND chat_id=p_chat AND active) THEN RAISE EXCEPTION 'Choose an approved VEO group' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-telegram-groups:'||p_tenant::text,0));
 SELECT * INTO c FROM veo_telegram_link_codes WHERE code_hash=p_hash AND expires_at>now() FOR UPDATE;
 SELECT * INTO a FROM veo_accounts WHERE user_id=c.user_id AND tenant_id=p_tenant AND active FOR UPDATE;
 IF a.user_id IS NULL OR c.consumed_at IS NOT NULL AND c.consumed_by IS DISTINCT FROM p_telegram THEN RAISE EXCEPTION 'Link code expired or already used' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM veo_worker_mappings WHERE user_id=a.user_id AND telegram_user_id<>p_telegram)
 OR EXISTS(SELECT 1 FROM veo_worker_mappings WHERE telegram_user_id=p_telegram AND user_id<>a.user_id) THEN RAISE EXCEPTION 'A different Telegram identity is already linked; ask your supervisor to review it' USING ERRCODE='23505';END IF;
 INSERT INTO veo_worker_mappings VALUES(a.user_id,p_telegram) ON CONFLICT(user_id) DO NOTHING;
 UPDATE veo_telegram_link_codes SET consumed_by=p_telegram,consumed_at=coalesce(consumed_at,clock_timestamp()) WHERE user_id=a.user_id;
 IF nullif(lower(p_username),'') ~ '^[a-z0-9_]{1,32}$' THEN
  UPDATE veo_accounts SET telegram_username=lower(p_username),telegram_profile_completed_at=clock_timestamp() WHERE user_id=a.user_id;
 END IF;
 UPDATE veo_telegram_sync_state SET next_sync_at=least(next_sync_at,now()),auto_cursor=0 WHERE tenant_id=p_tenant;
 IF c.consumed_at IS NULL THEN INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value) VALUES(p_tenant,owner,'telegram_self_link',a.user_id,jsonb_build_object('telegram_user_id',p_telegram,'chat_id',p_chat));END IF;
 RETURN jsonb_build_object('linked',true,'user_id',a.user_id);
END $$;

CREATE FUNCTION veo_apply_telegram_automation(p_tenant uuid,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE owner uuid;person jsonb;a veo_accounts;g veo_telegram_groups;t veo_teams;pg uuid;ids uuid[];uid bigint;chat bigint;seen timestamptz;
 checked integer:=0;linked integer:=0;granted integer:=0;revoked integer:=0;valid boolean;state text;rec record;BEGIN
 SELECT owner_id INTO owner FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL;
 IF owner IS NULL OR p_payload->>'tenant_id' IS DISTINCT FROM p_tenant::text OR jsonb_typeof(p_payload->'workers') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'workers')>200 THEN RAISE EXCEPTION 'Invalid automatic Telegram snapshot';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-telegram-groups:'||p_tenant::text,0));
 -- Supervisors precede their members. A username declaration alone can never
 -- create an identity mapping or a permission grant.
 FOR person IN SELECT v.value FROM jsonb_array_elements(p_payload->'workers') v JOIN veo_accounts w ON w.user_id=(v.value->>'user_id')::uuid
  ORDER BY CASE w.role WHEN 'team_leader' THEN 0 WHEN 'manager' THEN 1 ELSE 2 END,w.user_id LOOP
  SELECT * INTO a FROM veo_accounts WHERE user_id=(person->>'user_id')::uuid AND tenant_id=p_tenant AND active AND role<>'owner' FOR UPDATE;
  IF NOT FOUND THEN CONTINUE;END IF;
  uid:=(person->>'telegram_user_id')::bigint;chat:=(person->>'chat_id')::bigint;seen:=(person->>'observed_at')::timestamptz;
  SELECT * INTO g FROM veo_telegram_groups WHERE tenant_id=p_tenant AND chat_id=chat AND active;
  IF g.chat_id IS NULL OR seen IS NULL OR seen NOT BETWEEN now()-interval '10 minutes' AND now()+interval '1 minute'
   OR person->'membership_confirmed' IS DISTINCT FROM 'true'::jsonb OR person->'is_bot' IS DISTINCT FROM 'false'::jsonb
   OR NOT EXISTS(SELECT 1 FROM veo_worker_mappings WHERE user_id=a.user_id AND telegram_user_id=uid) THEN CONTINUE;END IF;
  state:=person->>'membership';valid:=state IN('member','administrator','creator','restricted_member');
  IF NOT valid AND state NOT IN('left','kicked') THEN CONTINUE;END IF;
  INSERT INTO veo_telegram_auto_states VALUES(a.user_id,chat,uid,state,seen)
   ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=uid,membership=state,observed_at=seen WHERE veo_telegram_auto_states.observed_at<EXCLUDED.observed_at;
  IF NOT FOUND THEN CONTINUE;END IF;
  checked:=checked+1;
  -- Application roles are retained. Telegram administration discovers which
  -- groups an existing supervisor manages; it never promotes an account.
  IF valid AND a.role IN('team_leader','manager') AND state IN('administrator','creator') THEN
   SELECT * INTO t FROM veo_teams WHERE manager_id=a.user_id AND tenant_id=p_tenant;
   SELECT coalesce(array_agg(DISTINCT p.id),'{}') INTO ids FROM jsonb_array_elements(g.discovered_pages) d JOIN pages p ON p.id::text=d.value->>'id'
    WHERE veo_can_page(a.user_id,p.id) AND veo_can_page(owner,p.id)
    AND NOT EXISTS(SELECT 1 FROM veo_team_telegram_pages r WHERE r.team_id=t.id AND r.page_id=p.id AND r.chat_id<>chat);
   IF t.id IS NOT NULL AND cardinality(ids)>0 AND (NOT EXISTS(SELECT 1 FROM veo_team_telegram_groups WHERE team_id=t.id AND chat_id=chat)
    OR EXISTS(SELECT 1 FROM unnest(ids) p WHERE NOT EXISTS(SELECT 1 FROM veo_team_telegram_pages WHERE team_id=t.id AND page_id=p AND chat_id=chat))) THEN
    -- Keep explicit Page routes, adding registered Pages without moving any
    -- existing destination or removing a supervisor's deliberate additions.
    SELECT array_agg(DISTINCT p) INTO ids FROM(SELECT unnest(ids) p UNION SELECT page_id FROM veo_team_telegram_pages WHERE team_id=t.id AND chat_id=chat) x;
    PERFORM veo_telegram_group_action(owner,'group',jsonb_build_object('team_id',t.id,'chat_id',chat,'page_ids',ids));linked:=linked+1;
   END IF;
  END IF;
  IF valid AND EXISTS(SELECT 1 FROM veo_team_telegram_groups l JOIN veo_teams tm ON tm.id=l.team_id JOIN veo_team_telegram_pages r ON r.team_id=tm.id AND r.chat_id=chat
   WHERE l.tenant_id=p_tenant AND l.chat_id=chat AND veo_can_page(tm.manager_id,r.page_id) AND veo_can_page(veo_grant_parent(a.user_id),r.page_id)
   AND(a.role='team_leader' AND tm.manager_id IN(SELECT veo_descendants(a.user_id)) OR tm.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END)) THEN
   INSERT INTO veo_telegram_memberships VALUES(a.user_id,p_tenant,chat,uid,seen,owner)
    ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=uid,verified_at=seen;
   INSERT INTO veo_staff_telegram_groups VALUES(a.user_id,chat,seen) ON CONFLICT(user_id) DO NOTHING;
  END IF;
 END LOOP;
 -- Reconcile every known identity, including members processed before their
 -- supervisor's batch. Existing manual grants are never adopted or removed.
 FOR a IN SELECT w.* FROM veo_accounts w JOIN users u ON u.id=w.user_id AND u.is_active WHERE w.tenant_id=p_tenant AND w.active AND w.role<>'owner'
  ORDER BY CASE w.role WHEN 'team_leader' THEN 0 WHEN 'manager' THEN 1 ELSE 2 END LOOP
  FOR rec IN SELECT s.* FROM veo_telegram_auto_states s JOIN veo_worker_mappings m USING(user_id,telegram_user_id)
   JOIN veo_telegram_groups tg ON tg.tenant_id=p_tenant AND tg.chat_id=s.chat_id AND tg.active
   WHERE s.user_id=a.user_id AND s.membership IN('member','administrator','creator','restricted_member') AND s.observed_at>now()-interval '10 minutes' LOOP
   IF EXISTS(SELECT 1 FROM veo_team_telegram_groups l JOIN veo_teams tm ON tm.id=l.team_id JOIN veo_team_telegram_pages r ON r.team_id=tm.id AND r.chat_id=l.chat_id
    WHERE l.tenant_id=p_tenant AND l.chat_id=rec.chat_id AND veo_can_page(tm.manager_id,r.page_id) AND veo_can_page(veo_grant_parent(a.user_id),r.page_id)
    AND(a.role='team_leader' AND tm.manager_id IN(SELECT veo_descendants(a.user_id)) OR tm.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END)) THEN
    INSERT INTO veo_telegram_memberships VALUES(a.user_id,p_tenant,rec.chat_id,rec.telegram_user_id,rec.observed_at,owner) ON CONFLICT(user_id,chat_id) DO UPDATE SET verified_at=EXCLUDED.verified_at;
   END IF;
  END LOOP;
  FOR pg IN SELECT DISTINCT r.page_id FROM veo_telegram_memberships m JOIN veo_telegram_auto_states s USING(user_id,chat_id,telegram_user_id)
   JOIN veo_worker_mappings wm USING(user_id,telegram_user_id) JOIN veo_telegram_groups tg ON tg.tenant_id=p_tenant AND tg.chat_id=m.chat_id AND tg.active
   JOIN veo_team_telegram_groups l ON l.tenant_id=p_tenant AND l.chat_id=m.chat_id JOIN veo_teams tm ON tm.id=l.team_id JOIN veo_team_telegram_pages r ON r.team_id=tm.id AND r.chat_id=l.chat_id
   WHERE m.user_id=a.user_id AND s.membership IN('member','administrator','creator','restricted_member') AND s.observed_at>now()-interval '10 minutes'
   AND veo_can_page(tm.manager_id,r.page_id) AND veo_can_page(veo_grant_parent(a.user_id),r.page_id)
   AND(a.role='team_leader' AND tm.manager_id IN(SELECT veo_descendants(a.user_id)) OR tm.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END) LOOP
   INSERT INTO user_pages(user_id,page_id) VALUES(a.user_id,pg) ON CONFLICT(user_id,page_id) DO NOTHING;
   IF FOUND THEN
    INSERT INTO veo_telegram_auto_grants(user_id,page_id) VALUES(a.user_id,pg) ON CONFLICT DO NOTHING;granted:=granted+1;
    INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value) VALUES(p_tenant,owner,'telegram_auto_page_grant',a.user_id,jsonb_build_object('page_id',pg));
   END IF;
  END LOOP;
  FOR pg IN SELECT ag.page_id FROM veo_telegram_auto_grants ag WHERE ag.user_id=a.user_id AND(
   NOT veo_can_page(veo_grant_parent(a.user_id),ag.page_id) OR NOT EXISTS(
    SELECT 1 FROM veo_telegram_memberships m JOIN veo_telegram_auto_states s USING(user_id,chat_id,telegram_user_id) JOIN veo_worker_mappings wm USING(user_id,telegram_user_id)
    JOIN veo_telegram_groups tg ON tg.tenant_id=p_tenant AND tg.chat_id=m.chat_id AND tg.active
    JOIN veo_team_telegram_groups l ON l.tenant_id=p_tenant AND l.chat_id=m.chat_id JOIN veo_teams tm ON tm.id=l.team_id JOIN veo_team_telegram_pages r ON r.team_id=tm.id AND r.chat_id=l.chat_id
    WHERE m.user_id=a.user_id AND r.page_id=ag.page_id AND veo_can_page(tm.manager_id,r.page_id)
    AND(a.role='team_leader' AND tm.manager_id IN(SELECT veo_descendants(a.user_id)) OR tm.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END)
    -- Unknown / stale observations retain existing access; only a confirmed
    -- departure, a removed route, or revoked supervisor access removes it.
    AND NOT(s.membership IN('left','kicked') AND s.observed_at>now()-interval '10 minutes')
   )) LOOP
   DELETE FROM user_pages WHERE user_id=a.user_id AND page_id=pg;DELETE FROM veo_telegram_auto_grants WHERE user_id=a.user_id AND page_id=pg;revoked:=revoked+1;
   INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value) VALUES(p_tenant,owner,'telegram_auto_page_revoke',a.user_id,jsonb_build_object('page_id',pg));
  END LOOP;
 END LOOP;
 UPDATE veo_telegram_sync_state SET auto_cursor=greatest(0,coalesce((p_payload->>'next_offset')::int,0)),auto_checked_at=clock_timestamp(),auto_last_error=NULL WHERE tenant_id=p_tenant;
 RETURN jsonb_build_object('checked',checked,'linked_groups',linked,'granted_pages',granted,'revoked_pages',revoked);
END $$;

-- An explicit supervisor Page edit becomes the authority for its selected
-- grants, rather than letting later automation remove those manual grants.
ALTER FUNCTION veo_action(uuid,text,jsonb) RENAME TO veo_action_before_automatic_groups;
CREATE FUNCTION veo_action(p_actor uuid,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;BEGIN
 result:=veo_action_before_automatic_groups(p_actor,p_action,p_data);
 IF p_action='assign_pages' THEN DELETE FROM veo_telegram_auto_grants WHERE user_id=(p_data->>'user_id')::uuid;END IF;
 RETURN result;
END $$;
ALTER FUNCTION veo_telegram_groups_page(uuid) RENAME TO veo_telegram_groups_page_before_automatic;
CREATE FUNCTION veo_telegram_groups_page(p_actor uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE result jsonb;BEGIN
 result:=veo_telegram_groups_page_before_automatic(p_actor);
 RETURN result||jsonb_build_object('automation',(SELECT jsonb_build_object('checked_at',s.auto_checked_at,'error',s.auto_last_error,'pending',s.auto_cursor>0)
  FROM veo_telegram_sync_state s WHERE s.tenant_id=(result->'scope'->>'tenant_id')::uuid));
END $$;
DO $$ DECLARE tab text;fn record;BEGIN
 FOREACH tab IN ARRAY ARRAY['veo_telegram_link_codes','veo_telegram_auto_grants','veo_telegram_auto_states'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,anon,authenticated',tab);EXECUTE format('GRANT ALL ON %I TO service_role',tab);
 END LOOP;
 FOR fn IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('veo_create_telegram_link','veo_confirm_telegram_link','veo_apply_telegram_automation','veo_action','veo_telegram_groups_page') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',fn.signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',fn.signature);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611080007_veo_automatic_telegram_teams.sql','b69e986262bdfddb773883f51e379ec4c7aebdabfa4e47fe8d33de88889c62a3');

-- FILE: 202611080008_veo_automatic_editor_dispatch.sql SHA256: 9cde2e8b84ff22f4fdbff8f325751a429346f677521c4f7bef68e39cc6d8b6c3

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;
ALTER TABLE veo_telegram_groups ADD COLUMN intake_enabled boolean NOT NULL DEFAULT false;
ALTER FUNCTION veo_sync_telegram_groups(uuid,jsonb) RENAME TO veo_sync_telegram_groups_before_intake_policy;
CREATE FUNCTION veo_sync_telegram_groups(p_actor uuid,p_groups jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE result jsonb;BEGIN
 result:=veo_sync_telegram_groups_before_intake_policy(p_actor,p_groups);
 UPDATE veo_telegram_groups g SET intake_enabled=(j.value->'intake_enabled'='true'::jsonb) IS TRUE FROM jsonb_array_elements(p_groups) j
 WHERE g.tenant_id=(SELECT tenant_id FROM veo_accounts WHERE user_id=p_actor) AND g.chat_id=(j.value->>'chat_id')::bigint;
 RETURN result;
END $$;
CREATE TABLE veo_intake_auto_policy(
 tenant_id uuid PRIMARY KEY REFERENCES veo_tenants(id),enabled boolean NOT NULL DEFAULT true,enabled_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 wait_minutes integer NOT NULL DEFAULT 60 CHECK(wait_minutes BETWEEN 1 AND 1440),accept_minutes integer NOT NULL DEFAULT 15 CHECK(accept_minutes BETWEEN 1 AND 60),
 wait_anchor text NOT NULL DEFAULT 'inquiry' CHECK(wait_anchor IN('inquiry','ready'))
);
INSERT INTO veo_intake_auto_policy(tenant_id) SELECT id FROM veo_tenants WHERE launch_at IS NOT NULL;
CREATE TABLE veo_intake_dispatch(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES veo_tenants(id),contact_id uuid NOT NULL UNIQUE REFERENCES contacts(id),
 page_id uuid NOT NULL REFERENCES pages(id),team_id uuid NOT NULL REFERENCES veo_teams(id),chat_id bigint NOT NULL CHECK(chat_id<0),
 arrived_at timestamptz NOT NULL,eligible_at timestamptz NOT NULL,announced_at timestamptz,announcement_message_id bigint,
 status text NOT NULL DEFAULT 'waiting' CHECK(status IN('waiting','offered','accepted','cancelled')),
 offer_id uuid REFERENCES veo_client_offers(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),last_error text
);
CREATE INDEX veo_intake_dispatch_due ON veo_intake_dispatch(tenant_id,eligible_at) WHERE status IN('waiting','offered');
CREATE TABLE veo_intake_dispatch_attempts(
 offer_id uuid PRIMARY KEY REFERENCES veo_client_offers(id),dispatch_id uuid NOT NULL REFERENCES veo_intake_dispatch(id),
 user_id uuid NOT NULL REFERENCES veo_accounts(user_id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),delivered_at timestamptz,telegram_message_id bigint
);
CREATE INDEX veo_intake_dispatch_worker ON veo_intake_dispatch_attempts(user_id,created_at DESC);
CREATE INDEX veo_intake_dispatch_attempt ON veo_intake_dispatch_attempts(dispatch_id,user_id,created_at DESC);
CREATE FUNCTION veo_dispatch_fresh_eligible(p_contact uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM contacts c JOIN pages pg ON pg.id=c.page_id AND pg.veo_enabled JOIN veo_intake_auto_policy p ON p.tenant_id=pg.veo_tenant_id AND p.enabled
 WHERE c.id=p_contact AND coalesce(c.first_interaction_at,c.created_at)>=p.enabled_at AND c.last_inbound_at IS NOT NULL
 AND c.pipeline_stage NOT IN('converted','order_created','not_qualified','opted_out')
 AND NOT EXISTS(SELECT 1 FROM veo_orders WHERE contact_id=c.id) AND NOT EXISTS(SELECT 1 FROM veo_closed_deals WHERE contact_id=c.id AND voided_at IS NULL)
 AND NOT EXISTS(SELECT 1 FROM veo_client_claims WHERE contact_id=c.id AND(user_id IS NOT NULL OR released_at IS NOT NULL))
 AND EXISTS(SELECT 1 FROM veo_team_telegram_pages r JOIN veo_teams t ON t.id=r.team_id AND t.tenant_id=p.tenant_id
 JOIN veo_telegram_groups g ON g.tenant_id=p.tenant_id AND g.chat_id=r.chat_id AND g.active AND g.intake_enabled
 WHERE r.page_id=c.page_id AND veo_can_page(t.manager_id,c.page_id)))
$$;

-- Availability must survive the one-hour client wait. Acceptance and /busy
-- still turn Ready off; Philippine midnight ends the current declaration.
DO $$ DECLARE definition text;old text:=$old$until_at:=least(at+interval '30 minutes',(((at AT TIME ZONE 'Asia/Manila')::date+1)::timestamp AT TIME ZONE 'Asia/Manila'));$old$;BEGIN
 definition:=pg_get_functiondef('veo_intake_action(uuid,text,jsonb)'::regprocedure);
 IF strpos(definition,old)=0 THEN RAISE EXCEPTION 'Readiness implementation changed';END IF;
 definition:=replace(definition,old,$new$until_at:=(((at AT TIME ZONE 'Asia/Manila')::date+1)::timestamp AT TIME ZONE 'Asia/Manila');$new$);
 EXECUTE definition;
END $$;

CREATE FUNCTION veo_dispatch_editor_allowed(p_user uuid,p_team uuid,p_page uuid,p_chat bigint,p_now timestamptz) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM veo_accounts a JOIN users u ON u.id=a.user_id AND u.is_active JOIN veo_teams t ON t.id=p_team AND t.tenant_id=a.tenant_id
 JOIN veo_intake_readiness r ON r.user_id=a.user_id AND r.status='ready' AND r.expires_at>p_now
 JOIN veo_telegram_memberships m ON m.user_id=a.user_id AND m.chat_id=p_chat JOIN veo_worker_mappings w ON w.user_id=m.user_id AND w.telegram_user_id=m.telegram_user_id
 LEFT JOIN veo_telegram_group_states s ON s.user_id=m.user_id AND s.chat_id=m.chat_id
 WHERE a.user_id=p_user AND a.active AND a.role IN('member','manager') AND t.manager_id=CASE WHEN a.role='manager' THEN a.user_id ELSE a.parent_id END
 AND veo_can_page(p_user,p_page) AND veo_staff_can_telegram_group(p_user,p_chat)
 AND EXISTS(SELECT 1 FROM veo_telegram_groups g WHERE g.tenant_id=a.tenant_id AND g.chat_id=p_chat AND g.active AND g.intake_enabled)
 AND ((s.observed_at>p_now-interval '10 minutes' AND s.payload->'membership_confirmed'='true'::jsonb AND s.payload->'is_bot'='false'::jsonb
 AND s.payload->>'membership' IN('member','administrator','creator','restricted_member')) OR(s.user_id IS NULL AND m.verified_at>p_now-interval '10 minutes'))
 AND veo_telegram_destination(p_team,p_page,p_user)->>'chat_id'=p_chat::text)
$$;

CREATE FUNCTION veo_automatic_intake_tick(p_tenant uuid,p_now timestamptz DEFAULT clock_timestamp()) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp SET jit=off SET plan_cache_mode=force_custom_plan AS $$
DECLARE policy veo_intake_auto_policy;d veo_intake_dispatch;inquiry record;route record;old veo_client_offers;worker uuid;owner uuid;result jsonb;ready_at timestamptz;
 announced integer:=0;offered integer:=0;cancelled integer:=0;BEGIN
 SELECT * INTO policy FROM veo_intake_auto_policy WHERE tenant_id=p_tenant AND enabled;
 IF NOT FOUND THEN RETURN jsonb_build_object('enabled',false);END IF;
 SELECT owner_id INTO owner FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL;
 IF owner IS NULL THEN RAISE EXCEPTION 'Tenant is not launched';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-intake:'||p_tenant::text,0));
 -- The activation cutoff excludes retained contacts and imported history. Only
 -- genuinely new customer inquiries can start an automatic editor rotation.
 FOR inquiry IN SELECT q.id,q.page_id,coalesce(x.first_interaction_at,x.created_at) arrived_at FROM veo_intake_contacts q JOIN contacts x ON x.id=q.id JOIN pages pg ON pg.id=q.page_id
  WHERE pg.veo_tenant_id=p_tenant AND pg.veo_enabled AND q.last_interaction_at>=policy.enabled_at AND coalesce(x.first_interaction_at,x.created_at)>=policy.enabled_at
  AND q.pipeline_stage NOT IN('converted','order_created','not_qualified','opted_out') AND x.last_inbound_at IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM veo_intake_dispatch WHERE contact_id=q.id)
  AND NOT EXISTS(SELECT 1 FROM veo_client_claims WHERE contact_id=q.id AND(user_id IS NOT NULL OR released_at IS NOT NULL))
  AND NOT EXISTS(SELECT 1 FROM veo_orders WHERE contact_id=q.id) AND NOT EXISTS(SELECT 1 FROM veo_closed_deals WHERE contact_id=q.id AND voided_at IS NULL)
  ORDER BY q.last_interaction_at,q.id LIMIT 30 LOOP
  SELECT t.id team_id,l.chat_id INTO route FROM veo_team_telegram_pages r JOIN veo_team_telegram_groups l USING(team_id,chat_id) JOIN veo_teams t ON t.id=r.team_id
   JOIN veo_telegram_groups g ON g.tenant_id=t.tenant_id AND g.chat_id=l.chat_id AND g.active AND g.intake_enabled JOIN veo_accounts a ON a.user_id=t.manager_id AND a.active
   WHERE r.page_id=inquiry.page_id AND t.tenant_id=p_tenant AND veo_can_page(t.manager_id,inquiry.page_id)
   ORDER BY EXISTS(SELECT 1 FROM veo_accounts w WHERE veo_dispatch_editor_allowed(w.user_id,t.id,inquiry.page_id,l.chat_id,p_now)) DESC,
    (SELECT max(created_at) FROM veo_intake_dispatch WHERE team_id=t.id) ASC NULLS FIRST,t.id LIMIT 1;
  IF FOUND THEN
   INSERT INTO veo_intake_dispatch(tenant_id,contact_id,page_id,team_id,chat_id,arrived_at,eligible_at)
    VALUES(p_tenant,inquiry.id,inquiry.page_id,route.team_id,route.chat_id,inquiry.arrived_at,inquiry.arrived_at+make_interval(mins=>policy.wait_minutes)) ON CONFLICT(contact_id) DO NOTHING;
   IF FOUND THEN announced:=announced+1;END IF;
  END IF;
 END LOOP;
 FOR d IN SELECT * FROM veo_intake_dispatch WHERE tenant_id=p_tenant AND status IN('waiting','offered') ORDER BY eligible_at,id LIMIT 50 FOR UPDATE LOOP
  IF EXISTS(SELECT 1 FROM veo_client_claims WHERE contact_id=d.contact_id AND user_id IS NOT NULL) THEN
   UPDATE veo_intake_dispatch SET status='accepted',last_error=NULL WHERE id=d.id;CONTINUE;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM contacts c JOIN veo_team_telegram_pages r ON r.team_id=d.team_id AND r.page_id=c.page_id AND r.chat_id=d.chat_id
    JOIN veo_telegram_groups g ON g.tenant_id=p_tenant AND g.chat_id=d.chat_id AND g.active AND g.intake_enabled
    WHERE c.id=d.contact_id AND c.pipeline_stage NOT IN('converted','order_created','not_qualified','opted_out') AND veo_can_page((SELECT manager_id FROM veo_teams WHERE id=d.team_id),c.page_id))
   OR EXISTS(SELECT 1 FROM veo_orders WHERE contact_id=d.contact_id) OR EXISTS(SELECT 1 FROM veo_closed_deals WHERE contact_id=d.contact_id AND voided_at IS NULL)
   OR EXISTS(SELECT 1 FROM veo_client_claims WHERE contact_id=d.contact_id AND released_at IS NOT NULL) THEN
   UPDATE veo_intake_dispatch SET status='cancelled',last_error='Inquiry eligibility or configured group changed' WHERE id=d.id;
   UPDATE veo_client_offers SET status='cancelled',ended_at=p_now WHERE id=d.offer_id AND status='pending';cancelled:=cancelled+1;CONTINUE;
  END IF;
  IF d.offer_id IS NOT NULL THEN
   SELECT * INTO old FROM veo_client_offers WHERE id=d.offer_id;
   IF old.status='pending' AND old.expires_at>p_now THEN CONTINUE;END IF;
   IF old.status IN('expired','pending') AND old.expires_at<=p_now THEN
    UPDATE veo_client_offers SET status='expired',ended_at=p_now WHERE id=old.id AND status='pending';
    IF EXISTS(SELECT 1 FROM veo_intake_dispatch_attempts WHERE offer_id=old.id AND delivered_at IS NOT NULL) THEN
     UPDATE veo_intake_readiness SET status='busy',updated_at=p_now WHERE user_id=old.offered_to AND status='ready' AND updated_at<=old.created_at;
    END IF;
   END IF;
   UPDATE veo_intake_dispatch SET status='waiting',offer_id=NULL WHERE id=d.id;
  END IF;
  IF d.announced_at IS NULL OR(policy.wait_anchor='inquiry' AND d.eligible_at>p_now) THEN CONTINUE;END IF;
  IF EXISTS(SELECT 1 FROM veo_client_offers WHERE contact_id=d.contact_id AND status='pending' AND expires_at>p_now) THEN CONTINUE;END IF;
  SELECT a.user_id INTO worker FROM veo_accounts a JOIN veo_intake_readiness r ON r.user_id=a.user_id
   WHERE veo_dispatch_editor_allowed(a.user_id,d.team_id,d.page_id,d.chat_id,p_now)
   AND(policy.wait_anchor='inquiry' OR r.updated_at<=p_now-make_interval(mins=>policy.wait_minutes))
   AND NOT EXISTS(SELECT 1 FROM veo_client_offers o WHERE o.offered_to=a.user_id AND o.status='pending' AND o.expires_at>p_now)
   AND NOT EXISTS(SELECT 1 FROM veo_intake_dispatch_attempts a2 WHERE a2.dispatch_id=d.id AND a2.user_id=a.user_id AND a2.created_at>=r.updated_at)
   ORDER BY(SELECT max(created_at) FROM veo_intake_dispatch_attempts WHERE user_id=a.user_id) ASC NULLS FIRST,r.updated_at,a.user_id LIMIT 1;
  IF worker IS NULL THEN UPDATE veo_intake_dispatch SET last_error='Waiting for an eligible Ready editor in this team and Telegram group' WHERE id=d.id;CONTINUE;END IF;
  BEGIN
   result:=veo_intake_action(owner,'offer',jsonb_build_object('request_id',gen_random_uuid(),'contact_id',d.contact_id,'user_id',worker,'reason','Automatic fresh inquiry allocation after the configured wait'));
   INSERT INTO veo_intake_dispatch_attempts(offer_id,dispatch_id,user_id) VALUES((result->>'offer_id')::uuid,d.id,worker);
   UPDATE veo_intake_dispatch SET status='offered',offer_id=(result->>'offer_id')::uuid,last_error=NULL WHERE id=d.id;offered:=offered+1;
  EXCEPTION WHEN OTHERS THEN UPDATE veo_intake_dispatch SET last_error='Editor availability changed; retry on the next scheduled run' WHERE id=d.id;
  END;
 END LOOP;
 RETURN jsonb_build_object('enabled',true,'new_announcements',announced,'offered',offered,'cancelled',cancelled);
END $$;

CREATE FUNCTION veo_intake_notice(p_tenant uuid,p_notice uuid,p_chat bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE d veo_intake_dispatch;c contacts;p pages;policy veo_intake_auto_policy;thread bigint;BEGIN
 SELECT * INTO d FROM veo_intake_dispatch WHERE id=p_notice AND tenant_id=p_tenant AND chat_id=p_chat AND status IN('waiting','offered');
 IF d.id IS NULL OR EXISTS(SELECT 1 FROM veo_client_claims WHERE contact_id=d.contact_id AND user_id IS NOT NULL) THEN RETURN NULL;END IF;
 SELECT * INTO c FROM contacts WHERE id=d.contact_id;SELECT * INTO p FROM pages WHERE id=d.page_id;
 SELECT * INTO policy FROM veo_intake_auto_policy WHERE tenant_id=p_tenant AND enabled;IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT l.thread_id INTO thread FROM veo_team_telegram_groups l JOIN veo_team_telegram_pages r USING(team_id,chat_id) JOIN veo_telegram_groups g ON g.tenant_id=l.tenant_id AND g.chat_id=l.chat_id AND g.active AND g.intake_enabled
 WHERE l.team_id=d.team_id AND l.chat_id=p_chat AND r.page_id=d.page_id AND veo_can_page((SELECT manager_id FROM veo_teams WHERE id=d.team_id),d.page_id);
 IF NOT FOUND OR c.pipeline_stage IN('converted','order_created','not_qualified','opted_out') OR EXISTS(SELECT 1 FROM veo_orders WHERE contact_id=c.id) OR EXISTS(SELECT 1 FROM veo_closed_deals WHERE contact_id=c.id AND voided_at IS NULL) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('notice_id',d.id,'chat_id',p_chat,'thread_id',thread,'text','New client inquiry: '||left(coalesce(c.name,'New client'),100)||E'\nPage: '||left(p.name,100)||
 E'\nThis is a fresh inquiry, not a Closed or Done Deal.\n'||CASE WHEN policy.wait_anchor='inquiry' THEN 'First editor offer after '||to_char(d.eligible_at AT TIME ZONE 'Asia/Manila','HH24:MI')||' PHT (one-hour inquiry wait).' ELSE 'Editor offer after an editor has been Ready for one hour.' END||
 E'\nUse /ready if you can take a client, or /busy if unavailable. The selected editor must accept within 15 minutes; otherwise another Ready editor receives the offer.',
 'reply_markup',jsonb_build_object('inline_keyboard',jsonb_build_array(jsonb_build_array(jsonb_build_object('text','Ready','callback_data','cw:ready'),jsonb_build_object('text','Busy','callback_data','cw:busy')),jsonb_build_array(jsonb_build_object('text','Open client','url','https://veochatbot.vercel.app/dashboard/contacts/'||c.id::text||'?pageId='||p.id::text)))));
END $$;

CREATE FUNCTION veo_intake_notice_pending(p_tenant uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(jsonb_build_object('notice_id',d.id,'chat_id',d.chat_id)),'[]') FROM(
 SELECT * FROM veo_intake_dispatch WHERE tenant_id=p_tenant AND announced_at IS NULL AND status IN('waiting','offered') ORDER BY created_at,id LIMIT 30) d
 WHERE veo_intake_notice(p_tenant,d.id,d.chat_id) IS NOT NULL
$$;
CREATE FUNCTION veo_ack_intake_notice(p_tenant uuid,p_notice uuid,p_chat bigint,p_message bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF p_message<=0 THEN RETURN false;END IF;
 UPDATE veo_intake_dispatch SET announced_at=coalesce(announced_at,clock_timestamp()),announcement_message_id=coalesce(announcement_message_id,p_message)
 WHERE id=p_notice AND tenant_id=p_tenant AND chat_id=p_chat AND(announcement_message_id IS NULL OR announcement_message_id=p_message);
 RETURN FOUND;
END $$;
CREATE FUNCTION veo_ack_intake_offer(p_tenant uuid,p_offer uuid,p_chat bigint,p_message bigint,p_sent_at timestamptz DEFAULT clock_timestamp()) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a veo_intake_dispatch_attempts;until_at timestamptz;BEGIN
 SELECT x.* INTO a FROM veo_intake_dispatch_attempts x JOIN veo_intake_dispatch d ON d.id=x.dispatch_id AND d.tenant_id=p_tenant AND d.chat_id=p_chat WHERE x.offer_id=p_offer FOR UPDATE OF x;
 IF a.offer_id IS NULL THEN RETURN true;END IF;
 IF a.delivered_at IS NOT NULL THEN RETURN a.telegram_message_id=p_message;END IF;
 IF p_message<=0 OR p_sent_at<a.created_at-interval '1 minute' OR p_sent_at>clock_timestamp()+interval '1 minute' THEN RETURN false;END IF;
 SELECT least(p_sent_at+make_interval(mins=>p.accept_minutes),r.expires_at) INTO until_at FROM veo_intake_auto_policy p JOIN veo_intake_readiness r ON r.user_id=a.user_id WHERE p.tenant_id=p_tenant;
 UPDATE veo_client_offers SET expires_at=until_at WHERE id=p_offer AND tenant_id=p_tenant AND status='pending';
 IF NOT FOUND THEN RETURN true;END IF;
 UPDATE veo_intake_dispatch_attempts SET delivered_at=p_sent_at,telegram_message_id=p_message WHERE offer_id=p_offer;
 UPDATE veo_telegram_intake_requests SET expires_at=until_at WHERE offer_id=p_offer;
 UPDATE veo_telegram_intake_tokens SET expires_at=until_at WHERE request_id IN(SELECT id FROM veo_telegram_intake_requests WHERE offer_id=p_offer);
 RETURN true;
END $$;

ALTER FUNCTION veo_intake_action(uuid,text,jsonb) RENAME TO veo_intake_action_before_auto_dispatch;
CREATE FUNCTION veo_intake_action(p_actor uuid,p_action text,p_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE d veo_intake_dispatch;policy veo_intake_auto_policy;BEGIN
 IF p_action IN('accept','offer') THEN
  IF NOT EXISTS(SELECT 1 FROM contacts WHERE id=(p_data->>'contact_id')::uuid AND veo_can_page(p_actor,page_id)) THEN RAISE EXCEPTION 'Client Page access denied' USING ERRCODE='42501';END IF;
  SELECT x.* INTO d FROM veo_intake_dispatch x JOIN veo_intake_auto_policy p ON p.tenant_id=x.tenant_id AND p.enabled WHERE x.contact_id=(p_data->>'contact_id')::uuid AND x.status IN('waiting','offered');
  IF d.id IS NULL AND veo_dispatch_fresh_eligible((p_data->>'contact_id')::uuid) THEN RAISE EXCEPTION 'This inquiry is in the automatic Telegram queue. Wait for your editor offer before accepting it';END IF;
  IF d.id IS NOT NULL THEN
   SELECT * INTO policy FROM veo_intake_auto_policy WHERE tenant_id=d.tenant_id;
   IF p_action='accept' AND nullif(p_data->>'offer_id','') IS NULL OR p_action='offer' AND(
    policy.wait_anchor='inquiry' AND d.eligible_at>clock_timestamp() OR policy.wait_anchor='ready' AND NOT EXISTS(
    SELECT 1 FROM veo_intake_readiness WHERE user_id=(p_data->>'user_id')::uuid AND status='ready' AND updated_at<=clock_timestamp()-make_interval(mins=>policy.wait_minutes)))
   THEN RAISE EXCEPTION 'This inquiry is in the automatic Telegram queue. Wait for your editor offer before accepting it';END IF;
  END IF;
 END IF;
 RETURN veo_intake_action_before_auto_dispatch(p_actor,p_action,p_data);
END $$;
ALTER FUNCTION veo_intake_page(uuid,text,uuid,text,integer) RENAME TO veo_intake_page_before_auto_dispatch;
CREATE FUNCTION veo_intake_page(p_actor uuid,p_view text DEFAULT 'pool',p_page uuid DEFAULT NULL,p_search text DEFAULT '',p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE result jsonb;BEGIN
 result:=veo_intake_page_before_auto_dispatch(p_actor,p_view,p_page,p_search,p_offset);
 RETURN result||jsonb_build_object('auto_policy',(SELECT jsonb_build_object('enabled',p.enabled,'wait_minutes',p.wait_minutes,'accept_minutes',p.accept_minutes,'wait_anchor',p.wait_anchor) FROM veo_intake_auto_policy p JOIN veo_accounts a ON a.tenant_id=p.tenant_id WHERE a.user_id=p_actor),
 'items',coalesce((SELECT jsonb_agg(i.value||jsonb_build_object('auto_assignment',coalesce((SELECT jsonb_build_object('status',d.status,'eligible_at',d.eligible_at,'announced_at',d.announced_at,'last_error',d.last_error) FROM veo_intake_dispatch d WHERE d.contact_id=(i.value->>'id')::uuid),
 (SELECT jsonb_build_object('status','waiting','eligible_at',coalesce(c.first_interaction_at,c.created_at)+make_interval(mins=>p.wait_minutes),'announced_at',NULL,'last_error','Waiting for the next scheduled Telegram announcement')
 FROM contacts c JOIN pages pg ON pg.id=c.page_id JOIN veo_intake_auto_policy p ON p.tenant_id=pg.veo_tenant_id WHERE c.id=(i.value->>'id')::uuid AND veo_dispatch_fresh_eligible(c.id))))) FROM jsonb_array_elements(result->'items') i),'[]'));
END $$;
DO $$ DECLARE tab text;fn record;BEGIN
 FOREACH tab IN ARRAY ARRAY['veo_intake_auto_policy','veo_intake_dispatch','veo_intake_dispatch_attempts'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('REVOKE ALL ON %I FROM PUBLIC,anon,authenticated',tab);EXECUTE format('GRANT ALL ON %I TO service_role',tab);
 END LOOP;
 FOR fn IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('veo_dispatch_editor_allowed','veo_dispatch_fresh_eligible','veo_automatic_intake_tick','veo_intake_notice','veo_intake_notice_pending','veo_ack_intake_notice','veo_ack_intake_offer','veo_intake_action','veo_intake_page','veo_sync_telegram_groups') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',fn.signature);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',fn.signature);
 END LOOP;
END $$;
NOTIFY pgrst,'reload schema';


