 ALTER TABLE veo_jev_policy DROP CONSTRAINT IF EXISTS veo_jev_policy_mode_check;
 ALTER TABLE veo_jev_policy ADD CONSTRAINT veo_jev_policy_mode_check CHECK(mode IN('observe','active'));
