-- FILE: 202611080014_veo_telegram_dm_pairing.sql SHA256: 6bc98e2cb5da0b20bc3199a24ebf091a59094f8ddd42343180949419acb7775b

SET LOCAL lock_timeout='10s';
SET LOCAL jit=off;

CREATE TABLE veo_telegram_pairing_codes(
 code_hash text PRIMARY KEY CHECK(code_hash ~ '^[a-f0-9]{64}$'),
 tenant_id uuid NOT NULL REFERENCES veo_tenants(id), telegram_user_id bigint NOT NULL CHECK(telegram_user_id>0),
 chat_id bigint NOT NULL, username text, expires_at timestamptz NOT NULL,
 consumed_by uuid REFERENCES veo_accounts(user_id), consumed_at timestamptz,
 FOREIGN KEY(tenant_id,chat_id) REFERENCES veo_telegram_groups(tenant_id,chat_id)
);
CREATE INDEX veo_telegram_pairing_pending ON veo_telegram_pairing_codes(telegram_user_id,expires_at) WHERE consumed_at IS NULL;

CREATE FUNCTION veo_issue_telegram_pairing(p_tenant uuid,p_hash text,p_telegram bigint,p_chat bigint,p_username text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM veo_telegram_groups WHERE tenant_id=p_tenant AND chat_id=p_chat AND active)
 OR p_telegram<=0 OR p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid pairing request' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM veo_worker_mappings WHERE telegram_user_id=p_telegram) THEN RAISE EXCEPTION 'Telegram account already linked' USING ERRCODE='23505'; END IF;
 DELETE FROM veo_telegram_pairing_codes WHERE telegram_user_id=p_telegram AND consumed_at IS NULL;
 INSERT INTO veo_telegram_pairing_codes(code_hash,tenant_id,telegram_user_id,chat_id,username,expires_at)
 VALUES(p_hash,p_tenant,p_telegram,p_chat,nullif(p_username,''),now()+interval '10 minutes');
 RETURN jsonb_build_object('expires_at',now()+interval '10 minutes');
END $$;

CREATE FUNCTION veo_confirm_telegram_pairing(p_actor uuid,p_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c veo_telegram_pairing_codes;a veo_accounts;owner uuid;
BEGIN
 SELECT * INTO c FROM veo_telegram_pairing_codes WHERE code_hash=p_hash AND expires_at>now() AND consumed_at IS NULL FOR UPDATE;
 SELECT * INTO a FROM veo_accounts WHERE user_id=p_actor AND active FOR UPDATE;
 IF a.user_id IS NULL OR c.code_hash IS NULL OR a.tenant_id<>c.tenant_id THEN RAISE EXCEPTION 'Pairing code expired or invalid' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM veo_worker_mappings WHERE user_id=a.user_id AND telegram_user_id<>c.telegram_user_id)
 OR EXISTS(SELECT 1 FROM veo_worker_mappings WHERE telegram_user_id=c.telegram_user_id AND user_id<>a.user_id) THEN RAISE EXCEPTION 'Telegram account already linked' USING ERRCODE='23505'; END IF;
 SELECT owner_id INTO owner FROM veo_tenants WHERE id=a.tenant_id;
 INSERT INTO veo_worker_mappings(user_id,telegram_user_id) VALUES(a.user_id,c.telegram_user_id) ON CONFLICT(user_id) DO NOTHING;
 INSERT INTO veo_telegram_memberships(user_id,tenant_id,chat_id,telegram_user_id,verified_at,verified_by)
 VALUES(a.user_id,a.tenant_id,c.chat_id,c.telegram_user_id,clock_timestamp(),owner)
 ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=EXCLUDED.telegram_user_id,verified_at=EXCLUDED.verified_at,verified_by=EXCLUDED.verified_by;
 IF nullif(lower(c.username),'') ~ '^[a-z0-9_]{1,32}$' THEN UPDATE veo_accounts SET telegram_username=lower(c.username),telegram_profile_completed_at=clock_timestamp() WHERE user_id=a.user_id; END IF;
 UPDATE veo_telegram_pairing_codes SET consumed_by=a.user_id,consumed_at=clock_timestamp() WHERE code_hash=p_hash;
 UPDATE veo_telegram_sync_state SET next_sync_at=least(next_sync_at,now()),cursor=0 WHERE tenant_id=a.tenant_id;
 INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,after_value) VALUES(a.tenant_id,a.user_id,'telegram_self_link',a.user_id,jsonb_build_object('telegram_user_id',c.telegram_user_id,'chat_id',c.chat_id,'method','dm_pairing'));
 RETURN jsonb_build_object('linked',true);
END $$;

ALTER TABLE veo_telegram_pairing_codes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON veo_telegram_pairing_codes FROM PUBLIC,anon,authenticated;
GRANT ALL ON veo_telegram_pairing_codes TO service_role;
REVOKE ALL ON FUNCTION veo_issue_telegram_pairing(uuid,text,bigint,bigint,text),veo_confirm_telegram_pairing(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_issue_telegram_pairing(uuid,text,bigint,bigint,text),veo_confirm_telegram_pairing(uuid,text) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611080014_veo_telegram_dm_pairing.sql','6bc98e2cb5da0b20bc3199a24ebf091a59094f8ddd42343180949419acb7775b');

-- FILE: 202611090001_veo_hierarchy_recursion_guards.sql SHA256: a93f4bab8e89edaa6a33f7b9fbd8cb476dc53c68f1dff5ee7379de25c08db5a0

SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '10s';

CREATE INDEX IF NOT EXISTS veo_accounts_parent_tenant_guard_idx
 ON public.veo_accounts(parent_id, tenant_id, user_id);

-- Include departed hierarchy nodes so historical reports and their active
-- descendants retain their existing semantics. Invalid cycles fail closed.
CREATE OR REPLACE FUNCTION public.veo_branch(p_actor uuid) RETURNS SETOF uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH RECURSIVE branch AS (
  SELECT a.user_id,a.tenant_id,ARRAY[a.user_id] AS visited,false AS cycle,1 AS depth
  FROM veo_accounts a WHERE a.user_id=p_actor AND a.active
  UNION ALL
  SELECT a.user_id,a.tenant_id,b.visited||a.user_id,a.user_id=ANY(b.visited),b.depth+1
  FROM veo_accounts a JOIN branch b ON a.parent_id=b.user_id AND a.tenant_id=b.tenant_id
  WHERE NOT b.cycle AND b.depth<64
 )
 SELECT b.user_id FROM branch b
 WHERE NOT EXISTS (
  SELECT 1 FROM branch invalid WHERE invalid.cycle OR (invalid.depth=64 AND EXISTS(
   SELECT 1 FROM veo_accounts child WHERE child.parent_id=invalid.user_id AND child.tenant_id=invalid.tenant_id
  ))
 )
$$;

CREATE OR REPLACE FUNCTION public.veo_descendants(p_actor uuid) RETURNS SETOF uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT user_id FROM veo_accounts WHERE user_id IN(SELECT veo_branch(p_actor)) AND active
$$;

CREATE OR REPLACE FUNCTION public.veo_grant_parent(p_user uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH RECURSIVE parents AS (
  SELECT p.user_id,p.parent_id,p.tenant_id,p.active,p.departed_at,a.tenant_id AS actor_tenant,
   ARRAY[p.user_id] AS visited,false AS cycle,1 AS depth
  FROM veo_accounts a JOIN veo_accounts p ON p.user_id=a.parent_id WHERE a.user_id=p_user
  UNION ALL
  SELECT a.user_id,a.parent_id,a.tenant_id,a.active,a.departed_at,p.actor_tenant,
   p.visited||a.user_id,a.user_id=ANY(p.visited),p.depth+1
  FROM veo_accounts a JOIN parents p ON a.user_id=p.parent_id
  WHERE p.departed_at IS NOT NULL AND NOT p.cycle AND p.depth<64
 )
 SELECT user_id FROM parents WHERE active AND NOT EXISTS (
  SELECT 1 FROM parents invalid WHERE invalid.cycle OR invalid.tenant_id<>invalid.actor_tenant
   OR (invalid.depth=64 AND invalid.departed_at IS NOT NULL AND invalid.parent_id IS NOT NULL)
 ) ORDER BY depth LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.veo_can_page(p_actor uuid,p_page uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH RECURSIVE parents AS (
  SELECT a.user_id,a.parent_id,a.tenant_id,a.active,a.departed_at,
   ARRAY[a.user_id] AS visited,false AS cycle,1 AS depth
  FROM veo_accounts a WHERE a.user_id=p_actor
  UNION ALL
  SELECT b.user_id,b.parent_id,b.tenant_id,b.active,b.departed_at,
   c.visited||b.user_id,b.user_id=ANY(c.visited),c.depth+1
  FROM veo_accounts b JOIN parents c ON c.parent_id=b.user_id
  WHERE NOT c.cycle AND c.depth<64
 )
 SELECT EXISTS (
  SELECT 1 FROM veo_accounts a JOIN veo_tenants t ON t.id=a.tenant_id
  JOIN pages p ON p.id=p_page AND p.veo_tenant_id=a.tenant_id AND p.veo_enabled
  WHERE a.user_id=p_actor AND a.active AND t.launch_at IS NOT NULL
   AND EXISTS(SELECT 1 FROM parents WHERE parent_id IS NULL)
   AND NOT EXISTS(SELECT 1 FROM parents b WHERE b.cycle OR b.tenant_id<>a.tenant_id OR (b.depth=64 AND b.parent_id IS NOT NULL))
   AND NOT EXISTS(
    SELECT 1 FROM parents b WHERE (b.departed_at IS NULL OR b.user_id=p_actor)
     AND (NOT b.active OR NOT EXISTS(SELECT 1 FROM user_pages up WHERE up.user_id=b.user_id AND up.page_id=p_page))
   )
 )
$$;

REVOKE ALL ON FUNCTION public.veo_branch(uuid),public.veo_descendants(uuid),public.veo_grant_parent(uuid),public.veo_can_page(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.veo_branch(uuid),public.veo_descendants(uuid),public.veo_grant_parent(uuid),public.veo_can_page(uuid,uuid) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611090001_veo_hierarchy_recursion_guards.sql','a93f4bab8e89edaa6a33f7b9fbd8cb476dc53c68f1dff5ee7379de25c08db5a0');

-- FILE: 202611090002_veo_compact_launch_archive.sql SHA256: d2324a8c266cea8a80d9db2b8fe7f3c17982f73439fff03249fb814c5c2bf111

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='10s';

-- Profiles already have versioned storage. A launch must not make a second
-- full copy of every historical profile payload in the immutable archive.
-- Existing archives, original profiles, contacts, tags and finance stay intact.
DO $$
DECLARE
 definition text;
 original_list text := $old$ARRAY['contacts','campaigns','contact_purchases','contact_verified_payments','chatbot_contact_states','contact_profile_snapshots','page_activity_history']$old$;
 compact_list text := $new$ARRAY['contacts','campaigns','contact_purchases','contact_verified_payments','chatbot_contact_states','page_activity_history']$new$;
BEGIN
 SELECT pg_get_functiondef('public.veo_launch(uuid,uuid[])'::regprocedure) INTO definition;
 IF strpos(definition,original_list)>0 THEN
  EXECUTE replace(definition,original_list,compact_list);
 ELSIF strpos(definition,compact_list)=0 THEN
  RAISE EXCEPTION 'Unexpected workspace launch archive definition; inspect before changing';
 END IF;
END $$;

INSERT INTO app_private.schema_migrations(version,description)
VALUES('202611090002','Avoid duplicate historical profile payloads at future workspace launches')
ON CONFLICT(version) DO NOTHING;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611090002_veo_compact_launch_archive.sql','d2324a8c266cea8a80d9db2b8fe7f3c17982f73439fff03249fb814c5c2bf111');

-- FILE: 202611090003_veo_contact_identity_sync.sql SHA256: 2fb3abdb7310557e061a66c54344ff16f8ecde20697dda50427e05923702f579

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='10s';
-- Seeding contact identities must not queue old conversations or manufacture
-- historical stage events. Live webhook writes retain their normal triggers.
DO $$
DECLARE signature text;definition text;
BEGIN
 FOREACH signature IN ARRAY ARRAY['public.veo_queue_contact_source()','public.record_ad_lead_stage_event()'] LOOP
  definition:=pg_get_functiondef(signature::regprocedure);
  IF strpos(definition,'app.veo_contact_identity_seed')=0 THEN
   definition:=regexp_replace(definition,'\mBEGIN\M',$guard$BEGIN
    IF TG_OP='INSERT' AND current_setting('app.veo_contact_identity_seed',true)='true' THEN RETURN NEW;END IF;
   $guard$);
   IF strpos(definition,'app.veo_contact_identity_seed')=0 THEN RAISE EXCEPTION 'Expected contact trigger body missing';END IF;
   EXECUTE definition;
  END IF;
 END LOOP;
END $$;

CREATE FUNCTION public.veo_seed_contact_identities(p_actor uuid,p_page uuid,p_contacts jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE inserted integer;received integer;previous_setting text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM veo_accounts a JOIN users u ON u.id=a.user_id WHERE a.user_id=p_actor AND a.active AND u.is_active AND a.role='owner')
 OR NOT veo_can_page(p_actor,p_page) THEN RAISE EXCEPTION 'Owner Page access required' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_contacts) IS DISTINCT FROM 'array' OR jsonb_array_length(p_contacts)>50 THEN RAISE EXCEPTION 'At most 50 contact identities per request';END IF;
 received:=jsonb_array_length(p_contacts);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_contacts) x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object'
  OR coalesce(x->>'psid','') !~ '^[0-9]{1,40}$' OR length(coalesce(x->>'name',''))>200) THEN RAISE EXCEPTION 'Invalid contact identity';END IF;
 previous_setting:=current_setting('app.veo_contact_identity_seed',true);
 PERFORM set_config('app.veo_contact_identity_seed','true',true);
 INSERT INTO contacts(page_id,psid,name)
 SELECT p_page,x->>'psid',nullif(btrim(x->>'name'),'') FROM (
  SELECT DISTINCT ON(value->>'psid') value AS x FROM jsonb_array_elements(p_contacts)
 ) identities
 ON CONFLICT(page_id,psid) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 PERFORM set_config('app.veo_contact_identity_seed',coalesce(previous_setting,''),true);
 RETURN jsonb_build_object('received',received,'inserted',inserted,'skipped',received-inserted);
END $$;
REVOKE ALL ON FUNCTION public.veo_seed_contact_identities(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.veo_seed_contact_identities(uuid,uuid,jsonb) TO service_role;
INSERT INTO app_private.schema_migrations(version,description) VALUES('202611090003','Bounded owner contact identity sync without historical messages or jobs') ON CONFLICT(version) DO NOTHING;
NOTIFY pgrst,'reload schema';


