-- FILE: 202611100001_veo_storage_protection.sql SHA256: 68c00d332d34483aa561d350881eac5e06a9775795434ceb2b94feac2e723957

CREATE TABLE app_private.veo_storage_state(
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 metrics jsonb NOT NULL DEFAULT '{}',metrics_checked_at timestamptz,metrics_ok_at timestamptz,
 maintenance_at timestamptz,maintenance_cleared integer NOT NULL DEFAULT 0
);
INSERT INTO app_private.veo_storage_state(singleton) VALUES(true);
REVOKE ALL ON app_private.veo_storage_state FROM PUBLIC,anon,authenticated;

CREATE FUNCTION veo_storage_maintenance() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp SET statement_timeout='8s' SET lock_timeout='1s' AS $$
DECLARE cleared integer;BEGIN
 IF NOT pg_try_advisory_xact_lock(hashtext('veo_storage_maintenance')) THEN RETURN jsonb_build_object('skipped',true);END IF;
 WITH retired AS(
  SELECT event_key FROM veo_event_inbox WHERE status='done' AND received_at<now()-interval '7 days' AND payload<>'{}'::jsonb
  ORDER BY received_at,event_key LIMIT 500 FOR UPDATE SKIP LOCKED
 ) UPDATE veo_event_inbox i SET payload='{}'::jsonb FROM retired r WHERE i.event_key=r.event_key;
 GET DIAGNOSTICS cleared=ROW_COUNT;
 DELETE FROM cron.job_run_details WHERE end_time<now()-interval '7 days';
 UPDATE app_private.veo_storage_state SET maintenance_at=clock_timestamp(),maintenance_cleared=cleared WHERE singleton;
 RETURN jsonb_build_object('completed_event_payloads_cleared',cleared,'contacts_deleted',0,'tags_deleted',0,'financial_records_deleted',0,'dedupe_keys_deleted',0);
END $$;

-- Planning and queue delivery can fail independently of this retention job.
DO $migration$ DECLARE definition text;before_sql text:=E'WITH retired AS(SELECT event_key FROM veo_event_inbox WHERE status=''done'' AND received_at<now()-interval ''7 days'' AND payload<>''{}''::jsonb LIMIT 500)\n UPDATE veo_event_inbox i SET payload=''{}''::jsonb FROM retired r WHERE i.event_key=r.event_key;\n GET DIAGNOSTICS cleared=ROW_COUNT;';BEGIN
 definition:=pg_get_functiondef('veo_operations_maintenance()'::regprocedure);
 IF strpos(definition,before_sql)=0 THEN RAISE EXCEPTION 'Unexpected planning maintenance definition';END IF;
 definition:=replace(definition,before_sql,E'cleared:=coalesce((veo_storage_maintenance()->>''completed_event_payloads_cleared'')::integer,0);');
 EXECUTE definition;
END $migration$;

CREATE FUNCTION veo_storage_status() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE state app_private.veo_storage_state;bytes bigint;disk_size bigint;disk_free bigint;status text:='healthy';fresh boolean;maintenance_ok boolean;BEGIN
 SELECT * INTO state FROM app_private.veo_storage_state WHERE singleton;
 bytes:=pg_database_size(current_database());
 fresh:=state.metrics_ok_at>now()-interval '15 minutes' AND state.metrics_checked_at=state.metrics_ok_at;
 maintenance_ok:=coalesce(state.maintenance_at>now()-interval '20 minutes',false) AND EXISTS(SELECT 1 FROM cron.job j WHERE jobname='veo-storage-protection' AND coalesce((to_jsonb(j)->>'active')::boolean,true));
 disk_size:=nullif(state.metrics->>'disk_size_bytes','')::bigint;disk_free:=nullif(state.metrics->>'disk_available_bytes','')::bigint;
 -- 500 MB is the application's conservative data budget, not a disk-size claim.
 IF bytes>=400000000 OR(disk_size>0 AND(disk_free<=268435456 OR disk_free::numeric/disk_size<=0.20)) THEN status:='critical';
 ELSIF bytes>=350000000 OR(disk_size>0 AND(disk_free<=536870912 OR disk_free::numeric/disk_size<=0.30)) THEN status:='warning';
 ELSIF NOT coalesce(fresh,false) THEN status:='unknown';END IF;
 RETURN jsonb_build_object('status',status,'database_bytes',bytes,'database_budget_bytes',500000000,
  'disk_size_bytes',disk_size,'disk_available_bytes',disk_free,'metrics_fresh',coalesce(fresh,false),'metrics_checked_at',state.metrics_checked_at,'metrics_ok_at',state.metrics_ok_at,
  'wal_bytes',state.metrics->'wal_bytes','maintenance_at',state.maintenance_at,'maintenance_cleared',state.maintenance_cleared,
  'maintenance_healthy',maintenance_ok,
  'optional_work_paused',status='critical' OR NOT coalesce(fresh,false) OR NOT maintenance_ok,'checked_at',clock_timestamp());
END $$;

CREATE FUNCTION veo_record_storage_metrics(p_metrics jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE stamp timestamptz:=clock_timestamp();BEGIN
 IF p_metrics IS NULL OR jsonb_typeof(p_metrics)<>'object' OR length(p_metrics::text)>2000 THEN RAISE EXCEPTION 'Invalid storage metrics';END IF;
 IF p_metrics->>'available'='true' THEN
  IF coalesce((p_metrics->>'disk_size_bytes')::numeric,0)<=0 OR coalesce((p_metrics->>'disk_available_bytes')::numeric,-1)<0
    OR(p_metrics->>'disk_available_bytes')::numeric>(p_metrics->>'disk_size_bytes')::numeric THEN RAISE EXCEPTION 'Invalid disk metrics';END IF;
  UPDATE app_private.veo_storage_state SET metrics=jsonb_build_object('disk_size_bytes',(p_metrics->>'disk_size_bytes')::bigint,
   'disk_available_bytes',(p_metrics->>'disk_available_bytes')::bigint,'wal_bytes',(p_metrics->>'wal_bytes')::bigint),metrics_checked_at=stamp,metrics_ok_at=stamp WHERE singleton;
 ELSE UPDATE app_private.veo_storage_state SET metrics_checked_at=stamp WHERE singleton;END IF;
 RETURN veo_storage_status();
END $$;

CREATE FUNCTION veo_owner_storage_health(p_actor uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM veo_accounts WHERE user_id=p_actor AND active AND role='owner') THEN RAISE EXCEPTION 'Owner access required' USING ERRCODE='42501';END IF;
 RETURN veo_storage_status();
END $$;

-- Keep dead tuples reusable sooner without a table rewrite or blocking VACUUM FULL.
ALTER TABLE veo_event_inbox SET(autovacuum_vacuum_scale_factor=0.05,autovacuum_vacuum_threshold=200,autovacuum_analyze_scale_factor=0.05);
ALTER TABLE contacts SET(autovacuum_vacuum_scale_factor=0.10,autovacuum_vacuum_threshold=100);
DO $$ DECLARE job record;BEGIN
 FOR job IN SELECT jobid FROM cron.job WHERE jobname='veo-storage-protection' LOOP PERFORM cron.unschedule(job.jobid);END LOOP;
 PERFORM cron.schedule('veo-storage-protection','*/5 * * * *','SELECT public.veo_storage_maintenance();');
END $$;
REVOKE ALL ON FUNCTION veo_storage_maintenance(),veo_storage_status(),veo_record_storage_metrics(jsonb),veo_owner_storage_health(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_storage_maintenance(),veo_storage_status(),veo_record_storage_metrics(jsonb),veo_owner_storage_health(uuid) TO service_role;
INSERT INTO app_private.schema_migrations(version,description) VALUES('202611100001','Independent bounded retention, physical disk monitoring and optional-work protection') ON CONFLICT(version) DO NOTHING;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611100001_veo_storage_protection.sql','68c00d332d34483aa561d350881eac5e06a9775795434ceb2b94feac2e723957');

-- FILE: 202611100002_veo_telegram_relink.sql SHA256: 05b8e6e418b738000554c12c46e8e99b3098e7a66d3b4f1908b753ebce0e64ce

SET LOCAL lock_timeout='5s';

-- A linked Telegram user may request fresh proof. Consumption still prevents
-- one Telegram identity from being claimed by a different VEO account.
CREATE OR REPLACE FUNCTION veo_issue_telegram_pairing(p_tenant uuid,p_hash text,p_telegram bigint,p_chat bigint,p_username text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM veo_tenants WHERE id=p_tenant AND launch_at IS NOT NULL)
 OR NOT EXISTS(SELECT 1 FROM veo_telegram_groups WHERE tenant_id=p_tenant AND chat_id=p_chat AND active)
 OR p_telegram IS NULL OR p_telegram<=0 OR p_hash IS NULL OR p_hash !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION 'Invalid pairing request' USING ERRCODE='42501';END IF;
 DELETE FROM veo_telegram_pairing_codes WHERE telegram_user_id=p_telegram AND consumed_at IS NULL;
 INSERT INTO veo_telegram_pairing_codes(code_hash,tenant_id,telegram_user_id,chat_id,username,expires_at)
 VALUES(p_hash,p_tenant,p_telegram,p_chat,nullif(p_username,''),now()+interval '10 minutes');
 RETURN jsonb_build_object('expires_at',now()+interval '10 minutes');
END $$;

CREATE FUNCTION veo_relink_telegram_pairing(p_actor uuid,p_hash text,p_expected bigint) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a veo_accounts;c veo_telegram_pairing_codes;previous bigint;owner uuid;old_groups jsonb;
BEGIN
 SELECT * INTO a FROM veo_accounts WHERE user_id=p_actor AND active;
 IF a.user_id IS NULL THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('veo-telegram-groups:'||a.tenant_id::text,0));
 SELECT w.* INTO a FROM veo_accounts w JOIN users u ON u.id=w.user_id AND u.is_active
 WHERE w.user_id=p_actor AND w.active FOR UPDATE OF w;
 SELECT * INTO c FROM veo_telegram_pairing_codes WHERE code_hash=p_hash AND expires_at>now() AND consumed_at IS NULL FOR UPDATE;
 IF a.user_id IS NULL OR c.code_hash IS NULL OR a.tenant_id<>c.tenant_id
 OR NOT EXISTS(SELECT 1 FROM veo_telegram_groups WHERE tenant_id=a.tenant_id AND chat_id=c.chat_id AND active) THEN
  RAISE EXCEPTION 'Pairing code expired or invalid' USING ERRCODE='42501';END IF;
 SELECT telegram_user_id INTO previous FROM veo_worker_mappings WHERE user_id=a.user_id FOR UPDATE;
 IF previous IS NULL OR p_expected IS DISTINCT FROM previous THEN
  RAISE EXCEPTION 'Telegram link changed; refresh your profile' USING ERRCODE='40001';END IF;
 IF EXISTS(SELECT 1 FROM veo_worker_mappings WHERE telegram_user_id=c.telegram_user_id AND user_id<>a.user_id) THEN
  RAISE EXCEPTION 'Telegram account already linked to another user' USING ERRCODE='23505';END IF;
 SELECT owner_id INTO owner FROM veo_tenants WHERE id=a.tenant_id AND launch_at IS NOT NULL;
 IF owner IS NULL THEN RAISE EXCEPTION 'Workspace is inactive' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(chat_id ORDER BY chat_id),'[]') INTO old_groups FROM veo_telegram_memberships WHERE user_id=a.user_id;
 IF previous<>c.telegram_user_id THEN
  -- These are current identity proofs and automatic grants, not the financial
  -- ledger or historical attendance. Manual Page grants remain authoritative.
  DELETE FROM user_pages p USING veo_telegram_auto_grants g WHERE p.user_id=a.user_id AND g.user_id=p.user_id AND g.page_id=p.page_id;
  DELETE FROM veo_telegram_auto_grants WHERE user_id=a.user_id;
  DELETE FROM veo_telegram_memberships WHERE user_id=a.user_id;
  DELETE FROM veo_telegram_auto_states WHERE user_id=a.user_id;
  UPDATE veo_intake_readiness SET status='busy',expires_at=now(),updated_at=clock_timestamp() WHERE user_id=a.user_id;
 ELSE
  DELETE FROM veo_telegram_group_states WHERE user_id=a.user_id AND chat_id=c.chat_id;
  DELETE FROM veo_telegram_auto_states WHERE user_id=a.user_id AND chat_id=c.chat_id;
 END IF;
 UPDATE veo_worker_mappings SET telegram_user_id=c.telegram_user_id WHERE user_id=a.user_id;
 INSERT INTO veo_telegram_memberships(user_id,tenant_id,chat_id,telegram_user_id,verified_at,verified_by)
 VALUES(a.user_id,a.tenant_id,c.chat_id,c.telegram_user_id,clock_timestamp(),owner)
 ON CONFLICT(user_id,chat_id) DO UPDATE SET telegram_user_id=EXCLUDED.telegram_user_id,verified_at=EXCLUDED.verified_at,verified_by=EXCLUDED.verified_by;
 UPDATE veo_accounts SET telegram_username=CASE WHEN lower(c.username) ~ '^[a-z0-9_]{1,32}$' THEN lower(c.username) ELSE NULL END,
 telegram_profile_completed_at=clock_timestamp() WHERE user_id=a.user_id;
 UPDATE veo_telegram_pairing_codes SET consumed_by=a.user_id,consumed_at=clock_timestamp() WHERE code_hash=p_hash;
 DELETE FROM veo_telegram_link_codes WHERE user_id=a.user_id;
 UPDATE veo_telegram_sync_state SET next_sync_at=least(next_sync_at,now()),cursor=0,auto_cursor=0 WHERE tenant_id=a.tenant_id;
 INSERT INTO veo_audit(tenant_id,actor_id,action,entity_id,before_value,after_value)
 VALUES(a.tenant_id,a.user_id,'telegram_self_relink',a.user_id,
 jsonb_build_object('telegram_user_id',previous,'chat_ids',old_groups),
 jsonb_build_object('telegram_user_id',c.telegram_user_id,'chat_id',c.chat_id,'method','dm_pairing'));
 RETURN jsonb_build_object('linked',true,'telegram_user_id',c.telegram_user_id::text);
END $$;
REVOKE ALL ON FUNCTION veo_issue_telegram_pairing(uuid,text,bigint,bigint,text),veo_relink_telegram_pairing(uuid,text,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_issue_telegram_pairing(uuid,text,bigint,bigint,text),veo_relink_telegram_pairing(uuid,text,bigint) TO service_role;
NOTIFY pgrst,'reload schema';


INSERT INTO app_private.suno_workspace_migration_files(filename,sha256) VALUES('202611100002_veo_telegram_relink.sql','05b8e6e418b738000554c12c46e8e99b3098e7a66d3b4f1908b753ebce0e64ce');

-- FILE: 202611100003_veo_distinct_order_paid_steps.sql SHA256: 6a03e7a471ba9eb5b6f522dd5b8d37e60cb9833886f7b3960c923cf0b9c7f78d

SET LOCAL lock_timeout='5s';

-- Order creation and settlement are separate milestones. Existing branch,
-- lead-stage, payment and Telegram checks continue to apply to both receipts.
ALTER FUNCTION veo_receipt_requirements(uuid,uuid,uuid,text,uuid,boolean) RENAME TO veo_receipt_requirements_before_order_steps;
CREATE FUNCTION veo_receipt_requirements(p_actor uuid,p_contact uuid,p_seller uuid,p_kind text,p_order uuid DEFAULT NULL,p_fresh boolean DEFAULT true) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp SET jit=off AS $$
DECLARE result jsonb;blocks jsonb;o veo_order_facts;
BEGIN
 result:=veo_receipt_requirements_before_order_steps(p_actor,p_contact,p_seller,p_kind,p_order,p_fresh);
 blocks:=coalesce(result->'blockers','[]');
 IF p_kind='closed' THEN
  IF p_order IS NULL THEN blocks:=blocks||'"closed_order_required"'::jsonb;
  ELSE
   SELECT * INTO o FROM veo_order_facts WHERE id=p_order;
   IF NOT EXISTS(SELECT 1 FROM veo_business_orders b WHERE b.order_id=o.id AND b.contact_id=p_contact
    AND b.page_id=o.page_id AND b.tenant_id=o.tenant_id AND NOT b.price_conflict AND b.total_minor=o.total_minor AND b.currency=o.currency) THEN
    blocks:=blocks||'"facebook_matching_order_required"'::jsonb;
   END IF;
  END IF;
 END IF;
 SELECT coalesce(jsonb_agg(DISTINCT value),'[]') INTO blocks FROM jsonb_array_elements(blocks) value;
 RETURN result||jsonb_build_object('allowed',jsonb_array_length(blocks)=0,'blockers',blocks);
END $$;
REVOKE ALL ON FUNCTION veo_receipt_requirements(uuid,uuid,uuid,text,uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION veo_receipt_requirements(uuid,uuid,uuid,text,uuid,boolean) TO service_role;

-- A new order may now have its own Closed Deal receipt before settlement.
-- Keep rejecting unrelated earlier deals, while permitting this exact link.
DO $migration$ DECLARE definition text;old_guard text;new_guard text;BEGIN
 old_guard:=$old$IF p_action='payment' AND nullif(p_data->>'closed_deal_id','') IS NOT NULL AND EXISTS(SELECT 1 FROM veo_orders WHERE id=(p_data->>'order_id')::uuid AND deal_mode='new') THEN$old$;
 new_guard:=$new$IF p_action='payment' AND nullif(p_data->>'closed_deal_id','') IS NOT NULL AND EXISTS(SELECT 1 FROM veo_orders sale_order WHERE sale_order.id=(p_data->>'order_id')::uuid AND sale_order.deal_mode='new'
 AND NOT EXISTS(SELECT 1 FROM veo_closed_deals closed_deal WHERE closed_deal.id=(p_data->>'closed_deal_id')::uuid AND closed_deal.order_id=sale_order.id
 AND (closed_deal.tenant_id,closed_deal.page_id,closed_deal.contact_id,closed_deal.seller_id,closed_deal.currency) IS NOT DISTINCT FROM (sale_order.tenant_id,sale_order.page_id,sale_order.contact_id,sale_order.seller_id,sale_order.currency))) THEN$new$;
 definition:=pg_get_functiondef('veo_action_before_receipt_gate(uuid,text,jsonb)'::regprocedure);
 IF strpos(definition,old_guard)=0 THEN RAISE EXCEPTION 'Expected independent-deal payment guard is missing';END IF;
 EXECUTE replace(definition,old_guard,new_guard);
END $migration$;
NOTIFY pgrst,'reload schema';


